 21: class LocationController extends Controller
 22: {
 23:     public function index(Request $request, Branch $branch): AnonymousResourceCollection
 24:     {
 25:         $validated = $request->validate([
 26:             'per_page' => ['sometimes', 'integer', 'min:1', 'max:100'],
 27:         ]);
 28: 
 29:         $locations = $branch->locations()
 30:             ->orderBy('id')
 31:             ->paginate($validated['per_page'] ?? 15)
 32:             ->withQueryString();
 33: 
 34:         return LocationResource::collection($locations);
 35:     }
 36: 
 37:     public function store(StoreLocationRequest $request, Branch $branch): JsonResponse
 38:     {
 39:         $location = $branch->locations()->create($request->validated());
 40: 
 41:         return LocationResource::make($location)->response()->setStatusCode(201);
 42:     }
 43: 
 44:     public function show(Branch $branch, Location $location): LocationResource
 45:     {
 46:         $this->ensureLocationBelongsToBranch($branch, $location);
 47: 
 48:         return LocationResource::make($location);
 49:     }
 50: 
 51:     public function update(UpdateLocationRequest $request, Branch $branch, Location $location): LocationResource
 52:     {
 53:         $this->ensureLocationBelongsToBranch($branch, $location);
 54:         $location->update($request->validated());
 55: 
 56:         return LocationResource::make($location);
 57:     }
 58: 
 59:     public function destroy(Branch $branch, Location $location): JsonResponse|Response
 60:     {
 61:         $this->ensureLocationBelongsToBranch($branch, $location);
 62:         $inventoryTables = $this->inventoryMovementTables();
 63: 
 64:         try {
 65:             $deleted = DB::transaction(function () use ($branch, $location, $inventoryTables): bool {
 66:                 $lockedLocation = Location::query()
 67:                     ->whereKey($location->getKey())
 68:                     ->lockForUpdate()
 69:                     ->firstOrFail();
 70:                 $this->ensureLocationBelongsToBranch($branch, $lockedLocation);
 71: 
 72:                 if ($this->hasInventoryMovements($lockedLocation, $inventoryTables)) {
 73:                     return false;
 74:                 }
 75: 
 76:                 $lockedLocation->delete();
 77: 
 78:                 return true;
 79:             });
 80:         } catch (QueryException $exception) {
 81:             if (! $this->isIntegrityConstraintViolation($exception)) {
 82:                 throw $exception;
 83:             }
 84: 
 85:             return $this->conflictResponse();
 86:         }
 87: 
 88:         if (! $deleted) {
 89:             return $this->conflictResponse();
 90:         }
 91: 
 92:         return response()->noContent();
 93:     }
 94: 
 95:     /**
 96:      * @return list<string>
 97:      */
 98:     private function inventoryMovementTables(): array
 99:     {
100:         $tables = [];
101: 
102:         foreach (['inventory_movements', 'stock_movements', 'inventory_transactions', 'stock_transactions'] as $table) {
103:             if (! Schema::hasTable($table) || ! Schema::hasColumn($table, 'location_id')) {
104:                 continue;
105:             }
106: 
107:             $tables[] = $table;
108:         }
109: 
110:         return $tables;
111:     }
112: 
113:     /**
114:      * @param  list<string>  $tables
115:      */
116:     private function hasInventoryMovements(Location $location, array $tables): bool
117:     {
118:         foreach ($tables as $table) {
119:             if (DB::table($table)->where('location_id', $location->getKey())->exists()) {
120:                 return true;
121:             }
122:         }
123: 
124:         return false;
125:     }
126: 
127:     private function isIntegrityConstraintViolation(QueryException $exception): bool
128:     {
129:         $sqlState = (string) ($exception->errorInfo[0] ?? $exception->getCode());
130: 
131:         return in_array($sqlState, ['23000', '23503'], true);
132:     }
133: 
134:     private function conflictResponse(): JsonResponse
135:     {
136:         return response()->json([
137:             'message' => 'لا يمكن حذف الموقع لارتباطه بحركات مخزنية.',
138:         ], 409);
139:     }
140: 
141:     private function ensureLocationBelongsToBranch(Branch $branch, Location $location): void
142:     {
143:         abort_unless($location->branch_id === $branch->getKey(), 404);
144:     }
145: } 1: <?php
