20: 
21:     /**
22:      * @return array<string, mixed>
23:      */
24:     public function rules(): array
25:     {
26:         $fromBranchId = filter_var($this->input('from_branch_id', $this->route('transfer')?->from_branch_id), FILTER_VALIDATE_INT) ?: 0;
27:         $toBranchId = filter_var($this->input('to_branch_id', $this->route('transfer')?->to_branch_id), FILTER_VALIDATE_INT) ?: 0;
28: 
29:         return [
30:             'from_branch_id' => ['sometimes', 'bail', 'integer', 'min:1', Rule::exists('branches', 'id')->where('is_active', true)],
31:             'to_branch_id' => ['sometimes', 'bail', 'integer', 'min:1', Rule::exists('branches', 'id')->where('is_active', true)],
32:             'notes' => ['sometimes', 'nullable', 'string', 'max:2000'],
33:             'items' => ['sometimes', 'array', 'min:1', 'max:100'],
34:             'items.*.product_variant_id' => ['required_with:items', 'bail', 'integer', 'min:1'],
35:             'items.*.from_location_id' => [
36:                 'nullable', 'bail', 'integer', 'min:1',
37:                 Rule::exists('locations', 'id')->where('branch_id', $fromBranchId),
38:             ],
39:             'items.*.to_location_id' => [
40:                 'nullable', 'bail', 'integer', 'min:1',
41:                 Rule::exists('locations', 'id')->where('branch_id', $toBranchId),
42:             ],
43:             'items.*.requested_qty' => ['required_with:items', 'numeric', 'decimal:0,4', 'gt:0', 'max:99999999.9999'],
44:         ];
45:     }
46: 
47:     public function withValidator(Validator $validator): void
48:     {
49:         $this->addBulkVariantExistsCheck($validator);
50:     }
