11: class UniqueCatalogIdentifier implements ValidationRule
12: {
13:     public function __construct(private string $table, private string $column, private ?int $ignoreId = null) {}
14: 
15:     public function validate(string $attribute, mixed $value, Closure $fail): void
16:     {
17:         if (! is_string($value)) {
18:             return;
19:         }
20:         $exists = DB::table($this->table)->whereRaw('LOWER('.$this->column.') = ?', [strtolower($value)])
21:             ->when($this->ignoreId !== null, fn ($query) => $query->where('id', '!=', $this->ignoreId))->exists();
22:         if ($exists) {
23:             $fail('القيمة مستخدمة بالفعل');
24:         }
25:     }
