 114: function invGenMoves() {
 115:   const out = [];
 116:   const types = Object.keys(INV_MOVE_TYPES);
 117:   const refs = { adj_in: 'ADJ', adj_out: 'ADJ', dmg_mark: 'ADJ', dmg_writeoff: 'ADJ', dmg_restore: 'ADJ', tr_out: 'TRF', tr_in: 'TRF', count: 'CNT', production: 'PRD', sale: 'INV' };
 118:   let seed = 7;
 119:   const rnd = () => { seed = (seed * 9301 + 49297) % 233280; return seed / 233280; };
 120:   for (let i = 0; i < 64; i++) {
 121:     const st = INV_STOCK[Math.floor(rnd() * INV_STOCK.length)];
 122:     const t = types[Math.floor(rnd() * types.length)];
 123:     const mt = INV_MOVE_TYPES[t];
 124:     const qty = st.variantId === 'v9' ? +(rnd() * 40 + 1).toFixed(2) : Math.ceil(rnd() * 24);
 125:     const sign = mt.sign === 0 ? (rnd() > .5 ? 1 : -1) : mt.sign;
 126:     const before = Math.round(st.onHand + rnd() * 30);
 127:     const day = 23 - Math.floor(i / 5);
 128:     const h = String(8 + (i * 7) % 12).padStart(2, '0'), m = String((i * 13) % 60).padStart(2, '0');
 129:     out.push({
 130:       id: 'm' + i, date: `2026-10-${String(day).padStart(2, '0')} ${h}:${m}`,
 131:       ref: `${refs[t]}-2026-${String(1480 - i * 3).padStart(5, '0')}`,
 132:       variantId: st.variantId, branchId: st.branchId, locId: st.locId, type: t,
 133:       qty: sign * qty, before, after: +(before + sign * qty).toFixed(4),
 134:       user: INV_USERS[i % 4], unitCost: invVariant(st.variantId).cost,
 135:       note: ['', 'كرتونة مفتوحة', 'مطابقة رصيد افتتاحي', '', 'تلف أثناء النقل', '', 'طلب فرع'][i % 7],
 136:     });
 137:   }
 138:   return out;
 139: }
 140: const INV_MOVES = invGenMoves();
