 218: function BranchForm({ open, initial, onClose, onSave }) {
 219:   const blank = { name: '', code: '', type: 'branch', phone: '', email: '', address: '', city: '', active: true };
 220:   const [f, setF] = useState(blank);
 221:   const [err, setErr] = useState({});
 222:   const [busy, setBusy] = useState(false);
 223:   const { db } = useInv();
 224:   useEffect(() => { if (open) { setF(initial ? { ...initial } : blank); setErr({}); setBusy(false); } }, [open]);
 225:   const set = (k, v) => setF(p => ({ ...p, [k]: v }));
 226:   const submit = () => {
 227:     const e = {};
 228:     if (!f.name.trim()) e.name = 'الاسم مطلوب';
 229:     if (!f.code.trim()) e.code = 'الكود مطلوب';
 230:     else if (db.branches.some(b => b.code.toLowerCase() === f.code.trim().toLowerCase() && b.id !== f.id)) e.code = 'هذا الكود مستخدم لفرع آخر';
 231:     if (f.email && !/^\S+@\S+\.\S+$/.test(f.email)) e.email = 'صيغة البريد غير صحيحة';
 232:     if (!f.city.trim()) e.city = 'المدينة مطلوبة';
 233:     setErr(e);
 234:     if (Object.keys(e).length) return;
 235:     setBusy(true);
 236:     setTimeout(() => onSave(f), 600);
 237:   };
 238:   return (
 239:     <Modal open={open} onClose={onClose} width="max-w-2xl"
 240:       title={initial ? 'تعديل ' + (initial.type === 'warehouse' ? 'المخزن' : 'الفرع') : 'إضافة فرع أو مخزن'}
 241:       sub="المخزن يُسجَّل كنوع من الفروع ويملك مواقع تخزين خاصة به."
 242:       footer={<>
 243:         <button className="btn btn-dark" onClick={submit} disabled={busy}>
 244:           {busy && <span className="w-3.5 h-3.5 rounded-full border-2 border-current border-t-transparent animate-spin" />}
 245:           {initial ? 'حفظ التعديلات' : 'إضافة'}
 246:         </button>
 247:         <button className="btn btn-soft" onClick={onClose}>إلغاء</button>
 248:       </>}>
 249:       <div className="space-y-4">
 250:         <div>
 251:           <span className="field-label">النوع</span>
 252:           <div className="grid grid-cols-2 gap-2.5">
 253:             {[['branch', 'فرع', 'store', 'نقطة بيع تستقبل العملاء'], ['warehouse', 'مخزن', 'warehouse', 'تخزين وتوزيع فقط']].map(([k, l, ic, d]) => (
 254:               <button key={k} type="button" onClick={() => set('type', k)}
 255:                 className={`rounded-2xl p-3.5 flex items-center gap-3 text-right transition border ${f.type === k ? 'border-[var(--accent-orange)]' : 'border-transparent'}`}
 256:                 style={{ background: f.type === k ? 'var(--accent-orange-light)' : 'var(--bg-subcard)' }}>
 257:                 <span className={`w-9 h-9 rounded-full flex items-center justify-center ${f.type === k ? 'bg-[var(--accent-orange)] text-white' : 'v-icon-well'}`}><Icon n={ic} s={16} /></span>
 258:                 <span><span className="block text-[13px] font-semibold c-primary">{l}</span><span className="block text-[11px] c-secondary">{d}</span></span>
 259:               </button>
 260:             ))}
 261:           </div>
 262:         </div>
 263:         <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
 264:           <Field label="الاسم" req error={err.name}><input className={`inp ${err.name ? 'err' : ''}`} value={f.name} onChange={e => set('name', e.target.value)} placeholder="مثال: فرع مدينة نصر" /></Field>
 265:           <Field label="الكود" req error={err.code} hint="فريد على مستوى النظام"><input className={`inp mono text-left ${err.code ? 'err' : ''}`} value={f.code} onChange={e => set('code', e.target.value.toUpperCase())} placeholder="BR-XXX" /></Field>
 266:           <Field label="الهاتف"><input className="inp num text-left" value={f.phone} onChange={e => set('phone', e.target.value)} placeholder="01xxxxxxxxx" /></Field>
 267:           <Field label="البريد الإلكتروني" error={err.email}><input className={`inp mono text-left ${err.email ? 'err' : ''}`} value={f.email} onChange={e => set('email', e.target.value)} placeholder="branch@company.com" /></Field>
 268:           <Field label="المدينة" req error={err.city}><input className={`inp ${err.city ? 'err' : ''}`} value={f.city} onChange={e => set('city', e.target.value)} /></Field>
 269:           <Field label="العنوان"><input className="inp" value={f.address} onChange={e => set('address', e.target.value)} /></Field>
 270:         </div>
 271:         <div className="v-subcard p-3.5 flex items-center justify-between">
 272:           <div>
 273:             <div className="text-[13px] font-semibold c-primary">الحالة: {f.active ? 'نشط' : 'غير نشط'}</div>
 274:             <div className="text-[11px] c-secondary">الفروع غير النشطة لا تظهر في عمليات التحويل والتسوية.</div>
 275:           </div>
 276:           <Toggle on={f.active} onChange={v => set('active', v)} />
 277:         </div>
 278:       </div>
 279:     </Modal>
 280:   );
 281: }
