 283: function BranchesScreen({ go }) {
 284:   const { db, setDb, toast } = useInv();
 285:   const can = useCan();
 286:   const phase = useLoad('branches');
 287:   const [q, setQ] = useState('');
 288:   const [type, setType] = useState('all');
 289:   const [form, setForm] = useState({ open: false, initial: null });
 290:   const [del, setDel] = useState(null);
 291:   const [delBusy, setDelBusy] = useState(false);
 292:   const [delErr, setDelErr] = useState(null);
 293: 
 294:   const locCount = id => db.locations.filter(l => l.branchId === id).length;
 295:   const rows = db.branches.filter(b => (type === 'all' || b.type === type) && (!q || b.name.includes(q) || b.code.toLowerCase().includes(q.toLowerCase()) || b.city.includes(q)));
 296: 
 297:   const save = f => {
 298:     if (f.id) setDb(d => ({ ...d, branches: d.branches.map(b => b.id === f.id ? f : b) }));
 299:     else setDb(d => ({ ...d, branches: [{ ...f, id: 'b' + Date.now() }, ...d.branches] }));
 300:     setForm({ open: false, initial: null });
 301:     toast(f.id ? 'تم حفظ التعديلات' : 'تمت إضافة ' + (f.type === 'warehouse' ? 'المخزن' : 'الفرع'));
 302:   };
 303:   const doDelete = () => {
 304:     setDelBusy(true); setDelErr(null);
 305:     setTimeout(() => {
 306:       setDelBusy(false);
 307:       const lc = locCount(del.id), sc = INV_STOCK.filter(s => s.branchId === del.id).length;
 308:       if (lc || sc) {
 309:         setDelErr(`لا يمكن حذف «${del.name}» لارتباطه بـ ${lc} موقع تخزين${sc ? ` و ${sc} رصيد مخزون` : ''}. يمكنك تعطيله بدلًا من الحذف. (409 Conflict)`);
 310:         return;
 311:       }
 312:       setDb(d => ({ ...d, branches: d.branches.filter(b => b.id !== del.id) }));
 313:       setDel(null); toast('تم الحذف');
 314:     }, 700);
 315:   };
 316: 
 317:   const counts = { all: db.branches.length, branch: db.branches.filter(b => b.type === 'branch').length, warehouse: db.branches.filter(b => b.type === 'warehouse').length };
 318: 
 319:   return (
 320:     <section className="space-y-5">
 321:       <PageHead title="الفروع والمخازن" sub="سجل نقاط البيع والمخازن ومواقع التخزين التابعة لكل منها."
 322:         actions={<Can perm="branches.manage"><button className="btn btn-dark" onClick={() => setForm({ open: true, initial: null })}><Icon n="plus" s={14} w={2.2} /> إضافة فرع / مخزن</button></Can>} />
 323: 
 324:       <Card>
 325:         <CardHead title="القائمة" meta={phase === 'ready' ? `${rows.length} من ${db.branches.length}` : null}
 326:           right={<>
 327:             <div className="seg">
 328:               {[['all', 'الكل'], ['branch', 'فروع'], ['warehouse', 'مخازن']].map(([k, l]) => (
 329:                 <button key={k} className={type === k ? 'on' : ''} onClick={() => setType(k)}>{l} <span className="num c-muted mr-1">{counts[k]}</span></button>
 330:               ))}
 331:             </div>
 332:             <SearchPill value={q} onChange={setQ} placeholder="الاسم، الكود، المدينة" />
 333:           </>} />
 334:         <Phase phase={phase} cols={7}
 335:           empty={<EmptyState icon="store" title="لا توجد فروع أو مخازن بعد" sub="ابدأ بإضافة المخزن الرئيسي، ثم أضف مواقع التخزين بداخله."
 336:             action={<Can perm="branches.manage"><button className="btn btn-dark btn-sm" onClick={() => setForm({ open: true, initial: null })}><Icon n="plus" s={13} /> إضافة أول فرع</button></Can>} />}>
 337:           {rows.length === 0 ? <EmptyState icon="search" title="لا توجد نتائج" sub="جرّب كلمة بحث أخرى أو غيّر نوع الفلتر." /> : (
 338:             <div className="overflow-x-auto">
 339:               <table className="vt">
 340:                 <thead><tr>
 341:                   <th>الاسم</th><th>الكود</th><th>النوع</th><th>المدينة</th><th>الهاتف</th><th>الحالة</th><th>مواقع التخزين</th><th></th>
 342:                 </tr></thead>
 343:                 <tbody>
 344:                   {rows.map(b => (
 345:                     <tr key={b.id}>
 346:                       <td>
 347:                         <div className="flex items-center gap-2.5">
 348:                           <span className={`w-8 h-8 rounded-full flex items-center justify-center shrink-0 ${b.type === 'warehouse' ? '' : 'v-icon-well'}`} style={b.type === 'warehouse' ? { background: 'var(--accent-orange-light)', color: 'var(--accent-orange)' } : {}}>
 349:                             <Icon n={b.type === 'warehouse' ? 'warehouse' : 'store'} s={14} />
 350:                           </span>
 351:                           <div><div className="font-semibold c-primary">{b.name}</div><div className="text-[11px] c-muted mono">{b.email}</div></div>
 352:                         </div>
 353:                       </td>
 354:                       <td><Sku>{b.code}</Sku></td>
 355:                       <td><TypeBadge type={b.type} /></td>
 356:                       <td className="c-secondary">{b.city}</td>
 357:                       <td className="num c-secondary">{b.phone}</td>
 358:                       <td><ActiveBadge on={b.active} /></td>
 359:                       <td>
 360:                         <button onClick={() => go('locations', { branchId: b.id })} className="flex items-center gap-2 group">
 361:                           <span className="num font-semibold c-primary">{locCount(b.id)}</span>
 362:                           <span className="text-[11.5px] c-orange font-semibold opacity-0 group-hover:opacity-100 transition">فتح ←</span>
 363:                         </button>
 364:                       </td>
 365:                       <td>
 366:                         <div className="flex items-center gap-0.5 justify-end">
 367:                           <button className="icon-btn" title="مواقع التخزين" onClick={() => go('locations', { branchId: b.id })}><Icon n="pin" s={15} /></button>
 368:                           {can('branches.manage') && <>
 369:                             <button className="icon-btn" title="تعديل" onClick={() => setForm({ open: true, initial: b })}><Icon n="edit" s={15} /></button>
 370:                             <button className="icon-btn hover:!text-[var(--badge-red-text)]" title="حذف" onClick={() => { setDel(b); setDelErr(null); }}><Icon n="trash" s={15} /></button>
 371:                           </>}
 372:                         </div>
 373:                       </td>
 374:                     </tr>
 375:                   ))}
 376:                 </tbody>
 377:               </table>
 378:             </div>
 379:           )}
 380:         </Phase>
 381:       </Card>
 382: 
 383:       <BranchForm open={form.open} initial={form.initial} onClose={() => setForm({ open: false, initial: null })} onSave={save} />
 384:       <ConfirmDialog open={!!del} onClose={() => setDel(null)} onConfirm={doDelete} danger busy={delBusy} error={delErr}
 385:         title={`حذف ${del?.type === 'warehouse' ? 'المخزن' : 'الفرع'}؟`} confirmLabel="حذف نهائي"
 386:         body={<>سيتم حذف <b className="c-primary">{del?.name}</b> (<span className="mono">{del?.code}</span>). لا يمكن التراجع عن هذا الإجراء، وسيرفض الخادم الحذف إذا كانت هناك مواقع تخزين أو أرصدة أو حركات مرتبطة.</>} />
 387:     </section>
 388:   );
 389: }
