 391: // ---------------- Storage locations ----------------
 392: function LocationForm({ open, initial, branchId, onClose, onSave }) {
 393:   const { db } = useInv();
 394:   const blank = { name: '', code: '', type: 'shelf', active: true, branchId };
 395:   const [f, setF] = useState(blank);
 396:   const [err, setErr] = useState({});
 397:   useEffect(() => { if (open) { setF(initial ? { ...initial } : blank); setErr({}); } }, [open]);
 398:   const set = (k, v) => setF(p => ({ ...p, [k]: v }));
 399:   const submit = () => {
 400:     const e = {};
 401:     if (!f.name.trim()) e.name = 'الاسم مطلوب';
 402:     if (!f.code.trim()) e.code = 'الكود مطلوب';
 403:     else if (db.locations.some(l => l.branchId === branchId && l.code.toLowerCase() === f.code.trim().toLowerCase() && l.id !== f.id)) e.code = 'الكود مستخدم بالفعل داخل هذا الفرع';
 404:     setErr(e);
 405:     if (!Object.keys(e).length) onSave(f);
 406:   };
 407:   return (
 408:     <Modal open={open} onClose={onClose} title={initial ? 'تعديل موقع التخزين' : 'إضافة موقع تخزين'} sub={`تابع لـ ${invBranch(branchId)?.name || ''}`}
 409:       footer={<><button className="btn btn-dark" onClick={submit}>{initial ? 'حفظ' : 'إضافة'}</button><button className="btn btn-soft" onClick={onClose}>إلغاء</button></>}>
 410:       <div className="space-y-4">
 411:         <div className="grid grid-cols-2 gap-4">
 412:           <Field label="الاسم" req error={err.name}><input className={`inp ${err.name ? 'err' : ''}`} value={f.name} onChange={e => set('name', e.target.value)} placeholder="رف A-01" /></Field>
 413:           <Field label="الكود" req error={err.code} hint="فريد داخل الفرع"><input className={`inp mono text-left ${err.code ? 'err' : ''}`} value={f.code} onChange={e => set('code', e.target.value.toUpperCase())} placeholder="A-01" /></Field>
 414:         </div>
 415:         <div>
 416:           <span className="field-label">النوع</span>
 417:           <div className="grid grid-cols-5 gap-2">
 418:             {Object.entries(INV_LOC_TYPES).map(([k, t]) => (
 419:               <button key={k} type="button" onClick={() => set('type', k)}
 420:                 className={`rounded-xl py-2.5 text-[12px] font-medium transition border ${f.type === k ? 'border-[var(--accent-orange)] c-primary font-semibold' : 'border-transparent c-secondary'}`}
 421:                 style={{ background: f.type === k ? 'var(--accent-orange-light)' : 'var(--bg-subcard)' }}>{t.label}</button>
 422:             ))}
 423:           </div>
 424:         </div>
 425:         <div className="v-subcard p-3.5 flex items-center justify-between">
 426:           <span className="text-[13px] font-semibold c-primary">{f.active ? 'نشط' : 'معطّل'}</span>
 427:           <Toggle on={f.active} onChange={v => set('active', v)} />
 428:         </div>
 429:       </div>
 430:     </Modal>
 431:   );
 432: }
