 434: function LocationsScreen({ go, params }) {
 435:   const { db, setDb, toast } = useInv();
 436:   const can = useCan();
 437:   const phase = useLoad('loc' + params.branchId);
 438:   const br = db.branches.find(b => b.id === params.branchId) || db.branches[0];
 439:   const [form, setForm] = useState({ open: false, initial: null });
 440:   const [del, setDel] = useState(null);
 441:   const [delErr, setDelErr] = useState(null);
 442:   const [tf, setTf] = useState('all');
 443:   const all = db.locations.filter(l => l.branchId === br.id);
 444:   const rows = all.filter(l => tf === 'all' || l.type === tf);
 445: 
 446:   const save = f => {
 447:     if (f.id) setDb(d => ({ ...d, locations: d.locations.map(l => l.id === f.id ? f : l) }));
 448:     else setDb(d => ({ ...d, locations: [...d.locations, { ...f, id: 'l' + Date.now(), branchId: br.id }] }));
 449:     setForm({ open: false, initial: null }); toast('تم حفظ موقع التخزين');
 450:   };
 451:   const toggle = l => { setDb(d => ({ ...d, locations: d.locations.map(x => x.id === l.id ? { ...x, active: !x.active } : x) })); toast(l.active ? 'تم تعطيل الموقع' : 'تم تفعيل الموقع'); };
 452:   const doDelete = () => {
 453:     const stock = INV_STOCK.filter(s => s.locId === del.id);
 454:     if (stock.length) { setDelErr(`الموقع «${del.code}» يحتوي على ${stock.length} رصيد مخزون. انقل الكميات أو عطّل الموقع بدلًا من حذفه. (409 Conflict)`); return; }
 455:     setDb(d => ({ ...d, locations: d.locations.filter(x => x.id !== del.id) })); setDel(null); toast('تم حذف الموقع');
 456:   };
 457: 
 458:   const typeCounts = Object.keys(INV_LOC_TYPES).reduce((a, k) => ({ ...a, [k]: all.filter(l => l.type === k).length }), {});
 459: 
 460:   return (
 461:     <section className="space-y-5">
 462:       <PageHead title="مواقع التخزين" back={{ label: 'الفروع والمخازن', onClick: () => go('branches') }}
 463:         sub={<span className="flex items-center gap-2">{br.name} <span className="mono text-[11.5px] c-muted">{br.code}</span> <TypeBadge type={br.type} /></span>}
 464:         actions={<>
 465:           <Sel value={br.id} onChange={id => id && go('locations', { branchId: id })} options={branchOpts()} className="!rounded-full !py-2 w-56" />
 466:           <Can perm="branches.manage"><button className="btn btn-dark" onClick={() => setForm({ open: true, initial: null })}><Icon n="plus" s={14} w={2.2} /> إضافة موقع</button></Can>
 467:         </>} />
 468: 
 469:       <div className="grid grid-cols-1 lg:grid-cols-12 gap-5">
 470:         <Card className="lg:col-span-4" stagger={2}>
 471:           <div className="v-orange-card rounded-[18px] p-5">
 472:             <div className="flex items-center justify-between">
 473:               <span className="text-[12.5px] font-medium text-white/90">إجمالي المواقع</span>
 474:               <span className="w-7 h-7 rounded-full bg-white/15 flex items-center justify-center"><Icon n="pin" s={14} /></span>
 475:             </div>
 476:             <div className="font-display text-[40px] font-bold num text-right mt-2">{all.length}</div>
 477:             <div className="text-[11.5px] text-white/80">{all.filter(l => l.active).length} نشط · {all.filter(l => !l.active).length} معطّل</div>
 478:           </div>
 479:           <div className="mt-4 space-y-1">
 480:             {Object.entries(INV_LOC_TYPES).map(([k, t]) => (
 481:               <button key={k} onClick={() => setTf(tf === k ? 'all' : k)} className={`w-full flex items-center justify-between px-3 py-2.5 rounded-xl transition ${tf === k ? 'bg-[var(--bg-subcard)]' : 'hover:bg-[var(--bg-subcard)]'}`}>
 482:                 <span className="flex items-center gap-2.5 text-[12.5px] c-primary"><Badge cls={t.cls}>{t.label}</Badge></span>
 483:                 <span className="flex items-center gap-3">
 484:                   <span className="w-20 h-1.5 rounded-full hatched overflow-hidden"><span className="block h-full bg-[var(--accent-orange)] rounded-full" style={{ width: `${all.length ? typeCounts[k] / all.length * 100 : 0}%` }} /></span>
 485:                   <span className="num text-[12px] font-semibold c-primary w-4 text-left">{typeCounts[k]}</span>
 486:                 </span>
 487:               </button>
 488:             ))}
 489:           </div>
 490:         </Card>
 491: 
 492:         <Card className="lg:col-span-8" stagger={3}>
 493:           <CardHead title="المواقع" meta={tf === 'all' ? 'كل الأنواع' : INV_LOC_TYPES[tf].label}
 494:             right={tf !== 'all' && <button className="btn btn-ghost btn-sm" onClick={() => setTf('all')}><Icon n="x" s={12} /> إزالة الفلتر</button>} />
 495:           <Phase phase={phase} cols={5} rows={5}
 496:             empty={<EmptyState icon="pin" title="لا توجد مواقع تخزين في هذا الفرع" sub="أضف رفوفًا ومناطق وخانات لتحديد مكان كل صنف بدقة."
 497:               action={<Can perm="branches.manage"><button className="btn btn-dark btn-sm" onClick={() => setForm({ open: true, initial: null })}><Icon n="plus" s={13} /> إضافة موقع</button></Can>} />}>
 498:             {rows.length === 0 ? <EmptyState icon="pin" title="لا توجد مواقع من هذا النوع" /> : (
 499:               <table className="vt">
 500:                 <thead><tr><th>الاسم</th><th>الكود</th><th>النوع</th><th>الحالة</th><th></th></tr></thead>
 501:                 <tbody>
 502:                   {rows.map(l => (
 503:                     <tr key={l.id} className={l.active ? '' : 'opacity-60'}>
 504:                       <td className="font-semibold c-primary">{l.name}</td>
 505:                       <td><Sku>{l.code}</Sku></td>
 506:                       <td><Badge cls={INV_LOC_TYPES[l.type].cls}>{INV_LOC_TYPES[l.type].label}</Badge></td>
 507:                       <td>
 508:                         <div className="flex items-center gap-2.5">
 509:                           {can('branches.manage') && <Toggle on={l.active} onChange={() => toggle(l)} />}
 510:                           <span className={`text-[11.5px] font-semibold ${l.active ? '' : 'c-muted'}`} style={l.active ? { color: 'var(--badge-green-text)' } : {}}>{l.active ? 'نشط' : 'معطّل'}</span>
 511:                         </div>
 512:                       </td>
 513:                       <td>
 514:                         {can('branches.manage') && (
 515:                           <div className="flex items-center gap-0.5 justify-end">
 516:                             <button className="icon-btn" title="تعديل" onClick={() => setForm({ open: true, initial: l })}><Icon n="edit" s={15} /></button>
 517:                             <button className="icon-btn" title="حذف" onClick={() => { setDel(l); setDelErr(null); }}><Icon n="trash" s={15} /></button>
 518:                           </div>
 519:                         )}
 520:                       </td>
 521:                     </tr>
 522:                   ))}
 523:                 </tbody>
 524:               </table>
 525:             )}
 526:           </Phase>
 527:         </Card>
 528:       </div>
 529: 
 530:       <LocationForm open={form.open} initial={form.initial} branchId={br.id} onClose={() => setForm({ open: false, initial: null })} onSave={save} />
 531:       <ConfirmDialog open={!!del} onClose={() => setDel(null)} onConfirm={doDelete} danger error={delErr} title="حذف موقع التخزين؟" confirmLabel="حذف"
 532:         body={<>سيتم حذف <b className="c-primary">{del?.name}</b> (<span className="mono">{del?.code}</span>) من {br.name}.</>} />
 533:     </section>
 534:   );
 535: }
