 539: const CNT_MAX = 500;
 540: 
 541: function CountsScreen({ go }) {
 542:   const { db } = useInv();
 543:   const phase = useLoad('counts');
 544:   const [create, setCreate] = useState(false);
 545:   return (
 546:     <section className="space-y-5">
 547:       <PageHead title="الجرد" sub="مقارنة الكميات الموجودة فعليًا بالمسجّلة في النظام، ثم اعتماد الفروق كتسويات."
 548:         actions={<Can perm="count.manage"><button className="btn btn-dark" onClick={() => setCreate(true)}><Icon n="plus" s={14} w={2.2} /> جرد جديد</button></Can>} />
 549:       <Card stagger={2}>
 550:         <CardHead title="القائمة" meta={phase === 'ready' ? `${db.counts.length} عملية` : null} />
 551:         <Phase phase={phase} cols={6}
 552:           empty={<EmptyState icon="clipboard" title="لم يتم إنشاء أي جرد بعد" sub="ابدأ جردًا لفرع كامل أو لموقع تخزين محدد."
 553:             action={<Can perm="count.manage"><button className="btn btn-dark btn-sm" onClick={() => setCreate(true)}><Icon n="plus" s={13} /> جرد جديد</button></Can>} />}>
 554:           <table className="vt">
 555:             <thead><tr><th>رقم الجرد</th><th>الفرع</th><th>الموقع</th><th>تقدّم العدّ</th><th>الحالة</th><th>المنشئ</th><th>التاريخ</th><th></th></tr></thead>
 556:             <tbody>
 557:               {db.counts.map(c => {
 558:                 const done = c.lines.filter(l => l.actual !== null).length;
 559:                 return (
 560:                   <tr key={c.id} className="cursor-pointer" onClick={() => go('count', { id: c.id })}>
 561:                     <td><span className="mono text-[12px] font-semibold c-primary">{c.no}</span></td>
 562:                     <td className="c-primary font-medium">{invBranch(c.branchId).name}</td>
 563:                     <td className="mono text-[11.5px] c-secondary">{c.locId ? invLoc(c.locId).code : <span className="c-muted" style={{ fontFamily: 'inherit' }}>كل المواقع</span>}</td>
 564:                     <td>
 565:                       <div className="flex items-center gap-2">
 566:                         <span className="w-20 h-1.5 rounded-full hatched overflow-hidden"><span className="block h-full rounded-full bg-[var(--accent-orange)]" style={{ width: done / c.lines.length * 100 + '%' }} /></span>
 567:                         <span className="num text-[11.5px] c-secondary">{done}/{c.lines.length}</span>
 568:                       </div>
 569:                     </td>
 570:                     <td><Badge cls={INV_CNT_STATUS[c.status].cls} dot>{INV_CNT_STATUS[c.status].label}</Badge></td>
 571:                     <td className="c-secondary">{c.createdBy}</td>
 572:                     <td className="num text-[11.5px] c-secondary">{c.date}</td>
 573:                     <td><Icon n="chevL" s={15} className="c-muted" /></td>
 574:                   </tr>
 575:                 );
 576:               })}
 577:             </tbody>
 578:           </table>
 579:         </Phase>
 580:       </Card>
 581:       <CountCreate open={create} onClose={() => setCreate(false)} go={go} />
 582:     </section>
 583:   );
 584: }
