 586: function CountCreate({ open, onClose, go }) {
 587:   const { setDb, toast } = useInv();
 588:   const [branchId, setBranchId] = useState(null);
 589:   const [locId, setLocId] = useState(null);
 590:   const [note, setNote] = useState('');
 591:   const [mode, setMode] = useState('all');
 592:   const [picked, setPicked] = useState([]);
 593:   const [tried, setTried] = useState(false);
 594:   useEffect(() => { if (open) { setBranchId(null); setLocId(null); setNote(''); setMode('all'); setPicked([]); setTried(false); } }, [open]);
 595: 
 596:   const scope = branchId ? INV_STOCK.filter(s => s.branchId === branchId && (!locId || s.locId === locId)) : [];
 597:   const items = mode === 'all' ? [...new Set(scope.map(s => s.variantId))] : picked;
 598:   const valid = branchId && items.length > 0 && items.length <= CNT_MAX;
 599: 
 600:   const submit = () => {
 601:     setTried(true); if (!valid) return;
 602:     const id = 'c' + Date.now();
 603:     setDb(d => ({ ...d, counts: [{ id, no: 'CNT-2026-000' + (32 + d.counts.length - 3), branchId, locId, status: 'counting', createdBy: 'أحمد سمير', date: '2026-10-23', note,
 604:       lines: items.map(v => ({ variantId: v, system: scope.filter(s => s.variantId === v).reduce((a, s) => a + s.onHand, 0), actual: null })) }, ...d.counts] }));
 605:     toast('تم إنشاء الجرد'); onClose(); go('count', { id });
 606:   };
 607: 
 608:   return (
 609:     <Modal open={open} onClose={onClose} width="max-w-2xl" title="جرد جديد" sub={`حتى ${CNT_MAX} بند عند الإنشاء`}
 610:       footer={<><button className="btn btn-dark" onClick={submit}>إنشاء وبدء العدّ</button><button className="btn btn-soft" onClick={onClose}>إلغاء</button></>}>
 611:       <div className="space-y-4">
 612:         <div className="grid grid-cols-2 gap-4">
 613:           <Field label="الفرع" req error={tried && !branchId ? 'مطلوب' : null}><Sel value={branchId} onChange={v => { setBranchId(v); setLocId(null); setPicked([]); }} placeholder="اختر…" options={branchOpts(b => b.active)} /></Field>
 614:           <Field label="الموقع" hint="اختياري"><Sel value={locId} onChange={setLocId} placeholder={branchId ? 'كل المواقع' : '—'} disabled={!branchId} options={branchId ? locOpts(branchId) : []} /></Field>
 615:         </div>
 616:         <div>
 617:           <span className="field-label">الأصناف</span>
 618:           <div className="seg mb-3">
 619:             <button className={mode === 'all' ? 'on' : ''} onClick={() => setMode('all')}>كل الأصناف في النطاق</button>
 620:             <button className={mode === 'pick' ? 'on' : ''} onClick={() => setMode('pick')}>اختيار أصناف محددة</button>
 621:           </div>
 622:           {mode === 'all' ? (
 623:             <div className="v-subcard p-3.5 flex items-center justify-between">
 624:               <span className="text-[12.5px] c-secondary">{branchId ? 'سيتم إدراج كل SKU له رصيد في النطاق المحدد' : 'اختر الفرع لعرض عدد الأصناف'}</span>
 625:               <span className="num font-display text-[20px] font-bold c-primary">{items.length}</span>
 626:             </div>
 627:           ) : (
 628:             <div className="space-y-2">
 629:               <VariantPicker value={null} onChange={v => v && setPicked(p => p.length < CNT_MAX ? [...p, v] : p)} exclude={picked} placeholder="أضف SKU…" />
 630:               <div className="flex flex-wrap gap-1.5">
 631:                 {picked.map(v => <span key={v} className="badge b-gray !py-1"><span className="mono">{invVariant(v).sku}</span><button onClick={() => setPicked(p => p.filter(x => x !== v))}><Icon n="x" s={11} /></button></span>)}
 632:                 {picked.length === 0 && <span className="text-[11.5px] c-muted">لم تتم إضافة أصناف</span>}
 633:               </div>
 634:             </div>
 635:           )}
 636:           {tried && branchId && items.length === 0 && <div className="text-[11px] mt-1.5" style={{ color: 'var(--badge-red-text)' }}>لا توجد أصناف للجرد</div>}
 637:           <div className="text-[11px] c-muted mt-1.5 num">{items.length} / {CNT_MAX}</div>
 638:         </div>
 639:         <Field label="ملاحظات"><textarea className="inp" rows={2} value={note} onChange={e => setNote(e.target.value)} /></Field>
 640:       </div>
 641:     </Modal>
 642:   );
 643: }
