 645: function CountDetail({ go, params }) {
 646:   const { db, setDb, toast, demoState } = useInv();
 647:   const can = useCan();
 648:   const phase = useLoad('cnt' + params.id);
 649:   const c = db.counts.find(x => x.id === params.id);
 650:   const [vals, setVals] = useState(() => Object.fromEntries((c?.lines || []).map((l, i) => [i, l.actual === null ? '' : String(l.actual)])));
 651:   const [filter, setFilter] = useState('all');
 652:   const [confirm, setConfirm] = useState(false);
 653:   const [busy, setBusy] = useState(false);
 654:   const [err, setErr] = useState(null);
 655:   const [dirty, setDirty] = useState(false);
 656:   if (!c) return null;
 657: 
 658:   const editable = c.status !== 'approved' && can('count.manage');
 659:   const actual = i => vals[i] === '' || vals[i] === undefined ? null : parseFloat(vals[i]);
 660:   const rows = c.lines.map((l, i) => ({ ...l, i, a: actual(i), diff: actual(i) === null ? null : +(actual(i) - l.system).toFixed(4) }));
 661:   const counted = rows.filter(r => r.a !== null).length;
 662:   const shown = rows.filter(r => filter === 'all' || (filter === 'uncounted' && r.a === null) || (filter === 'diff' && r.diff) || (filter === 'match' && r.diff === 0));
 663:   const diffs = rows.filter(r => r.diff);
 664: 
 665:   const saveCounts = () => { setDb(d => ({ ...d, counts: d.counts.map(x => x.id === c.id ? { ...x, status: 'counting', lines: x.lines.map((l, i) => ({ ...l, actual: actual(i) })) } : x) })); setDirty(false); toast('تم حفظ العدّ'); };
 666:   const approve = () => {
 667:     setBusy(true); setErr(null);
 668:     setTimeout(() => {
 669:       setBusy(false);
 670:       if (demoState === 'error') { setErr('تم تنفيذ حركات على بعض الأصناف بعد إنشاء الجرد؛ أعد احتساب كميات النظام قبل الاعتماد. (409)'); return; }
 671:       setDb(d => ({ ...d, counts: d.counts.map(x => x.id === c.id ? { ...x, status: 'approved', lines: x.lines.map((l, i) => ({ ...l, actual: actual(i) })) } : x) }));
 672:       setConfirm(false); toast('تم اعتماد الجرد وترحيل الفروق');
 673:     }, 900);
 674:   };
 675: 
 676:   return (
 677:     <section className="space-y-5">
 678:       <PageHead title={<span className="mono">{c.no}</span>} back={{ label: 'الجرد', onClick: () => go('counts') }}
 679:         sub={<span className="flex items-center gap-2 flex-wrap">{invBranch(c.branchId).name} <span className="c-muted">·</span> {c.locId ? <span className="mono">{invLoc(c.locId).code}</span> : 'كل المواقع'} <Badge cls={INV_CNT_STATUS[c.status].cls} dot>{INV_CNT_STATUS[c.status].label}</Badge></span>}
 680:         actions={c.status !== 'approved' && <>
 681:           {editable && <button className="btn btn-soft" disabled={!dirty} onClick={saveCounts}>حفظ العدّ</button>}
 682:           {can('count.approve')
 683:             ? <button className="btn btn-orange" onClick={() => { setErr(null); setConfirm(true); }} disabled={counted < rows.length}><Icon n="check" s={14} w={2.2} /> اعتماد الجرد</button>
 684:             : <Can perm="count.approve" mode="الاعتماد يتطلب صلاحية" />}
 685:         </>} />
 686: 
 687:       <Phase phase={phase} cols={5} rows={5} empty={<Card><EmptyState icon="clipboard" title="لا توجد بنود في هذا الجرد" /></Card>}>
 688:         <div className="grid grid-cols-2 lg:grid-cols-4 gap-3.5 stagger-item stagger-2">
 689:           <KPI hot label="تم العدّ" icon="clipboard" value={`${counted}/${rows.length}`} sub={counted < rows.length ? `${rows.length - counted} بند لم يُعدّ بعد` : 'اكتمل العدّ'} />
 690:           <KPI label="مطابق" icon="check" value={rows.filter(r => r.diff === 0).length} />
 691:           <KPI label="بفروق" icon="alert" value={diffs.length} />
 692:           <KPI label="صافي الفرق" icon="sliders" value={(() => { const n = diffs.reduce((a, r) => a + r.diff, 0); return (n > 0 ? '+' : '') + invFmt(n); })()} sub="بالوحدات" />
 693:         </div>
 694: 
 695:         <Card stagger={3}>
 696:           <CardHead title="جدول العدّ" right={
 697:             <div className="seg">
 698:               {[['all', 'الكل'], ['uncounted', 'لم يُعدّ'], ['diff', 'بفروق'], ['match', 'مطابق']].map(([k, l]) => <button key={k} className={filter === k ? 'on' : ''} onClick={() => setFilter(k)}>{l}</button>)}
 699:             </div>} />
 700:           {counted < rows.length && c.status !== 'approved' && <div className="mb-3"><InlineAlert kind="amber" icon="info" title="الحقل الفارغ ≠ صفر">الخانة الفارغة المظللة تعني «لم يتم العدّ». إذا كان الصنف غير موجود فعليًا اكتب 0 أو اضغط «صفر».</InlineAlert></div>}
 701:           {shown.length === 0 ? <EmptyState icon="filter" title="لا توجد بنود بهذا الفلتر" /> : (
 702:             <table className="vt">
 703:               <thead><tr><th>SKU</th><th>الصنف</th><th className="t-num">كمية النظام</th><th className="t-num" style={{ width: 200 }}>الكمية الفعلية</th><th className="t-num">الفرق</th><th>الحالة</th></tr></thead>
 704:               <tbody>
 705:                 {shown.map(r => (
 706:                   <tr key={r.i}>
 707:                     <td><Sku id={r.variantId} /></td>
 708:                     <td><VariantCell id={r.variantId} showBarcode /></td>
 709:                     <td className="t-num num c-secondary">{invFmt(r.system)}</td>
 710:                     <td className="t-num">
 711:                       {editable ? (
 712:                         <div className="flex items-center gap-1.5 justify-end">
 713:                           {r.a === null && <button className="btn btn-ghost btn-sm !px-2 !py-1 text-[11px]" onClick={() => { setVals(v => ({ ...v, [r.i]: '0' })); setDirty(true); }}>صفر</button>}
 714:                           <div className={`rounded-[10px] w-28 ${r.a === null ? 'uncounted' : ''}`}>
 715:                             <NumInput small value={vals[r.i]} placeholder="لم يُعدّ" onChange={v => { setVals(x => ({ ...x, [r.i]: v })); setDirty(true); }} className={r.a === null ? '!bg-transparent' : ''} />
 716:                           </div>
 717:                           {r.a !== null && <button className="icon-btn !w-6 !h-6" title="مسح (لم يُعدّ)" onClick={() => { setVals(v => ({ ...v, [r.i]: '' })); setDirty(true); }}><Icon n="x" s={11} /></button>}
 718:                         </div>
 719:                       ) : <span className="num font-semibold c-primary">{r.a === null ? <span className="c-muted font-normal">لم يُعدّ</span> : invFmt(r.a)}</span>}
 720:                     </td>
 721:                     <td className="t-num num font-bold" style={{ color: r.diff === null ? 'var(--text-muted)' : r.diff > 0 ? 'var(--badge-green-text)' : r.diff < 0 ? 'var(--badge-red-text)' : 'var(--text-secondary)' }}>
 722:                       {r.diff === null ? '—' : r.diff === 0 ? '0' : (r.diff > 0 ? '+' : '−') + invFmt(Math.abs(r.diff))}
 723:                     </td>
 724:                     <td>{r.a === null ? <Badge cls="b-gray">لم يُعدّ</Badge> : r.a === 0 ? <Badge cls={r.diff ? 'b-red' : 'b-green'}>صفر فعلي</Badge> : r.diff === 0 ? <Badge cls="b-green">مطابق</Badge> : <Badge cls={r.diff > 0 ? 'b-blue' : 'b-red'}>{r.diff > 0 ? 'زيادة' : 'عجز'}</Badge>}</td>
 725:                   </tr>
 726:                 ))}
 727:               </tbody>
 728:             </table>
 729:           )}
 730:         </Card>
 731:       </Phase>
 732: 
 733:       <ConfirmDialog open={confirm} onClose={() => setConfirm(false)} onConfirm={approve} busy={busy} error={err} title="اعتماد الجرد" confirmLabel="اعتماد وترحيل الفروق"
 734:         body={<>سيتم ترحيل <b className="num c-primary">{diffs.length}</b> فرق كحركات «فرق جرد» وتحديث الأرصدة. لا يمكن تعديل العدّ بعد الاعتماد.</>} />
 735:     </section>
 736:   );
 737: }
