 755:         actions={allowed ? <button className="btn btn-dark" onClick={() => setOpen(true)}><Icon n="plus" s={14} w={2.2} /> تسجيل استلام</button>
 756:           : <span className="inline-flex items-center gap-1.5 text-[12px] c-muted px-3.5 py-2 rounded-full v-pill-surface"><Icon n="lock" s={12} /> يتطلب صلاحية تسوية المخزون وعرض التكلفة</span>} />
 757:       <Card stagger={2}>
 758:         <CardHead title="سجل الاستلامات" meta={phase === 'ready' ? `${db.production.length} استلام` : null} />
 759:         <Phase phase={phase} cols={6}
 760:           empty={<EmptyState icon="factory" title="لا توجد استلامات إنتاج" sub="عند وصول دفعة من التصنيع سجّلها هنا لتُضاف إلى رصيد المخزن." action={allowed && <button className="btn btn-dark btn-sm" onClick={() => setOpen(true)}><Icon n="plus" s={13} /> تسجيل استلام</button>} />}>
 761:           <table className="vt">
 762:             <thead><tr><th>رقم الاستلام</th><th>رقم الدفعة</th><th>الفرع</th><th>الموقع</th><th className="t-num">البنود</th><th className="t-num">إجمالي الكمية</th>{can('cost.view') && <th className="t-num">إجمالي التكلفة</th>}<th>المنفّذ</th><th>التاريخ</th></tr></thead>
 763:             <tbody>
 764:               {db.production.map(p => (
 765:                 <tr key={p.id} className="cursor-pointer" onClick={() => setView(p)}>
 766:                   <td><span className="mono text-[12px] font-semibold c-orange">{p.no}</span></td>
 767:                   <td><Sku>{p.batch}</Sku></td>
 768:                   <td className="c-primary font-medium">{invBranch(p.branchId).name}</td>
 769:                   <td className="mono text-[11.5px] c-secondary">{p.locId ? invLoc(p.locId).code : '—'}</td>
 770:                   <td className="t-num num c-secondary">{p.lines.length}</td>
 771:                   <td className="t-num num font-semibold c-primary">{invFmt(p.lines.reduce((a, l) => a + l.qty, 0))}</td>
 772:                   {can('cost.view') && <td className="t-num num c-primary">{invMoney(p.lines.reduce((a, l) => a + l.qty * l.cost, 0))}</td>}
 773:                   <td className="c-secondary">{p.user}</td>
 774:                   <td className="num text-[11.5px] c-secondary">{p.date}</td>
 775:                 </tr>
 776:               ))}
 777:             </tbody>
 778:           </table>
 779:         </Phase>
 780:       </Card>
 781:       <ProductionForm open={open} onClose={() => setOpen(false)} onSave={p => { setDb(d => ({ ...d, production: [p, ...d.production] })); setOpen(false); toast('تم تسجيل استلام الإنتاج'); }} />
 782:       <Modal open={!!view} onClose={() => setView(null)} width="max-w-xl" title={view?.no} sub={view && `دفعة ${view.batch} · ${invBranch(view.branchId).name}`}>
 783:         {view && <table className="vt mb-4"><thead><tr><th>SKU</th><th>الصنف</th><th className="t-num">الكمية</th><th className="t-num">تكلفة الوحدة</th></tr></thead>
 784:           <tbody>{view.lines.map((l, i) => <tr key={i}><td><Sku id={l.variantId} /></td><td><VariantCell id={l.variantId} /></td><td className="t-num num font-semibold">{l.qty}</td><td className="t-num num">{invMoney(l.cost)}</td></tr>)}</tbody></table>}
 785:       </Modal>
 786:     </section>
 787:   );
 788: }
