 853: // ============ 3. Stock balances · 4. Adjustment · 5. Movements ============
 854: 
 855: function FilterBar({ children, onReset, active }) {
 856:   return (
 857:     <div className="v-subcard p-3 flex flex-wrap items-end gap-2.5 mb-4">
 858:       {children}
 859:       {active > 0 && <button onClick={onReset} className="btn btn-ghost btn-sm mb-0.5"><Icon n="x" s={12} /> مسح ({active})</button>}
 860:     </div>
 861:   );
 862: }
 863: const FItem = ({ label, w = 'w-44', children }) => (
 864:   <div className={w}><div className="text-[10.5px] font-medium c-muted mb-1 pr-1">{label}</div>{children}</div>
 865: );
 866: 
 867: // Product-level then variant-level filter (product narrows the variant list)
 868: function ProductVariantFilters({ f, set }) {
 869:   const prod = INV_PRODUCTS.find(p => p.id === f.productId);
 870:   return <>
 871:     <FItem label="المنتج"><Sel small value={f.productId} onChange={v => set({ productId: v, variantId: null })} placeholder="كل المنتجات" options={INV_PRODUCTS.map(p => ({ value: p.id, label: p.name }))} className="!bg-[var(--bg-card)]" /></FItem>
 872:     <FItem label="المتغير / SKU"><Sel small value={f.variantId} onChange={v => set({ variantId: v })} placeholder={prod ? 'كل المتغيرات' : 'اختر منتجًا أولًا'} disabled={!prod}
 873:       options={(prod?.variants || []).map(v => ({ value: v.id, label: `${v.sku} · ${v.attrs}` }))} className="!bg-[var(--bg-card)]" /></FItem>
 874:   </>;
 875: }
 876: 
 877: function BranchLocFilters({ f, set }) {
 878:   return <>
 879:     <FItem label="الفرع"><Sel small value={f.branchId} onChange={v => set({ branchId: v, locId: null })} placeholder="كل الفروع" options={branchOpts()} className="!bg-[var(--bg-card)]" /></FItem>
 880:     <FItem label="الموقع" w="w-40"><Sel small value={f.locId} onChange={v => set({ locId: v })} placeholder={f.branchId ? 'كل المواقع' : 'اختر فرعًا أولًا'} disabled={!f.branchId} options={f.branchId ? locOpts(f.branchId) : []} className="!bg-[var(--bg-card)]" /></FItem>
 881:   </>;
 882: }
