 884: // ---------------- 3. Stock balances ----------------
 885: function StockScreen({ go }) {
 886:   const can = useCan();
 887:   const phase = useLoad('stock');
 888:   const [f, setF] = useState({ branchId: null, locId: null, productId: null, variantId: null, low: false });
 889:   const set = p => setF(x => ({ ...x, ...p }));
 890:   const [adj, setAdj] = useState(null);
 891: 
 892:   const rows = INV_STOCK.filter(s => {
 893:     const v = invVariant(s.variantId);
 894:     return (!f.branchId || s.branchId === f.branchId) && (!f.locId || s.locId === f.locId)
 895:       && (!f.productId || v.productId === f.productId) && (!f.variantId || s.variantId === f.variantId)
 896:       && (!f.low || s.available <= s.reorder);
 897:   });
 898:   const active = ['branchId', 'locId', 'productId', 'variantId'].filter(k => f[k]).length + (f.low ? 1 : 0);
 899:   const lowCount = INV_STOCK.filter(s => s.available <= s.reorder).length;
 900:   const sum = k => rows.reduce((a, s) => a + s[k], 0);
 901: 
 902:   return (
 903:     <section className="space-y-5">
 904:       <PageHead title="أرصدة المخزون" sub="الكميات الحالية لكل SKU في كل فرع وموقع. لتغيير أي كمية استخدم عملية مخزنية."
 905:         actions={<Can perm="stock.adjust"><button className="btn btn-dark" onClick={() => go('adjust')}><Icon n="sliders" s={14} /> تسوية جديدة</button></Can>} />
 906: 
 907:       <div className="grid grid-cols-2 lg:grid-cols-4 gap-3.5 stagger-item stagger-2">
 908:         <KPI hot label="المتاح" icon="box" value={phase === 'ready' ? invFmt(sum('available'), 2) : '—'} sub={`${rows.length} سطر رصيد`} />
 909:         <KPI label="المحجوز" icon="lock" value={phase === 'ready' ? invFmt(sum('reserved'), 2) : '—'} sub="لطلبات مفتوحة" />
 910:         <KPI label="قيد النقل" icon="truck" value={phase === 'ready' ? invFmt(sum('inTransit'), 2) : '—'} sub="في تحويلات مشحونة" />
 911:         <button onClick={() => set({ low: !f.low })} className="text-right">
 912:           <KPI label="تحت حد إعادة الطلب" icon="alert" value={phase === 'ready' ? lowCount : '—'} sub={f.low ? 'الفلتر مفعّل · اضغط للإلغاء' : 'اضغط لعرضها فقط'} />
 913:         </button>
 914:       </div>
 915: 
 916:       <Card stagger={3}>
 917:         <CardHead title="الأرصدة" meta={phase === 'ready' ? `${rows.length} سطر` : null}
 918:           right={<span className="text-[11.5px] c-muted flex items-center gap-1.5"><Icon n="eye" s={13} /> للعرض فقط</span>} />
 919:         <FilterBar active={active} onReset={() => setF({ branchId: null, locId: null, productId: null, variantId: null, low: false })}>
 920:           <BranchLocFilters f={f} set={set} />
 921:           <ProductVariantFilters f={f} set={set} />
 922:           <label className="flex items-center gap-2.5 px-3 py-2 rounded-full cursor-pointer mb-0.5" style={{ background: f.low ? 'var(--accent-orange-light)' : 'var(--bg-card)' }}>
 923:             <Toggle on={f.low} onChange={v => set({ low: v })} />
 924:             <span className="text-[12px] font-medium c-primary">المخزون المنخفض فقط</span>
 925:           </label>
 926:         </FilterBar>
 927:         <Phase phase={phase} cols={10} rows={7}
 928:           empty={<EmptyState icon="box" title="لا توجد أرصدة مسجّلة بعد" sub="سجّل الكميات الافتتاحية عن طريق تسوية زيادة مع سبب واضح مثل «رصيد افتتاحي»."
 929:             action={<Can perm="stock.adjust"><button className="btn btn-dark btn-sm" onClick={() => go('adjust')}><Icon n="plus" s={13} /> إدخال رصيد افتتاحي</button></Can>} />}>
 930:           {rows.length === 0 ? <EmptyState icon="filter" title="لا توجد أرصدة تطابق الفلاتر" sub="غيّر الفلاتر أو امسحها لعرض كل الأرصدة." /> : (
 931:             <div className="overflow-x-auto -mx-1 px-1">
 932:               <table className="vt">
 933:                 <thead><tr>
 934:                   <th>المنتج</th><th>SKU</th><th>الباركود</th><th>الفرع</th><th>الموقع</th>
 935:                   <th className="t-num">الموجود</th><th className="t-num">المحجوز</th><th className="t-num">التالف</th><th className="t-num">قيد النقل</th><th className="t-num">المتاح</th><th className="t-num">حد الطلب</th><th>آخر تحديث</th><th></th>
 936:                 </tr></thead>
 937:                 <tbody>
 938:                   {rows.map(s => {
 939:                     const low = s.available <= s.reorder;
 940:                     const pct = Math.min(100, s.reorder ? s.available / (s.reorder * 2) * 100 : 100);
 941:                     return (
 942:                       <tr key={s.id}>
 943:                         <td><VariantCell id={s.variantId} /></td>
 944:                         <td><Sku id={s.variantId} /></td>
 945:                         <td className="mono text-[11.5px] c-secondary">{invVariant(s.variantId).barcode}</td>
 946:                         <td className="c-secondary">{invBranch(s.branchId).name}</td>
 947:                         <td><span className="mono text-[11.5px] c-secondary">{invLoc(s.locId).code}</span></td>
 948:                         <td className="t-num num font-semibold c-primary">{invFmt(s.onHand)}</td>
 949:                         <td className="t-num num c-secondary">{invFmt(s.reserved)}</td>
 950:                         <td className="t-num num" style={{ color: s.damaged ? 'var(--badge-red-text)' : 'var(--text-muted)' }}>{invFmt(s.damaged)}</td>
 951:                         <td className="t-num num" style={{ color: s.inTransit ? 'var(--badge-blue-text)' : 'var(--text-muted)' }}>{invFmt(s.inTransit)}</td>
 952:                         <td className="t-num">
 953:                           <div className="flex flex-col items-end gap-1">
 954:                             <span className={`num font-bold ${low ? '' : 'c-primary'}`} style={low ? { color: 'var(--accent-orange)' } : {}}>{invFmt(s.available)}</span>
 955:                             <span className="w-16 h-1 rounded-full hatched overflow-hidden flex justify-end" style={{ direction: 'ltr' }}>
 956:                               <span className="block h-full rounded-full" style={{ width: pct + '%', background: low ? 'var(--accent-orange)' : 'var(--text-primary)' }} />
 957:                             </span>
 958:                           </div>
 959:                         </td>
 960:                         <td className="t-num num c-muted">{invFmt(s.reorder)}</td>
 961:                         <td className="num text-[11.5px] c-muted">{s.updated}</td>
 962:                         <td>
 963:                           <div className="flex items-center gap-0.5 justify-end">
 964:                             <button className="icon-btn" title="حركات الصنف" onClick={() => go('moves', { variantId: s.variantId, productId: invVariant(s.variantId).productId, branchId: s.branchId })}><Icon n="history" s={15} /></button>
 965:                             {can('stock.adjust') && <button className="icon-btn" title="تسوية" onClick={() => go('adjust', { branchId: s.branchId, locId: s.locId, variantId: s.variantId })}><Icon n="sliders" s={15} /></button>}
 966:                           </div>
 967:                         </td>
 968:                       </tr>
 969:                     );
 970:                   })}
 971:                 </tbody>
 972:               </table>
 973:             </div>
 974:           )}
 975:         </Phase>
 976:       </Card>
 977:     </section>
 978:   );
 979: }
 980: 
 981: // ---------------- 4. Adjustment ----------------
 982: const ADJ_TYPES = {
 983:   increase:   { label: 'زيادة',              cls: 'b-green', sign: '+' },
 984:   decrease:   { label: 'نقصان',              cls: 'b-red',   sign: '−' },
 985:   dmg_mark:   { label: 'تسجيل تالف',         cls: 'b-amber', sign: '→' },
 986:   dmg_write:  { label: 'إعدام تالف',         cls: 'b-red',   sign: '×' },
 987:   dmg_restore:{ label: 'استرجاع من التالف',  cls: 'b-blue',  sign: '←' },
 988: };
 989: const ADJ_MAX = 100;
 990: let __adjLineId = 1;
 991: const newAdjLine = (p = {}) => ({ key: __adjLineId++, variantId: null, type: 'increase', qty: '', reason: '', ...p });
 992: 
 993: function AdjustScreen({ go, params }) {
 994:   const { toast, demoState } = useInv();
 995:   const can = useCan();
 996:   const [branchId, setBranchId] = useState(params.branchId || null);
 997:   const [locId, setLocId] = useState(params.locId || null);
 998:   const [lines, setLines] = useState(() => [newAdjLine(params.variantId ? { variantId: params.variantId } : {})]);
 999:   const [tried, setTried] = useState(false);
1000:   const [confirm, setConfirm] = useState(false);
1001:   const [busy, setBusy] = useState(false);
1002:   const [srvErr, setSrvErr] = useState(null);
1003:   const [opening, setOpening] = useState(false);
1004: 
1005:   if (!can('stock.adjust')) return <NoPerm title="تسوية المخزون" perm="تسوية المخزون" go={go} />;
1006: 
1007:   const upd = (key, p) => setLines(ls => ls.map(l => l.key === key ? { ...l, ...p } : l));
1008:   const lineErr = l => {
1009:     const e = {};
1010:     if (!l.variantId) e.variantId = true;
1011:     const q = parseFloat(l.qty);
1012:     if (!l.qty || !(q > 0)) e.qty = 'كمية موجبة';
1013:     if (!l.reason.trim()) e.reason = true;
1014:     return e;
1015:   };
1016:   const errs = lines.map(lineErr);
1017:   const valid = branchId && errs.every(e => !Object.keys(e).length);
1018:   const dupes = lines.filter((l, i) => l.variantId && lines.findIndex(x => x.variantId === l.variantId && x.type === l.type) !== i).length;
1019: 
1020:   const stockOf = vid => INV_STOCK.find(s => s.variantId === vid && s.branchId === branchId && (!locId || s.locId === locId));
1021: 
1022:   const applyOpening = on => {
1023:     setOpening(on);
1024:     setLines(ls => ls.map(l => on ? { ...l, type: 'increase', reason: l.reason || 'رصيد افتتاحي' } : l));
1025:   };
1026: 
1027:   const execute = () => {
1028:     setBusy(true); setSrvErr(null);
1029:     setTimeout(() => {
1030:       setBusy(false);
1031:       if (demoState === 'error') { setSrvErr('الكمية المطلوب خصمها في البند ٢ أكبر من الرصيد المتاح (Insufficient stock · 422).'); return; }
1032:       setConfirm(false); toast(`تم تنفيذ التسوية · ${lines.length} بند`);
1033:       go('moves', { branchId });
1034:     }, 900);
1035:   };
1036: 
1037:   const totals = Object.keys(ADJ_TYPES).map(k => ({ k, n: lines.filter(l => l.type === k && l.variantId).length })).filter(x => x.n);
1038: 
1039:   return (
1040:     <section className="space-y-5">
1041:       <PageHead title="تسوية المخزون" back={{ label: 'أرصدة المخزون', onClick: () => go('stock') }}
1042:         sub="زيادة أو خصم كميات، أو نقلها من وإلى التالف. التسوية تُنفَّذ كعملية واحدة وتنعكس فورًا على الأرصدة والحركات." />
1043: 
1044:       <div className="grid grid-cols-1 lg:grid-cols-12 gap-5 items-start">
1045:         <div className="lg:col-span-9 space-y-5">
1046:           <Card stagger={2}>
1047:             <CardHead title="بيانات العملية" />
1048:             <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
1049:               <Field label="الفرع / المخزن" req error={tried && !branchId ? 'اختر الفرع' : null}>
1050:                 <Sel value={branchId} onChange={v => { setBranchId(v); setLocId(null); }} placeholder="اختر…" options={branchOpts(b => b.active)} className={tried && !branchId ? 'err' : ''} />
1051:               </Field>
1052:               <Field label="موقع التخزين" hint="اختياري — يطبَّق على كل البنود">
1053:                 <Sel value={locId} onChange={setLocId} placeholder={branchId ? 'بدون موقع محدد' : 'اختر الفرع أولًا'} disabled={!branchId} options={branchId ? locOpts(branchId) : []} />
1054:               </Field>
1055:               <div>
1056:                 <span className="field-label">إدخال رصيد افتتاحي</span>
1057:                 <label className="v-subcard px-3.5 py-2 flex items-center justify-between cursor-pointer" style={{ borderRadius: 12 }}>
1058:                   <span className="text-[12px] c-secondary">كل البنود = زيادة</span>
1059:                   <Toggle on={opening} onChange={applyOpening} />
1060:                 </label>
1061:               </div>
1062:             </div>
1063:             {opening && <div className="mt-4"><InlineAlert kind="blue" icon="info" title="رصيد افتتاحي">تُسجَّل الكميات الافتتاحية حاليًا كتسوية زيادة. اكتب سببًا واضحًا لكل بند حتى يسهل تتبّعها في سجل الحركات.</InlineAlert></div>}
1064:           </Card>
1065: 
1066:           <Card stagger={3}>
1067:             <CardHead title="البنود" meta={<span className="num">{lines.length} / {ADJ_MAX}</span>}
1068:               right={<button className="btn btn-soft btn-sm" disabled={lines.length >= ADJ_MAX} onClick={() => setLines(ls => [...ls, newAdjLine(opening ? { reason: 'رصيد افتتاحي' } : {})])}><Icon n="plus" s={13} /> إضافة بند</button>} />
1069:             {dupes > 0 && <div className="mb-3"><InlineAlert kind="amber" title="بنود مكررة">يوجد {dupes} بند مكرر بنفس SKU ونفس نوع التسوية — سيتم دمجها عند التنفيذ.</InlineAlert></div>}
1070:             <div className="overflow-x-auto">
1071:               <table className="vt">
1072:                 <thead><tr><th className="w-8">#</th><th style={{ minWidth: 280 }}>المنتج / المتغير</th><th style={{ minWidth: 170 }}>نوع التسوية</th><th style={{ minWidth: 120 }}>الكمية</th><th style={{ minWidth: 200 }}>السبب</th><th></th></tr></thead>
1073:                 <tbody>
1074:                   {lines.map((l, i) => {
1075:                     const e = tried ? errs[i] : {};
1076:                     const st = l.variantId && branchId ? stockOf(l.variantId) : null;
1077:                     return (
1078:                       <tr key={l.key} className="align-top">
1079:                         <td className="num c-muted pt-4">{i + 1}</td>
1080:                         <td>
1081:                           <div className={e.variantId ? 'rounded-[12px] ring-1 ring-[var(--badge-red-text)]' : ''}><VariantPicker small value={l.variantId} onChange={v => upd(l.key, { variantId: v })} /></div>
1082:                           {st && <div className="text-[10.5px] c-muted mt-1 pr-1">المتاح <span className="num c-primary font-semibold">{invFmt(st.available)}</span> · التالف <span className="num">{invFmt(st.damaged)}</span></div>}
1083:                           {l.variantId && branchId && !st && <div className="text-[10.5px] c-muted mt-1 pr-1">لا يوجد رصيد حالي في هذا الفرع</div>}
1084:                         </td>
1085:                         <td><Sel small value={l.type} onChange={v => upd(l.key, { type: v || 'increase' })} options={Object.entries(ADJ_TYPES).map(([k, t]) => ({ value: k, label: t.label }))} /></td>
1086:                         <td>
1087:                           <NumInput small value={l.qty} onChange={v => upd(l.key, { qty: v })} err={e.qty} placeholder="0.0000" />
1088:                           {e.qty && <div className="text-[10.5px] mt-1" style={{ color: 'var(--badge-red-text)' }}>{e.qty}</div>}
1089:                         </td>
1090:                         <td><input className={`inp inp-sm ${e.reason ? 'err' : ''}`} value={l.reason} onChange={ev => upd(l.key, { reason: ev.target.value })} placeholder="مثال: كسر أثناء التفريغ" /></td>
1091:                         <td className="pt-3"><button className="icon-btn" disabled={lines.length === 1} onClick={() => setLines(ls => ls.filter(x => x.key !== l.key))}><Icon n="trash" s={14} /></button></td>
1092:                       </tr>
1093:                     );
1094:                   })}
1095:                 </tbody>
1096:               </table>
1097:             </div>
1098:             <div className="mt-3 text-[11px] c-muted flex items-center gap-1.5"><Icon n="info" s={12} /> الكميات موجبة دائمًا وتقبل حتى 4 منازل عشرية. اتجاه الحركة يحدده نوع التسوية.</div>
1099:           </Card>
1100:         </div>
1101: 
1102:         <div className="lg:col-span-3 lg:sticky lg:top-5">
1103:           <Card stagger={4}>
1104:             <h3 className="font-display text-[15px] font-semibold c-primary mb-3">ملخص</h3>
1105:             <div className="space-y-2 text-[12.5px]">
1106:               <div className="flex justify-between"><span className="c-secondary">الفرع</span><span className="font-medium c-primary">{branchId ? invBranch(branchId).name : '—'}</span></div>
1107:               <div className="flex justify-between"><span className="c-secondary">الموقع</span><span className="mono c-primary">{locId ? invLoc(locId).code : '—'}</span></div>
1108:               <div className="flex justify-between"><span className="c-secondary">عدد البنود</span><span className="num font-semibold c-primary">{lines.length}</span></div>
1109:             </div>
1110:             <div className="h-px my-4" style={{ background: 'var(--divider-color)' }} />
1111:             <div className="space-y-1.5">
1112:               {totals.length === 0 && <div className="text-[11.5px] c-muted">لم يتم اختيار أصناف بعد</div>}
1113:               {totals.map(t => <div key={t.k} className="flex items-center justify-between"><Badge cls={ADJ_TYPES[t.k].cls}>{ADJ_TYPES[t.k].label}</Badge><span className="num text-[12px] c-primary font-semibold">{t.n}</span></div>)}
1114:             </div>
1115:             <div className="mt-5 space-y-2">
1116:               <button className="btn btn-orange w-full" onClick={() => { setTried(true); if (valid) { setSrvErr(null); setConfirm(true); } }}>
1117:                 <Icon n="check" s={14} w={2.2} /> تنفيذ التسوية
1118:               </button>
1119:               <button className="btn btn-soft w-full" onClick={() => go('stock')}>إلغاء</button>
1120:             </div>
1121:             {tried && !valid && <div className="text-[11px] mt-3" style={{ color: 'var(--badge-red-text)' }}>أكمل الحقول المطلوبة المظللة بالأحمر.</div>}
1122:           </Card>
1123:         </div>
1124:       </div>
1125: 
1126:       <ConfirmDialog open={confirm} onClose={() => setConfirm(false)} onConfirm={execute} busy={busy} error={srvErr}
1127:         title="تأكيد تنفيذ التسوية" confirmLabel="تنفيذ الآن"
1128:         body={<div className="space-y-3">
1129:           <p>سيتم تنفيذ <b className="c-primary num">{lines.length}</b> بند على <b className="c-primary">{branchId && invBranch(branchId).name}</b>{locId && <> — موقع <span className="mono">{invLoc(locId).code}</span></>}. لا يمكن تعديل أو حذف الحركات بعد التنفيذ؛ للتصحيح أنشئ تسوية عكسية.</p>
1130:           <div className="v-subcard p-3 space-y-1.5 max-h-40 overflow-y-auto">
1131:             {lines.filter(l => l.variantId).map(l => (
1132:               <div key={l.key} className="flex items-center justify-between text-[12px]">
1133:                 <span className="flex items-center gap-2"><Sku id={l.variantId} /><Badge cls={ADJ_TYPES[l.type].cls}>{ADJ_TYPES[l.type].label}</Badge></span>
1134:                 <span className="num font-semibold c-primary">{invFmt(l.qty)}</span>
1135:               </div>
1136:             ))}
1137:           </div>
1138:         </div>} />
1139:     </section>
1140:   );
1141: }
