1143: // ---------------- 5. Movements ----------------
1144: function MovesScreen({ go, params }) {
1145:   const can = useCan();
1146:   const [f, setF] = useState({ branchId: params.branchId || null, locId: null, productId: params.productId || null, variantId: params.variantId || null, type: null, from: '', to: '' });
1147:   const [cursor, setCursor] = useState(0);
1148:   const PAGE = 12;
1149:   const phase = useLoad(JSON.stringify(f) + cursor);
1150:   const set = p => { setF(x => ({ ...x, ...p })); setCursor(0); };
1151:   const showCost = can('cost.view');
1152: 
1153:   const rows = INV_MOVES.filter(m => {
1154:     const v = invVariant(m.variantId); const d = m.date.slice(0, 10);
1155:     return (!f.branchId || m.branchId === f.branchId) && (!f.locId || m.locId === f.locId) && (!f.productId || v.productId === f.productId)
1156:       && (!f.variantId || m.variantId === f.variantId) && (!f.type || m.type === f.type) && (!f.from || d >= f.from) && (!f.to || d <= f.to);
1157:   });
1158:   const page = rows.slice(cursor, cursor + PAGE);
1159:   const hasNext = cursor + PAGE < rows.length;
1160:   const active = ['branchId', 'locId', 'productId', 'variantId', 'type', 'from', 'to'].filter(k => f[k]).length;
1161: 
1162:   return (
1163:     <section className="space-y-5">
1164:       <PageHead title="حركات المخزون" sub="سجل غير قابل للتعديل لكل عملية أثّرت على الكميات." />
1165:       <Card stagger={2}>
1166:         <CardHead title="السجل" meta={<span className="flex items-center gap-1.5"><Icon n="lock" s={11} /> عرض فقط</span>}
1167:           right={!showCost && <span className="text-[11px] c-muted flex items-center gap-1"><Icon n="lock" s={11} /> تكلفة الوحدة مخفية حسب صلاحيتك</span>} />
1168:         <FilterBar active={active} onReset={() => set({ branchId: null, locId: null, productId: null, variantId: null, type: null, from: '', to: '' })}>
1169:           <BranchLocFilters f={f} set={set} />
1170:           <ProductVariantFilters f={f} set={set} />
1171:           <FItem label="نوع الحركة" w="w-40"><Sel small value={f.type} onChange={v => set({ type: v })} placeholder="كل الأنواع" options={Object.entries(INV_MOVE_TYPES).map(([k, t]) => ({ value: k, label: t.label }))} className="!bg-[var(--bg-card)]" /></FItem>
1172:           <FItem label="من تاريخ" w="w-36"><input type="date" value={f.from} onChange={e => set({ from: e.target.value })} className="inp inp-sm num !bg-[var(--bg-card)]" /></FItem>
1173:           <FItem label="إلى تاريخ" w="w-36"><input type="date" value={f.to} onChange={e => set({ to: e.target.value })} className="inp inp-sm num !bg-[var(--bg-card)]" /></FItem>
1174:         </FilterBar>
1175: 
1176:         <Phase phase={phase} cols={9} rows={8}
1177:           empty={<EmptyState icon="history" title="لا توجد حركات بعد" sub="ستظهر هنا كل عمليات التسوية والتحويل والجرد واستلام الإنتاج بمجرد تنفيذها." />}>
1178:           {page.length === 0 ? <EmptyState icon="filter" title="لا توجد حركات تطابق الفلاتر" sub="وسّع نطاق التاريخ أو امسح بعض الفلاتر." /> : (
1179:             <>
1180:               <div className="overflow-x-auto">
1181:                 <table className="vt">
1182:                   <thead><tr>
1183:                     <th>التاريخ</th><th>المرجع</th><th>SKU</th><th>الفرع</th><th>الموقع</th><th>نوع الحركة</th>
1184:                     <th className="t-num">الكمية</th><th className="t-num">الرصيد قبل ← بعد</th>{showCost && <th className="t-num">تكلفة الوحدة</th>}<th>المنفّذ</th><th>ملاحظات</th>
1185:                   </tr></thead>
1186:                   <tbody>
1187:                     {page.map(m => {
1188:                       const t = INV_MOVE_TYPES[m.type];
1189:                       return (
1190:                         <tr key={m.id}>
1191:                           <td className="num text-[11.5px] c-secondary">{m.date}</td>
1192:                           <td><span className="mono text-[11.5px] font-semibold c-orange">{m.ref}</span></td>
1193:                           <td><div className="flex flex-col gap-0.5"><Sku id={m.variantId} /><span className="text-[10.5px] c-muted">{invVariant(m.variantId).productName}</span></div></td>
1194:                           <td className="c-secondary">{invBranch(m.branchId).name}</td>
1195:                           <td className="mono text-[11.5px] c-secondary">{invLoc(m.locId).code}</td>
1196:                           <td><Badge cls={t.cls}>{t.label}</Badge></td>
1197:                           <td className="t-num num font-bold" style={{ color: m.qty > 0 ? 'var(--badge-green-text)' : 'var(--badge-red-text)' }}>{m.qty > 0 ? '+' : '−'}{invFmt(Math.abs(m.qty))}</td>
1198:                           <td className="t-num num text-[12px]"><span className="c-muted">{invFmt(m.before)}</span> <span className="c-muted mx-1">→</span> <span className="font-semibold c-primary">{invFmt(m.after)}</span></td>
1199:                           {showCost && <td className="t-num num c-secondary">{invMoney(m.unitCost)}</td>}
1200:                           <td className="c-secondary">{m.user}</td>
1201:                           <td className="text-[11.5px] c-muted max-w-[160px] truncate">{m.note || '—'}</td>
1202:                         </tr>
1203:                       );
1204:                     })}
1205:                   </tbody>
1206:                 </table>
1207:               </div>
1208:               <div className="flex items-center justify-between mt-4 pt-4" style={{ borderTop: '1px solid var(--divider-color)' }}>
1209:                 <span className="text-[11.5px] c-muted">عرض <span className="num">{page.length}</span> حركة · التنقل بالمؤشر</span>
1210:                 <div className="flex items-center gap-2">
1211:                   <button className="btn btn-soft btn-sm" disabled={cursor === 0} onClick={() => setCursor(c => Math.max(0, c - PAGE))}><Icon n="chevR" s={13} /> السابق</button>
1212:                   <button className="btn btn-dark btn-sm" disabled={!hasNext} onClick={() => setCursor(c => c + PAGE)}>التالي <Icon n="chevL" s={13} /></button>
1213:                 </div>
1214:               </div>
1215:             </>
1216:           )}
1217:         </Phase>
1218:       </Card>
1219:     </section>
1220:   );
1221: }
1222: 
1223: function NoPerm({ title, perm, go }) {
1224:   return (
1225:     <section className="space-y-5">
1226:       <PageHead title={title} />
1227:       <Card><EmptyState icon="lock" title="لا تملك صلاحية الوصول لهذه الشاشة" sub={`تتطلب هذه العملية صلاحية «${perm}». تواصل مع مدير النظام لمنحك الصلاحية.`}
1228:         action={<button className="btn btn-soft btn-sm" onClick={() => go('stock')}>العودة لأرصدة المخزون</button>} /></Card>
