1233: // ============ 6. Stock transfers ============
1234: 
1235: const TR_FLOW = ['draft', 'approved', 'shipped', 'received'];
1236: let __trKey = 1;
1237: const newTrLine = (p = {}) => ({ key: __trKey++, variantId: null, fromLoc: null, toLoc: null, req: '', ...p });
1238: 
1239: function TrStatus({ s }) { const t = INV_TR_STATUS[s]; return <Badge cls={t.cls} dot>{t.label}</Badge>; }
1240: 
1241: function TransfersScreen({ go }) {
1242:   const { db } = useInv();
1243:   const phase = useLoad('transfers');
1244:   const [st, setSt] = useState('all');
1245:   const [q, setQ] = useState('');
1246:   const rows = db.transfers.filter(t => (st === 'all' || t.status === st) && (!q || t.no.toLowerCase().includes(q.toLowerCase())));
1247:   const cnt = k => db.transfers.filter(t => t.status === k).length;
1248:   return (
1249:     <section className="space-y-5">
1250:       <PageHead title="التحويلات المخزنية" sub="نقل البضاعة بين فرعين أو مخزنين عبر مراحل: مسودة ← اعتماد ← شحن ← استلام."
1251:         actions={<Can perm="transfers.create"><button className="btn btn-dark" onClick={() => go('transfer-edit', {})}><Icon n="plus" s={14} w={2.2} /> تحويل جديد</button></Can>} />
1252: 
1253:       <div className="grid grid-cols-2 lg:grid-cols-4 gap-3.5 stagger-item stagger-2">
1254:         <KPI label="مسودات" icon="edit" value={cnt('draft')} sub="بانتظار الاعتماد" />
1255:         <KPI label="معتمدة" icon="check" value={cnt('approved')} sub="جاهزة للشحن" />
1256:         <KPI hot label="في الطريق" icon="truck" value={cnt('shipped')} sub="بانتظار الاستلام" />
1257:         <KPI label="مستلمة هذا الشهر" icon="inbox" value={cnt('received')} sub="أكتوبر ٢٠٢٦" />
1258:       </div>
1259: 
1260:       <Card stagger={3}>
1261:         <CardHead title="القائمة" right={<>
1262:           <div className="seg">
1263:             <button className={st === 'all' ? 'on' : ''} onClick={() => setSt('all')}>الكل</button>
1264:             {Object.entries(INV_TR_STATUS).map(([k, t]) => <button key={k} className={st === k ? 'on' : ''} onClick={() => setSt(k)}>{t.label}</button>)}
1265:           </div>
1266:           <SearchPill value={q} onChange={setQ} placeholder="رقم التحويل" w="w-32" />
1267:         </>} />
1268:         <Phase phase={phase} cols={6}
1269:           empty={<EmptyState icon="swap" title="لا توجد تحويلات" sub="أنشئ أول تحويل لنقل الكميات من المخزن الرئيسي إلى الفروع."
1270:             action={<Can perm="transfers.create"><button className="btn btn-dark btn-sm" onClick={() => go('transfer-edit', {})}><Icon n="plus" s={13} /> تحويل جديد</button></Can>} />}>
1271:           {rows.length === 0 ? <EmptyState icon="filter" title="لا توجد تحويلات بهذه الحالة" /> : (
1272:             <table className="vt">
1273:               <thead><tr><th>رقم التحويل</th><th>المصدر ← الوجهة</th><th>البنود</th><th>التقدّم</th><th>الحالة</th><th>التاريخ</th><th></th></tr></thead>
1274:               <tbody>
1275:                 {rows.map(t => {
1276:                   const idx = TR_FLOW.indexOf(t.status);
1277:                   return (
1278:                     <tr key={t.id} className="cursor-pointer" onClick={() => go('transfer', { id: t.id })}>
1279:                       <td><span className="mono text-[12px] font-semibold c-primary">{t.no}</span></td>
1280:                       <td>
1281:                         <div className="flex items-center gap-2">
1282:                           <span className="font-medium c-primary">{invBranch(t.from).name}</span>
1283:                           <Icon n="arrowL" s={14} className="c-orange" />
1284:                           <span className="font-medium c-primary">{invBranch(t.to).name}</span>
1285:                         </div>
1286:                       </td>
1287:                       <td className="num c-secondary">{t.lines.length}</td>
1288:                       <td>
1289:                         <div className="flex items-center gap-1 w-28">
1290:                           {TR_FLOW.slice(1).map((s, i) => <span key={s} className="h-1.5 flex-1 rounded-full" style={{ background: t.status === 'cancelled' ? 'var(--badge-red-bg)' : i < idx ? 'var(--accent-orange)' : 'var(--badge-gray-bg)' }} />)}
1291:                         </div>
1292:                       </td>
1293:                       <td><TrStatus s={t.status} /></td>
1294:                       <td className="num text-[11.5px] c-secondary">{t.date}</td>
1295:                       <td><Icon n="chevL" s={15} className="c-muted" /></td>
1296:                     </tr>
1297:                   );
1298:                 })}
1299:               </tbody>
1300:             </table>
1301:           )}
1302:         </Phase>
1303:       </Card>
1304:     </section>
1305:   );
1306: }
