1308: function TransferEdit({ go, params }) {
1309:   const { db, setDb, toast } = useInv();
1310:   const can = useCan();
1311:   const existing = params.id ? db.transfers.find(t => t.id === params.id) : null;
1312:   const [from, setFrom] = useState(existing?.from || null);
1313:   const [to, setTo] = useState(existing?.to || null);
1314:   const [note, setNote] = useState(existing?.note || '');
1315:   const [lines, setLines] = useState(() => existing ? existing.lines.map(l => newTrLine({ ...l, req: String(l.req) })) : [newTrLine()]);
1316:   const [tried, setTried] = useState(false);
1317:   const [busy, setBusy] = useState(false);
1318: 
1319:   if (!can('transfers.create')) return <NoPerm title="تحويل جديد" perm="إنشاء التحويلات" go={go} />;
1320: 
1321:   const same = from && to && from === to;
1322:   const upd = (key, p) => setLines(ls => ls.map(l => l.key === key ? { ...l, ...p } : l));
1323:   const lineBad = l => !l.variantId || !(parseFloat(l.req) > 0);
1324:   const valid = from && to && !same && lines.length && lines.every(l => !lineBad(l));
1325: 
1326:   const save = () => {
1327:     setTried(true); if (!valid) return;
1328:     setBusy(true);
1329:     setTimeout(() => {
1330:       const data = { from, to, note, lines: lines.map(l => ({ variantId: l.variantId, fromLoc: l.fromLoc, toLoc: l.toLoc, req: parseFloat(l.req), appr: null, ship: null, recv: null })) };
1331:       let id = existing?.id;
1332:       if (existing) setDb(d => ({ ...d, transfers: d.transfers.map(t => t.id === id ? { ...t, ...data } : t) }));
1333:       else { id = 't' + Date.now(); setDb(d => ({ ...d, transfers: [{ id, no: 'TRF-2026-00' + (143 + d.transfers.length - 5), status: 'draft', date: '2026-10-23', createdBy: 'أحمد سمير', ...data }, ...d.transfers] })); }
1334:       toast('تم حفظ التحويل كمسودة'); go('transfer', { id });
1335:     }, 600);
1336:   };
1337: 
1338:   const avail = (vid, br, loc) => INV_STOCK.filter(s => s.variantId === vid && s.branchId === br && (!loc || s.locId === loc)).reduce((a, s) => a + s.available, 0);
1339: 
1340:   return (
1341:     <section className="space-y-5">
1342:       <PageHead title={existing ? `تعديل ${existing.no}` : 'تحويل جديد'} back={{ label: 'التحويلات المخزنية', onClick: () => go(existing ? 'transfer' : 'transfers', existing ? { id: existing.id } : {}) }}
1343:         actions={<><button className="btn btn-soft" onClick={() => go('transfers')}>إلغاء</button><button className="btn btn-dark" onClick={save} disabled={busy}>{busy && <span className="w-3.5 h-3.5 rounded-full border-2 border-current border-t-transparent animate-spin" />} حفظ كمسودة</button></>} />
1344: 
1345:       <Card stagger={2}>
1346:         <div className="grid grid-cols-1 md:grid-cols-[1fr_auto_1fr] gap-4 items-end">
1347:           <Field label="فرع المصدر" req error={tried && !from ? 'مطلوب' : null}>
1348:             <Sel value={from} onChange={v => { setFrom(v); setLines(ls => ls.map(l => ({ ...l, fromLoc: null }))); }} placeholder="من…" options={branchOpts(b => b.active)} className={(tried && !from) || same ? 'err' : ''} />
1349:           </Field>
1350:           <button type="button" onClick={() => { setFrom(to); setTo(from); setLines(ls => ls.map(l => ({ ...l, fromLoc: l.toLoc, toLoc: l.fromLoc }))); }} className="w-10 h-10 rounded-full v-subcard flex items-center justify-center c-orange mx-auto mb-0.5" title="تبديل">
1351:             <Icon n="swap" s={16} />
1352:           </button>
1353:           <Field label="فرع الوجهة" req error={tried && !to ? 'مطلوب' : null}>
1354:             <Sel value={to} onChange={v => { setTo(v); setLines(ls => ls.map(l => ({ ...l, toLoc: null }))); }} placeholder="إلى…" options={branchOpts(b => b.active)} className={(tried && !to) || same ? 'err' : ''} />
1355:           </Field>
1356:         </div>
1357:         {same && <div className="mt-3"><InlineAlert kind="red" title="المصدر والوجهة متطابقان">العملية الحالية تشترط اختلاف فرع المصدر عن فرع الوجهة. للنقل بين مواقع داخل نفس الفرع استخدم التسوية.</InlineAlert></div>}
1358:         <Field label="ملاحظات" className="mt-4"><textarea className="inp" rows={2} value={note} onChange={e => setNote(e.target.value)} placeholder="سبب التحويل أو تعليمات للشحن…" /></Field>
1359:       </Card>
1360: 
1361:       <Card stagger={3}>
1362:         <CardHead title="البنود" meta={<span className="num">{lines.length}</span>} right={<button className="btn btn-soft btn-sm" onClick={() => setLines(ls => [...ls, newTrLine()])}><Icon n="plus" s={13} /> إضافة بند</button>} />
1363:         <div className="overflow-x-auto">
1364:           <table className="vt">
1365:             <thead><tr><th className="w-8">#</th><th style={{ minWidth: 280 }}>المتغير / SKU</th><th style={{ minWidth: 170 }}>موقع المصدر</th><th style={{ minWidth: 170 }}>موقع الوجهة</th><th style={{ minWidth: 130 }}>الكمية المطلوبة</th><th></th></tr></thead>
1366:             <tbody>
1367:               {lines.map((l, i) => {
1368:                 const a = l.variantId && from ? avail(l.variantId, from, l.fromLoc) : null;
1369:                 const over = a !== null && parseFloat(l.req) > a;
1370:                 return (
1371:                   <tr key={l.key} className="align-top">
1372:                     <td className="num c-muted pt-4">{i + 1}</td>
1373:                     <td>
1374:                       <div className={tried && !l.variantId ? 'rounded-[12px] ring-1 ring-[var(--badge-red-text)]' : ''}><VariantPicker small value={l.variantId} onChange={v => upd(l.key, { variantId: v })} /></div>
1375:                       {a !== null && <div className="text-[10.5px] c-muted mt-1 pr-1">المتاح في المصدر: <span className="num font-semibold c-primary">{invFmt(a)}</span></div>}
1376:                     </td>
1377:                     <td><Sel small value={l.fromLoc} onChange={v => upd(l.key, { fromLoc: v })} placeholder={from ? 'أي موقع' : '—'} disabled={!from} options={from ? locOpts(from) : []} /></td>
1378:                     <td><Sel small value={l.toLoc} onChange={v => upd(l.key, { toLoc: v })} placeholder={to ? 'موقع الاستلام الافتراضي' : '—'} disabled={!to} options={to ? locOpts(to) : []} /></td>
1379:                     <td>
1380:                       <NumInput small value={l.req} onChange={v => upd(l.key, { req: v })} err={tried && !(parseFloat(l.req) > 0)} />
1381:                       {over && <div className="text-[10.5px] mt-1" style={{ color: 'var(--badge-amber-text)' }}>أكبر من المتاح حاليًا</div>}
1382:                     </td>
1383:                     <td className="pt-3"><button className="icon-btn" disabled={lines.length === 1} onClick={() => setLines(ls => ls.filter(x => x.key !== l.key))}><Icon n="trash" s={14} /></button></td>
1384:                   </tr>
1385:                 );
1386:               })}
1387:             </tbody>
1388:           </table>
1389:         </div>
1390:       </Card>
1391:     </section>
1392:   );
1393: }
1394: 
1395: function TransferDetail({ go, params }) {
1396:   const { db, setDb, toast, demoState } = useInv();
1397:   const can = useCan();
1398:   const phase = useLoad('tr' + params.id);
1399:   const t = db.transfers.find(x => x.id === params.id);
1400:   const [stage, setStage] = useState(null); // 'approve' | 'ship' | 'receive'
1401:   const [qtys, setQtys] = useState({});
1402:   const [confirm, setConfirm] = useState(null);
1403:   const [busy, setBusy] = useState(false);
1404:   const [err, setErr] = useState(null);
1405: 
1406:   if (!t) return <section><Card><EmptyState icon="alert" title="التحويل غير موجود" action={<button className="btn btn-soft btn-sm" onClick={() => go('transfers')}>العودة</button>} /></Card></section>;
1407: 
1408:   const idx = TR_FLOW.indexOf(t.status);
1409:   const stageMeta = {
1410:     approve: { col: 'appr', srcCol: 'req', label: 'اعتماد', next: 'approved', perm: 'transfers.approve', hint: 'حدّد الكمية المعتمدة لكل بند (لا تتجاوز المطلوبة).' },
1411:     ship:    { col: 'ship', srcCol: 'appr', label: 'شحن', next: 'shipped', perm: 'transfers.ship', hint: 'أدخل الكمية المشحونة فعليًا. سيتم خصمها من المصدر وتظهر «قيد النقل».' },
1412:     receive: { col: 'recv', srcCol: 'ship', label: 'استلام', next: 'received', perm: 'transfers.receive', hint: 'أدخل الكمية المستلمة فعليًا في الوجهة. أي فرق يُسجَّل في الملاحظات.' },
1413:   };
1414:   const startStage = s => { const m = stageMeta[s]; setStage(s); setQtys(Object.fromEntries(t.lines.map((l, i) => [i, String(l[m.srcCol] ?? '')]))); };
1415:   const commit = () => {
1416:     const m = stageMeta[stage];
1417:     setBusy(true); setErr(null);
1418:     setTimeout(() => {
1419:       setBusy(false);
1420:       if (demoState === 'error') { setErr('تغيّرت حالة التحويل بواسطة مستخدم آخر. حدّث الصفحة وأعد المحاولة. (409)'); return; }
1421:       setDb(d => ({ ...d, transfers: d.transfers.map(x => x.id === t.id ? { ...x, status: m.next, lines: x.lines.map((l, i) => ({ ...l, [m.col]: parseFloat(qtys[i]) || 0 })) } : x) }));
1422:       setConfirm(null); setStage(null); toast(`تم ${m.label} التحويل`);
1423:     }, 800);
1424:   };
1425:   const cancel = () => {
1426:     setBusy(true);
1427:     setTimeout(() => { setBusy(false); setDb(d => ({ ...d, transfers: d.transfers.map(x => x.id === t.id ? { ...x, status: 'cancelled' } : x) })); setConfirm(null); toast('تم إلغاء التحويل'); }, 600);
1428:   };
1429: 
1430:   const actions = [];
1431:   if (!stage) {
1432:     if (t.status === 'draft') {
1433:       if (can('transfers.create')) actions.push(<button key="e" className="btn btn-soft" onClick={() => go('transfer-edit', { id: t.id })}><Icon n="edit" s={14} /> تعديل</button>);
1434:       if (can('transfers.approve')) actions.push(<button key="a" className="btn btn-dark" onClick={() => startStage('approve')}><Icon n="check" s={14} /> اعتماد</button>);
1435:     }
1436:     if (t.status === 'approved' && can('transfers.ship')) actions.push(<button key="s" className="btn btn-dark" onClick={() => startStage('ship')}><Icon n="truck" s={14} /> شحن</button>);
1437:     if (t.status === 'shipped' && can('transfers.receive')) actions.push(<button key="r" className="btn btn-orange" onClick={() => startStage('receive')}><Icon n="inbox" s={14} /> استلام</button>);
1438:     if (['draft', 'approved'].includes(t.status) && can('transfers.cancel')) actions.unshift(<button key="c" className="btn btn-danger" onClick={() => { setErr(null); setConfirm('cancel'); }}>إلغاء التحويل</button>);
1439:   }
1440:   const nextNeedsPerm = !stage && actions.length === 0 && !['received', 'cancelled'].includes(t.status);
1441: 
1442:   const steps = [['draft', 'مسودة', 'edit'], ['approved', 'معتمد', 'check'], ['shipped', 'مشحون', 'truck'], ['received', 'مستلم', 'inbox']];
1443: 
1444:   return (
1445:     <section className="space-y-5">
1446:       <PageHead title={<span className="mono">{t.no}</span>} back={{ label: 'التحويلات المخزنية', onClick: () => go('transfers') }}
1447:         sub={<span className="flex items-center gap-2 flex-wrap">{invBranch(t.from).name} <Icon n="arrowL" s={14} className="c-orange" /> {invBranch(t.to).name} <span className="c-muted">·</span> <TrStatus s={t.status} /></span>}
1448:         actions={actions.length ? actions : nextNeedsPerm ? <span className="inline-flex items-center gap-1.5 text-[12px] c-muted px-3.5 py-2 rounded-full v-subcard"><Icon n="lock" s={12} /> الخطوة التالية تتطلب صلاحية أخرى</span> : null} />
1449: 
1450:       <Phase phase={phase} cols={6} rows={3} empty={<Card><EmptyState icon="swap" title="لا توجد بنود" /></Card>}>
1451:         <div className="grid grid-cols-1 lg:grid-cols-12 gap-5 items-start">
1452:           <div className="lg:col-span-8 space-y-5">
1453:             <Card stagger={2} pad="p-6">
1454:               {t.status === 'cancelled' ? (
1455:                 <InlineAlert kind="red" icon="x" title="تم إلغاء هذا التحويل">{t.note || 'لا يمكن تنفيذ أي إجراء على تحويل ملغي.'}</InlineAlert>
1456:               ) : (
1457:                 <div className="flex items-center gap-2">
1458:                   {steps.map(([k, l, ic], i) => (
1459:                     <Fragment key={k}>
1460:                       <div className="flex flex-col items-center gap-1.5 shrink-0">
1461:                         <span className={`w-10 h-10 rounded-full flex items-center justify-center ${i <= idx ? 'text-white' : 'c-muted'}`} style={{ background: i < idx ? 'var(--pill-active-bg)' : i === idx ? 'var(--accent-orange)' : 'var(--bg-subcard)', color: i < idx ? 'var(--pill-active-text)' : undefined }}>
1462:                           <Icon n={i < idx ? 'check' : ic} s={16} w={2} />
1463:                         </span>
1464:                         <span className={`text-[11.5px] ${i === idx ? 'font-semibold c-primary' : 'c-secondary'}`}>{l}</span>
1465:                       </div>
1466:                       {i < steps.length - 1 && <div className={`step-line mb-5 ${i < idx ? 'done' : ''}`} />}
1467:                     </Fragment>
1468:                   ))}
1469:                 </div>
1470:               )}
1471:             </Card>
1472: 
1473:             <Card stagger={3}>
1474:               <CardHead title="البنود" meta={stage ? `وضع ${stageMeta[stage].label}` : `${t.lines.length} بند`} />
1475:               {stage && <div className="mb-3"><InlineAlert kind="blue" icon="info" title={`${stageMeta[stage].label} التحويل`}>{stageMeta[stage].hint}</InlineAlert></div>}
1476:               <div className="overflow-x-auto">
1477:                 <table className="vt">
1478:                   <thead><tr><th>المتغير</th><th>من ← إلى</th><th className="t-num">المطلوبة</th><th className="t-num">المعتمدة</th><th className="t-num">المشحونة</th><th className="t-num">المستلمة</th></tr></thead>
1479:                   <tbody>
1480:                     {t.lines.map((l, i) => {
1481:                       const cell = (col) => {
1482:                         if (stage && stageMeta[stage].col === col) {
1483:                           const max = parseFloat(l[stageMeta[stage].srcCol]);
1484:                           const over = parseFloat(qtys[i]) > max;
1485:                           return <td className="t-num" style={{ width: 110 }}><NumInput small value={qtys[i]} onChange={v => setQtys(q => ({ ...q, [i]: v }))} err={over} className="!bg-[var(--accent-orange-light)]" />{over && <div className="text-[10px] mt-0.5" style={{ color: 'var(--badge-red-text)' }}>الحد {invFmt(max)}</div>}</td>;
1486:                         }
1487:                         const v = l[col]; const diff = col === 'recv' && v !== null && l.ship !== null && v !== l.ship;
1488:                         return <td className="t-num num" style={{ color: v === null ? 'var(--text-muted)' : diff ? 'var(--badge-red-text)' : 'var(--text-primary)', fontWeight: v === null ? 400 : 600 }}>{v === null ? '—' : invFmt(v)}{diff && <span className="text-[10px] block font-normal">عجز {invFmt(l.ship - v)}</span>}</td>;
1489:                       };
1490:                       return (
1491:                         <tr key={i}>
1492:                           <td><div className="flex items-center gap-2.5"><Sku id={l.variantId} /><VariantCell id={l.variantId} /></div></td>
1493:                           <td className="mono text-[11px] c-secondary">{l.fromLoc ? invLoc(l.fromLoc).code : '—'} → {l.toLoc ? invLoc(l.toLoc).code : '—'}</td>
1494:                           <td className="t-num num font-semibold c-primary">{invFmt(l.req)}</td>
1495:                           {cell('appr')}{cell('ship')}{cell('recv')}
1496:                         </tr>
1497:                       );
1498:                     })}
1499:                   </tbody>
1500:                 </table>
1501:               </div>
1502:               {stage && (
1503:                 <div className="flex items-center gap-2.5 mt-4 pt-4" style={{ borderTop: '1px solid var(--divider-color)' }}>
1504:                   <button className="btn btn-orange" onClick={() => {
1505:                     const m = stageMeta[stage];
1506:                     if (t.lines.some((l, i) => parseFloat(qtys[i]) > parseFloat(l[m.srcCol]))) return;
1507:                     setErr(null); setConfirm('stage');
1508:                   }}><Icon n="check" s={14} w={2.2} /> تأكيد ال{stageMeta[stage].label}</button>
1509:                   <button className="btn btn-soft" onClick={() => setStage(null)}>تراجع</button>
1510:                 </div>
1511:               )}
1512:             </Card>
1513:           </div>
1514: 
1515:           <Card className="lg:col-span-4" stagger={4}>
1516:             <h3 className="font-display text-[15px] font-semibold c-primary mb-3">التفاصيل</h3>
1517:             <div className="space-y-3 text-[12.5px]">
1518:               {[['المصدر', invBranch(t.from).name], ['الوجهة', invBranch(t.to).name], ['التاريخ', <span className="num">{t.date}</span>], ['أنشأه', t.createdBy]].map(([k, v]) => (
1519:                 <div key={k} className="flex justify-between"><span className="c-secondary">{k}</span><span className="font-medium c-primary">{v}</span></div>
1520:               ))}
1521:             </div>
1522:             <div className="v-subcard p-3.5 mt-4 text-[12px] c-secondary">{t.note || <span className="c-muted">لا توجد ملاحظات</span>}</div>
1523:             <div className="mt-4 space-y-2">
1524:               {[['req', 'المطلوب'], ['appr', 'المعتمد'], ['ship', 'المشحون'], ['recv', 'المستلم']].map(([k, l]) => {
1525:                 const total = t.lines.reduce((a, x) => a + (x[k] || 0), 0); const req = t.lines.reduce((a, x) => a + x.req, 0);
1526:                 return (
1527:                   <div key={k}>
1528:                     <div className="flex justify-between text-[11.5px] mb-1"><span className="c-secondary">{l}</span><span className="num font-semibold c-primary">{invFmt(total)}</span></div>
1529:                     <div className="h-1.5 rounded-full hatched overflow-hidden"><div className="h-full rounded-full bar-hatched-orange" style={{ width: (req ? total / req * 100 : 0) + '%' }} /></div>
1530:                   </div>
1531:                 );
1532:               })}
1533:             </div>
1534:           </Card>
1535:         </div>
1536:       </Phase>
1537: 
1538:       <ConfirmDialog open={confirm === 'stage'} onClose={() => setConfirm(null)} onConfirm={commit} busy={busy} error={err}
1539:         title={stage ? `تأكيد ${stageMeta[stage].label} ${t.no}` : ''} confirmLabel="تأكيد"
1540:         body={stage === 'ship' ? 'سيتم خصم الكميات المشحونة من رصيد المصدر وإضافتها كـ«قيد النقل» حتى يتم الاستلام.' : stage === 'receive' ? 'سيتم إضافة الكميات المستلمة إلى رصيد الوجهة وإغلاق التحويل.' : 'بعد الاعتماد لا يمكن تعديل بنود التحويل.'} />
1541:       <ConfirmDialog open={confirm === 'cancel'} onClose={() => setConfirm(null)} onConfirm={cancel} busy={busy} danger title="إلغاء التحويل؟" confirmLabel="إلغاء التحويل"
1542:         body={<>سيتم إلغاء <span className="mono c-primary">{t.no}</span> نهائيًا ولن يمكن إعادة تفعيله.</>} />
1543:     </section>
1544:   );
1545: }
