1547: // ============ Shared Vortix UI primitives (RTL) ============
1548: 
1549: 
1550: const InvCtx = createContext(null);
1551: const useInv = () => useContext(InvCtx);
1552: const PERMISSION_MAP = { 'branches.manage':['branches.manage','branches.create','branches.update','branches.delete'], 'stock.adjust':['inventory.adjust'], 'cost.view':['products.view_cost'], 'count.manage':['stocktakes.create','stocktakes.update'], 'count.approve':['stocktakes.approve'], 'transfers.cancel':['transfers.update'] };
1553: const useCan = () => { const { can } = useInv(); return p => (PERMISSION_MAP[p] || [p]).some(can); };
1554: 
1555: // Simulated fetch lifecycle: loading → (live | empty | error) per demo tweak
1556: function useLoad(dep) {
1557:   const { demoState, reloadKey } = useInv();
1558:   const [phase, setPhase] = useState('loading');
1559:   useEffect(() => {
1560:     setPhase('loading');
1561:     if (demoState === 'loading') return;
1562:     const t = setTimeout(() => setPhase(demoState === 'live' ? 'ready' : demoState), 550);
1563:     return () => clearTimeout(t);
1564:   }, [demoState, reloadKey, dep]);
1565:   return phase;
1566: }
1567: 
