1607: function Icon({ n, s = 16, w = 1.9, className = '', style }) {
1608:   return (
1609:     <svg width={s} height={s} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={w} strokeLinecap="round" strokeLinejoin="round" className={className} style={style}>
