1615: // ---------- Layout ----------
1616: function PageHead({ title, sub, actions, back }) {
1617:   return (
1618:     <div className="flex flex-wrap items-end justify-between gap-4 pt-1 stagger-item stagger-1">
1619:       <div>
1620:         {back && (
1621:           <button onClick={back.onClick} className="flex items-center gap-1.5 text-[12px] font-medium c-secondary hover:c-primary mb-2">
1622:             <Icon n="chevR" s={14} /> {back.label}
1623:           </button>
1624:         )}
1625:         <h1 className="font-display text-[34px] sm:text-[38px] font-medium tracking-[-0.02em] leading-tight c-primary">{title}</h1>
1626:         {sub && <p className="text-[13.5px] mt-1 c-secondary">{sub}</p>}
1627:       </div>
1628:       {actions && <div className="flex items-center gap-2.5 flex-wrap">{actions}</div>}
1629:     </div>
1630:   );
1631: }
1632: 
1633: function Card({ children, className = '', pad = 'p-5', stagger = 2 }) {
1634:   return <div className={`v-card ${pad} stagger-item stagger-${stagger} ${className}`}>{children}</div>;
1635: }
1636: 
1637: function CardHead({ title, meta, right }) {
1638:   return (
1639:     <div className="flex flex-wrap items-center justify-between gap-3 mb-4">
1640:       <div className="flex items-center gap-2.5">
1641:         <h3 className="font-display text-[17px] font-semibold c-primary">{title}</h3>
1642:         {meta && <span className="text-[11.5px] c-muted">| &nbsp;{meta}</span>}
1643:       </div>
1644:       {right && <div className="flex items-center gap-2.5 flex-wrap">{right}</div>}
1645:     </div>
1646:   );
1647: }
1648: 
1649: function Badge({ cls = 'b-gray', dot, children }) {
1650:   return <span className={`badge ${cls}`}>{dot && <span className="dot" />}{children}</span>;
1651: }
1652: const ActiveBadge = ({ on }) => <Badge cls={on ? 'b-green' : 'b-gray'} dot>{on ? 'نشط' : 'غير نشط'}</Badge>;
1653: 
1654: function SearchPill({ value, onChange, placeholder = 'بحث', w = 'w-40' }) {
1655:   return (
1656:     <div className="v-subcard px-3 py-1.5 rounded-full flex items-center gap-2">
1657:       <Icon n="search" s={14} className="c-muted" />
1658:       <input value={value} onChange={e => onChange(e.target.value)} placeholder={placeholder} className={`bg-transparent text-[12px] outline-none ${w} c-primary`} />
1659:     </div>
1660:   );
1661: }
1662: 
1663: function Field({ label, req, hint, error, children, className = '' }) {
1664:   return (
1665:     <label className={`block ${className}`}>
1666:       <span className="field-label">{label}{req && <span className="c-orange">*</span>}</span>
1667:       {children}
