 250: function invGenMoves() {
 251:   const out = [];
 252:   const types = Object.keys(INV_MOVE_TYPES);
 253:   const refs = { adj_in: 'ADJ', adj_out: 'ADJ', dmg_mark: 'ADJ', dmg_writeoff: 'ADJ', dmg_restore: 'ADJ', tr_out: 'TRF', tr_in: 'TRF', count: 'CNT', production: 'PRD', sale: 'INV' };
 254:   let seed = 7;
 255:   const rnd = () => { seed = (seed * 9301 + 49297) % 233280; return seed / 233280; };
 256:   for (let i = 0; i < 64; i++) {
 257:     const st = INV_STOCK[Math.floor(rnd() * INV_STOCK.length)];
 258:     const t = types[Math.floor(rnd() * types.length)];
 259:     const mt = INV_MOVE_TYPES[t];
 260:     const qty = st.variantId === 'v9' ? +(rnd() * 40 + 1).toFixed(2) : Math.ceil(rnd() * 24);
 261:     const sign = mt.sign === 0 ? (rnd() > .5 ? 1 : -1) : mt.sign;
 262:     const before = Math.round(st.onHand + rnd() * 30);
 263:     const day = 23 - Math.floor(i / 5);
 264:     const h = String(8 + (i * 7) % 12).padStart(2, '0'), m = String((i * 13) % 60).padStart(2, '0');
 265:     out.push({
 266:       id: 'm' + i, date: `2026-10-${String(day).padStart(2, '0')} ${h}:${m}`,
 267:       ref: `${refs[t]}-2026-${String(1480 - i * 3).padStart(5, '0')}`,
 268:       variantId: st.variantId, branchId: st.branchId, locId: st.locId, type: t,
 269:       qty: sign * qty, before, after: +(before + sign * qty).toFixed(4),
 270:       user: INV_USERS[i % 4], unitCost: invVariant(st.variantId).cost,
 271:       note: ['', 'كرتونة مفتوحة', 'مطابقة رصيد افتتاحي', '', 'تلف أثناء النقل', '', 'طلب فرع'][i % 7],
 272:     });
 273:   }
 274:   return out;
 275: }
 276: const INV_MOVES = invGenMoves();
