 423: function BranchesScreen({ go }) {
 424:   const { db, setDb, toast } = useInv();
 425:   const can = useCan();
 426:   const phase = useLoad('branches');
 427:   const [q, setQ] = useState('');
 428:   const [type, setType] = useState('all');
 429:   const [form, setForm] = useState({ open: false, initial: null });
 430:   const [del, setDel] = useState(null);
 431:   const [delBusy, setDelBusy] = useState(false);
 432:   const [delErr, setDelErr] = useState(null);
 433: 
 434:   const locCount = id => db.locations.filter(l => l.branchId === id).length;
 435:   const rows = db.branches.filter(b => (type === 'all' || b.type === type) && (!q || b.name.includes(q) || b.code.toLowerCase().includes(q.toLowerCase()) || b.city.includes(q)));
 436: 
 437:   const save = f => {
 438:     if (f.id) setDb(d => ({ ...d, branches: d.branches.map(b => b.id === f.id ? f : b) }));
 439:     else setDb(d => ({ ...d, branches: [{ ...f, id: 'b' + Date.now() }, ...d.branches] }));
 440:     setForm({ open: false, initial: null });
 441:     toast(f.id ? 'تم حفظ التعديلات' : 'تمت إضافة ' + (f.type === 'warehouse' ? 'المخزن' : 'الفرع'));
 442:   };
 443:   const doDelete = () => {
 444:     setDelBusy(true); setDelErr(null);
 445:     setTimeout(() => {
 446:       setDelBusy(false);
 447:       const lc = locCount(del.id), sc = INV_STOCK.filter(s => s.branchId === del.id).length;
 448:       if (lc || sc) {
 449:         setDelErr(`لا يمكن حذف «${del.name}» لارتباطه بـ ${lc} موقع تخزين${sc ? ` و ${sc} رصيد مخزون` : ''}. يمكنك تعطيله بدلًا من الحذف. (409 Conflict)`);
 450:         return;
 451:       }
 452:       setDb(d => ({ ...d, branches: d.branches.filter(b => b.id !== del.id) }));
 453:       setDel(null); toast('تم الحذف');
 454:     }, 700);
 455:   };
 456: 
 457:   const counts = { all: db.branches.length, branch: db.branches.filter(b => b.type === 'branch').length, warehouse: db.branches.filter(b => b.type === 'warehouse').length };
 458: 
 459:   return (
 460:     <section className="space-y-5">
 461:       <PageHead title="الفروع والمخازن" sub="سجل نقاط البيع والمخازن ومواقع التخزين التابعة لكل منها."
 462:         actions={<Can perm="branches.manage"><button className="btn btn-dark" onClick={() => setForm({ open: true, initial: null })}><Icon n="plus" s={14} w={2.2} /> إضافة فرع / مخزن</button></Can>} />
 463: 
 464:       <Card>
 465:         <CardHead title="القائمة" meta={phase === 'ready' ? `${rows.length} من ${db.branches.length}` : null}
 466:           right={<>
 467:             <div className="seg">
 468:               {[['all', 'الكل'], ['branch', 'فروع'], ['warehouse', 'مخازن']].map(([k, l]) => (
 469:                 <button key={k} className={type === k ? 'on' : ''} onClick={() => setType(k)}>{l} <span className="num c-muted mr-1">{counts[k]}</span></button>
 470:               ))}
 471:             </div>
 472:             <SearchPill value={q} onChange={setQ} placeholder="الاسم، الكود، المدينة" />
 473:           </>} />
 474:         <Phase phase={phase} cols={7}
 475:           empty={<EmptyState icon="store" title="لا توجد فروع أو مخازن بعد" sub="ابدأ بإضافة المخزن الرئيسي، ثم أضف مواقع التخزين بداخله."
 476:             action={<Can perm="branches.manage"><button className="btn btn-dark btn-sm" onClick={() => setForm({ open: true, initial: null })}><Icon n="plus" s={13} /> إضافة أول فرع</button></Can>} />}>
 477:           {rows.length === 0 ? <EmptyState icon="search" title="لا توجد نتائج" sub="جرّب كلمة بحث أخرى أو غيّر نوع الفلتر." /> : (
 478:             <div className="overflow-x-auto">
 479:               <table className="vt">
 480:                 <thead><tr>
 481:                   <th>الاسم</th><th>الكود</th><th>النوع</th><th>المدينة</th><th>الهاتف</th><th>الحالة</th><th>مواقع التخزين</th><th></th>
 482:                 </tr></thead>
 483:                 <tbody>
 484:                   {rows.map(b => (
 485:                     <tr key={b.id}>
 486:                       <td>
 487:                         <div className="flex items-center gap-2.5">
 488:                           <span className={`w-8 h-8 rounded-full flex items-center justify-center shrink-0 ${b.type === 'warehouse' ? '' : 'v-icon-well'}`} style={b.type === 'warehouse' ? { background: 'var(--accent-orange-light)', color: 'var(--accent-orange)' } : {}}>
 489:                             <Icon n={b.type === 'warehouse' ? 'warehouse' : 'store'} s={14} />
 490:                           </span>
 491:                           <div><div className="font-semibold c-primary">{b.name}</div><div className="text-[11px] c-muted mono">{b.email}</div></div>
 492:                         </div>
 493:                       </td>
 494:                       <td><Sku>{b.code}</Sku></td>
 495:                       <td><TypeBadge type={b.type} /></td>
 496:                       <td className="c-secondary">{b.city}</td>
 497:                       <td className="num c-secondary">{b.phone}</td>
 498:                       <td><ActiveBadge on={b.active} /></td>
 499:                       <td>
 500:                         <button onClick={() => go('locations', { branchId: b.id })} className="flex items-center gap-2 group">
 501:                           <span className="num font-semibold c-primary">{locCount(b.id)}</span>
 502:                           <span className="text-[11.5px] c-orange font-semibold opacity-0 group-hover:opacity-100 transition">فتح ←</span>
 503:                         </button>
 504:                       </td>
 505:                       <td>
 506:                         <div className="flex items-center gap-0.5 justify-end">
 507:                           <button className="icon-btn" title="مواقع التخزين" onClick={() => go('locations', { branchId: b.id })}><Icon n="pin" s={15} /></button>
 508:                           {can('branches.manage') && <>
 509:                             <button className="icon-btn" title="تعديل" onClick={() => setForm({ open: true, initial: b })}><Icon n="edit" s={15} /></button>
 510:                             <button className="icon-btn hover:!text-[var(--badge-red-text)]" title="حذف" onClick={() => { setDel(b); setDelErr(null); }}><Icon n="trash" s={15} /></button>
 511:                           </>}
 512:                         </div>
 513:                       </td>
 514:                     </tr>
 515:                   ))}
 516:                 </tbody>
 517:               </table>
 518:             </div>
 519:           )}
 520:         </Phase>
 521:       </Card>
 522: 
 523:       <BranchForm open={form.open} initial={form.initial} onClose={() => setForm({ open: false, initial: null })} onSave={save} />
 524:       <ConfirmDialog open={!!del} onClose={() => setDel(null)} onConfirm={doDelete} danger busy={delBusy} error={delErr}
 525:         title={`حذف ${del?.type === 'warehouse' ? 'المخزن' : 'الفرع'}؟`} confirmLabel="حذف نهائي"
 526:         body={<>سيتم حذف <b className="c-primary">{del?.name}</b> (<span className="mono">{del?.code}</span>). لا يمكن التراجع عن هذا الإجراء، وسيرفض الخادم الحذف إذا كانت هناك مواقع تخزين أو أرصدة أو حركات مرتبطة.</>} />
 527:     </section>
 528:   );
 529: }
