 532: function LocationForm({ open, initial, branchId, onClose, onSave }) {
 533:   const { db } = useInv();
 534:   const blank = { name: '', code: '', type: 'shelf', active: true, branchId };
 535:   const [f, setF] = useState(blank);
 536:   const [err, setErr] = useState({});
 537:   useEffect(() => { if (open) { setF(initial ? { ...initial } : blank); setErr({}); } }, [open]);
 538:   const set = (k, v) => setF(p => ({ ...p, [k]: v }));
 539:   const submit = () => {
 540:     const e = {};
 541:     if (!f.name.trim()) e.name = 'الاسم مطلوب';
 542:     if (!f.code.trim()) e.code = 'الكود مطلوب';
 543:     else if (db.locations.some(l => l.branchId === branchId && l.code.toLowerCase() === f.code.trim().toLowerCase() && l.id !== f.id)) e.code = 'الكود مستخدم بالفعل داخل هذا الفرع';
 544:     setErr(e);
 545:     if (!Object.keys(e).length) onSave(f);
 546:   };
 547:   return (
 548:     <Modal open={open} onClose={onClose} title={initial ? 'تعديل موقع التخزين' : 'إضافة موقع تخزين'} sub={`تابع لـ ${invBranch(branchId)?.name || ''}`}
