 553:           <Field label="الكود" req error={err.code} hint="فريد داخل الفرع"><input className={`inp mono text-left ${err.code ? 'err' : ''}`} value={f.code} onChange={e => set('code', e.target.value.toUpperCase())} placeholder="A-01" /></Field>
