 681: function CountsScreen({ go }) {
 682:   const { db } = useInv();
 683:   const phase = useLoad('counts');
 684:   const [create, setCreate] = useState(false);
 685:   return (
 686:     <section className="space-y-5">
 687:       <PageHead title="الجرد" sub="مقارنة الكميات الموجودة فعليًا بالمسجّلة في النظام، ثم اعتماد الفروق كتسويات."
 688:         actions={<Can perm="count.manage"><button className="btn btn-dark" onClick={() => setCreate(true)}><Icon n="plus" s={14} w={2.2} /> جرد جديد</button></Can>} />
 689:       <Card stagger={2}>
 690:         <CardHead title="القائمة" meta={phase === 'ready' ? `${db.counts.length} عملية` : null} />
 691:         <Phase phase={phase} cols={6}
 692:           empty={<EmptyState icon="clipboard" title="لم يتم إنشاء أي جرد بعد" sub="ابدأ جردًا لفرع كامل أو لموقع تخزين محدد."
 693:             action={<Can perm="count.manage"><button className="btn btn-dark btn-sm" onClick={() => setCreate(true)}><Icon n="plus" s={13} /> جرد جديد</button></Can>} />}>
 694:           <table className="vt">
 695:             <thead><tr><th>رقم الجرد</th><th>الفرع</th><th>الموقع</th><th>تقدّم العدّ</th><th>الحالة</th><th>المنشئ</th><th>التاريخ</th><th></th></tr></thead>
 696:             <tbody>
 697:               {db.counts.map(c => {
 698:                 const done = c.lines.filter(l => l.actual !== null).length;
 699:                 return (
 700:                   <tr key={c.id} className="cursor-pointer" onClick={() => go('count', { id: c.id })}>
 701:                     <td><span className="mono text-[12px] font-semibold c-primary">{c.no}</span></td>
 702:                     <td className="c-primary font-medium">{invBranch(c.branchId).name}</td>
 703:                     <td className="mono text-[11.5px] c-secondary">{c.locId ? invLoc(c.locId).code : <span className="c-muted" style={{ fontFamily: 'inherit' }}>كل المواقع</span>}</td>
 704:                     <td>
 705:                       <div className="flex items-center gap-2">
 706:                         <span className="w-20 h-1.5 rounded-full hatched overflow-hidden"><span className="block h-full rounded-full bg-[var(--accent-orange)]" style={{ width: done / c.lines.length * 100 + '%' }} /></span>
 707:                         <span className="num text-[11.5px] c-secondary">{done}/{c.lines.length}</span>
 708:                       </div>
 709:                     </td>
 710:                     <td><Badge cls={INV_CNT_STATUS[c.status].cls} dot>{INV_CNT_STATUS[c.status].label}</Badge></td>
 711:                     <td className="c-secondary">{c.createdBy}</td>
 712:                     <td className="num text-[11.5px] c-secondary">{c.date}</td>
 713:                     <td><Icon n="chevL" s={15} className="c-muted" /></td>
 714:                   </tr>
 715:                 );
 716:               })}
 717:             </tbody>
 718:           </table>
 719:         </Phase>
 720:       </Card>
 721:       <CountCreate open={create} onClose={() => setCreate(false)} go={go} />
 722:     </section>
 723:   );
 724: }
