 726: function CountCreate({ open, onClose, go }) {
 727:   const { setDb, toast } = useInv();
 728:   const [branchId, setBranchId] = useState(null);
 729:   const [locId, setLocId] = useState(null);
 730:   const [note, setNote] = useState('');
 731:   const [mode, setMode] = useState('all');
 732:   const [picked, setPicked] = useState([]);
 733:   const [tried, setTried] = useState(false);
 734:   useEffect(() => { if (open) { setBranchId(null); setLocId(null); setNote(''); setMode('all'); setPicked([]); setTried(false); } }, [open]);
 735: 
 736:   const scope = branchId ? INV_STOCK.filter(s => s.branchId === branchId && (!locId || s.locId === locId)) : [];
 737:   const items = mode === 'all' ? [...new Set(scope.map(s => s.variantId))] : picked;
 738:   const valid = branchId && items.length > 0 && items.length <= CNT_MAX;
 739: 
 740:   const submit = () => {
 741:     setTried(true); if (!valid) return;
 742:     const id = 'c' + Date.now();
 743:     setDb(d => ({ ...d, counts: [{ id, no: 'CNT-2026-000' + (32 + d.counts.length - 3), branchId, locId, status: 'counting', createdBy: 'أحمد سمير', date: '2026-10-23', note,
 744:       lines: items.map(v => ({ variantId: v, system: scope.filter(s => s.variantId === v).reduce((a, s) => a + s.onHand, 0), actual: null })) }, ...d.counts] }));
 745:     toast('تم إنشاء الجرد'); onClose(); go('count', { id });
 746:   };
 747: 
 748:   return (
 749:     <Modal open={open} onClose={onClose} width="max-w-2xl" title="جرد جديد" sub={`حتى ${CNT_MAX} بند عند الإنشاء`}
 750:       footer={<><button className="btn btn-dark" onClick={submit}>إنشاء وبدء العدّ</button><button className="btn btn-soft" onClick={onClose}>إلغاء</button></>}>
 751:       <div className="space-y-4">
 752:         <div className="grid grid-cols-2 gap-4">
 753:           <Field label="الفرع" req error={tried && !branchId ? 'مطلوب' : null}><Sel value={branchId} onChange={v => { setBranchId(v); setLocId(null); setPicked([]); }} placeholder="اختر…" options={branchOpts(b => b.active)} /></Field>
 754:           <Field label="الموقع" hint="اختياري"><Sel value={locId} onChange={setLocId} placeholder={branchId ? 'كل المواقع' : '—'} disabled={!branchId} options={branchId ? locOpts(branchId) : []} /></Field>
 755:         </div>
 756:         <div>
 757:           <span className="field-label">الأصناف</span>
 758:           <div className="seg mb-3">
 759:             <button className={mode === 'all' ? 'on' : ''} onClick={() => setMode('all')}>كل الأصناف في النطاق</button>
 760:             <button className={mode === 'pick' ? 'on' : ''} onClick={() => setMode('pick')}>اختيار أصناف محددة</button>
 761:           </div>
 762:           {mode === 'all' ? (
 763:             <div className="v-subcard p-3.5 flex items-center justify-between">
 764:               <span className="text-[12.5px] c-secondary">{branchId ? 'سيتم إدراج كل SKU له رصيد في النطاق المحدد' : 'اختر الفرع لعرض عدد الأصناف'}</span>
 765:               <span className="num font-display text-[20px] font-bold c-primary">{items.length}</span>
 766:             </div>
 767:           ) : (
 768:             <div className="space-y-2">
 769:               <VariantPicker value={null} onChange={v => v && setPicked(p => p.length < CNT_MAX ? [...p, v] : p)} exclude={picked} placeholder="أضف SKU…" />
 770:               <div className="flex flex-wrap gap-1.5">
 771:                 {picked.map(v => <span key={v} className="badge b-gray !py-1"><span className="mono">{invVariant(v).sku}</span><button onClick={() => setPicked(p => p.filter(x => x !== v))}><Icon n="x" s={11} /></button></span>)}
 772:                 {picked.length === 0 && <span className="text-[11.5px] c-muted">لم تتم إضافة أصناف</span>}
 773:               </div>
 774:             </div>
 775:           )}
 776:           {tried && branchId && items.length === 0 && <div className="text-[11px] mt-1.5" style={{ color: 'var(--badge-red-text)' }}>لا توجد أصناف للجرد</div>}
 777:           <div className="text-[11px] c-muted mt-1.5 num">{items.length} / {CNT_MAX}</div>
 778:         </div>
 779:         <Field label="ملاحظات"><textarea className="inp" rows={2} value={note} onChange={e => setNote(e.target.value)} /></Field>
 780:       </div>
 781:     </Modal>
 782:   );
 783: }
