 785: function CountDetail({ go, params }) {
 786:   const { db, setDb, toast, demoState } = useInv();
 787:   const can = useCan();
 788:   const phase = useLoad('cnt' + params.id);
 789:   const c = db.counts.find(x => x.id === params.id);
 790:   const [vals, setVals] = useState(() => Object.fromEntries((c?.lines || []).map((l, i) => [i, l.actual === null ? '' : String(l.actual)])));
 791:   const [filter, setFilter] = useState('all');
 792:   const [confirm, setConfirm] = useState(false);
 793:   const [busy, setBusy] = useState(false);
 794:   const [err, setErr] = useState(null);
 795:   const [dirty, setDirty] = useState(false);
 796:   if (!c) return null;
 797: 
 798:   const editable = c.status !== 'approved' && can('count.manage');
 799:   const actual = i => vals[i] === '' || vals[i] === undefined ? null : parseFloat(vals[i]);
 800:   const rows = c.lines.map((l, i) => ({ ...l, i, a: actual(i), diff: actual(i) === null ? null : +(actual(i) - l.system).toFixed(4) }));
 801:   const counted = rows.filter(r => r.a !== null).length;
 802:   const shown = rows.filter(r => filter === 'all' || (filter === 'uncounted' && r.a === null) || (filter === 'diff' && r.diff) || (filter === 'match' && r.diff === 0));
 803:   const diffs = rows.filter(r => r.diff);
 804: 
 805:   const saveCounts = () => { setDb(d => ({ ...d, counts: d.counts.map(x => x.id === c.id ? { ...x, status: 'counting', lines: x.lines.map((l, i) => ({ ...l, actual: actual(i) })) } : x) })); setDirty(false); toast('تم حفظ العدّ'); };
 806:   const approve = () => {
 807:     setBusy(true); setErr(null);
 808:     setTimeout(() => {
 809:       setBusy(false);
 810:       if (demoState === 'error') { setErr('تم تنفيذ حركات على بعض الأصناف بعد إنشاء الجرد؛ أعد احتساب كميات النظام قبل الاعتماد. (409)'); return; }
 811:       setDb(d => ({ ...d, counts: d.counts.map(x => x.id === c.id ? { ...x, status: 'approved', lines: x.lines.map((l, i) => ({ ...l, actual: actual(i) })) } : x) }));
 812:       setConfirm(false); toast('تم اعتماد الجرد وترحيل الفروق');
 813:     }, 900);
 814:   };
 815: 
 816:   return (
 817:     <section className="space-y-5">
 818:       <PageHead title={<span className="mono">{c.no}</span>} back={{ label: 'الجرد', onClick: () => go('counts') }}
 819:         sub={<span className="flex items-center gap-2 flex-wrap">{invBranch(c.branchId).name} <span className="c-muted">·</span> {c.locId ? <span className="mono">{invLoc(c.locId).code}</span> : 'كل المواقع'} <Badge cls={INV_CNT_STATUS[c.status].cls} dot>{INV_CNT_STATUS[c.status].label}</Badge></span>}
 820:         actions={c.status !== 'approved' && <>
 821:           {editable && <button className="btn btn-soft" disabled={!dirty} onClick={saveCounts}>حفظ العدّ</button>}
 822:           {can('count.approve')
 823:             ? <button className="btn btn-orange" onClick={() => { setErr(null); setConfirm(true); }} disabled={counted < rows.length}><Icon n="check" s={14} w={2.2} /> اعتماد الجرد</button>
 824:             : <Can perm="count.approve" mode="الاعتماد يتطلب صلاحية" />}
 825:         </>} />
 826: 
 827:       <Phase phase={phase} cols={5} rows={5} empty={<Card><EmptyState icon="clipboard" title="لا توجد بنود في هذا الجرد" /></Card>}>
 828:         <div className="grid grid-cols-2 lg:grid-cols-4 gap-3.5 stagger-item stagger-2">
 829:           <KPI hot label="تم العدّ" icon="clipboard" value={`${counted}/${rows.length}`} sub={counted < rows.length ? `${rows.length - counted} بند لم يُعدّ بعد` : 'اكتمل العدّ'} />
 830:           <KPI label="مطابق" icon="check" value={rows.filter(r => r.diff === 0).length} />
 831:           <KPI label="بفروق" icon="alert" value={diffs.length} />
 832:           <KPI label="صافي الفرق" icon="sliders" value={(() => { const n = diffs.reduce((a, r) => a + r.diff, 0); return (n > 0 ? '+' : '') + invFmt(n); })()} sub="بالوحدات" />
 833:         </div>
 834: 
 835:         <Card stagger={3}>
 836:           <CardHead title="جدول العدّ" right={
 837:             <div className="seg">
 838:               {[['all', 'الكل'], ['uncounted', 'لم يُعدّ'], ['diff', 'بفروق'], ['match', 'مطابق']].map(([k, l]) => <button key={k} className={filter === k ? 'on' : ''} onClick={() => setFilter(k)}>{l}</button>)}
 839:             </div>} />
