1051:         <button onClick={() => set({ low: !f.low })} className="text-right">
1052:           <KPI label="تحت حد إعادة الطلب" icon="alert" value={phase === 'ready' ? lowCount : '—'} sub={f.low ? 'الفلتر مفعّل · اضغط للإلغاء' : 'اضغط لعرضها فقط'} />
1053:         </button>
1054:       </div>
