1059:         <FilterBar active={active} onReset={() => setF({ branchId: null, locId: null, productId: null, variantId: null, low: false })}>
1060:           <BranchLocFilters f={f} set={set} />
1061:           <ProductVariantFilters f={f} set={set} />
1062:           <label className="flex items-center gap-2.5 px-3 py-2 rounded-full cursor-pointer mb-0.5" style={{ background: f.low ? 'var(--accent-orange-light)' : 'var(--bg-card)' }}>
1063:             <Toggle on={f.low} onChange={v => set({ low: v })} />
1064:             <span className="text-[12px] font-medium c-primary">المخزون المنخفض فقط</span>
1065:           </label>
1066:         </FilterBar>
1067:         <Phase phase={phase} cols={10} rows={7}
1068:           empty={<EmptyState icon="box" title="لا توجد أرصدة مسجّلة بعد" sub="سجّل الكميات الافتتاحية عن طريق تسوية زيادة مع سبب واضح مثل «رصيد افتتاحي»."
1069:             action={<Can perm="stock.adjust"><button className="btn btn-dark btn-sm" onClick={() => go('adjust')}><Icon n="plus" s={13} /> إدخال رصيد افتتاحي</button></Can>} />}>
1070:           {rows.length === 0 ? <EmptyState icon="filter" title="لا توجد أرصدة تطابق الفلاتر" sub="غيّر الفلاتر أو امسحها لعرض كل الأرصدة." /> : (
1071:             <div className="overflow-x-auto -mx-1 px-1">
1072:               <table className="vt">
