1089:                         <td className="t-num num c-secondary">{invFmt(s.reserved)}</td>
1090:                         <td className="t-num num" style={{ color: s.damaged ? 'var(--badge-red-text)' : 'var(--text-muted)' }}>{invFmt(s.damaged)}</td>
1091:                         <td className="t-num num" style={{ color: s.inTransit ? 'var(--badge-blue-text)' : 'var(--text-muted)' }}>{invFmt(s.inTransit)}</td>
1092:                         <td className="t-num">
1093:                           <div className="flex flex-col items-end gap-1">
1094:                             <span className={`num font-bold ${low ? '' : 'c-primary'}`} style={low ? { color: 'var(--accent-orange)' } : {}}>{invFmt(s.available)}</span>
1095:                             <span className="w-16 h-1 rounded-full hatched overflow-hidden flex justify-end" style={{ direction: 'ltr' }}>
1096:                               <span className="block h-full rounded-full" style={{ width: pct + '%', background: low ? 'var(--accent-orange)' : 'var(--text-primary)' }} />
1097:                             </span>
1098:                           </div>
1099:                         </td>
1100:                         <td className="t-num num c-muted">{invFmt(s.reorder)}</td>
1101:                         <td className="num text-[11.5px] c-muted">{s.updated}</td>
1102:                         <td>
1103:                           <div className="flex items-center gap-0.5 justify-end">
1104:                             <button className="icon-btn" title="حركات الصنف" onClick={() => go('moves', { variantId: s.variantId, productId: invVariant(s.variantId).productId, branchId: s.branchId })}><Icon n="history" s={15} /></button>
1105:                             {can('stock.adjust') && <button className="icon-btn" title="تسوية" onClick={() => go('adjust', { branchId: s.branchId, locId: s.locId, variantId: s.variantId })}><Icon n="sliders" s={15} /></button>}
1106:                           </div>
1107:                         </td>
1108:                       </tr>
1109:                     );
1110:                   })}
1111:                 </tbody>
1112:               </table>
1113:             </div>
1114:           )}
1115:         </Phase>
1116:       </Card>
1117:     </section>
1118:   );
1119: }
1120: 
1121: // ---------------- 4. Adjustment ----------------
1122: const ADJ_TYPES = {
1123:   increase:   { label: 'زيادة',              cls: 'b-green', sign: '+' },
1124:   decrease:   { label: 'نقصان',              cls: 'b-red',   sign: '−' },
1125:   dmg_mark:   { label: 'تسجيل تالف',         cls: 'b-amber', sign: '→' },
1126:   dmg_write:  { label: 'إعدام تالف',         cls: 'b-red',   sign: '×' },
1127:   dmg_restore:{ label: 'استرجاع من التالف',  cls: 'b-blue',  sign: '←' },
1128: };
1129: const ADJ_MAX = 100;
1130: let __adjLineId = 1;
1131: const newAdjLine = (p = {}) => ({ key: __adjLineId++, variantId: null, type: 'increase', qty: '', reason: '', ...p });
1132: 
1133: function AdjustScreen({ go, params }) {
1134:   const { toast, demoState } = useInv();
1135:   const can = useCan();
1136:   const [branchId, setBranchId] = useState(params.branchId || null);
1137:   const [locId, setLocId] = useState(params.locId || null);
1138:   const [lines, setLines] = useState(() => [newAdjLine(params.variantId ? { variantId: params.variantId } : {})]);
1139:   const [tried, setTried] = useState(false);
1140:   const [confirm, setConfirm] = useState(false);
1141:   const [busy, setBusy] = useState(false);
1142:   const [srvErr, setSrvErr] = useState(null);
1143:   const [opening, setOpening] = useState(false);
1144: 
1145:   if (!can('stock.adjust')) return <NoPerm title="تسوية المخزون" perm="تسوية المخزون" go={go} />;
1146: 
1147:   const upd = (key, p) => setLines(ls => ls.map(l => l.key === key ? { ...l, ...p } : l));
1148:   const lineErr = l => {
1149:     const e = {};
1150:     if (!l.variantId) e.variantId = true;
1151:     const q = parseFloat(l.qty);
1152:     if (!l.qty || !(q > 0)) e.qty = 'كمية موجبة';
1153:     if (!l.reason.trim()) e.reason = true;
1154:     return e;
1155:   };
1156:   const errs = lines.map(lineErr);
1157:   const valid = branchId && errs.every(e => !Object.keys(e).length);
1158:   const dupes = lines.filter((l, i) => l.variantId && lines.findIndex(x => x.variantId === l.variantId && x.type === l.type) !== i).length;
1159: 
1160:   const stockOf = vid => INV_STOCK.find(s => s.variantId === vid && s.branchId === branchId && (!locId || s.locId === locId));
1161: 
1162:   const applyOpening = on => {
1163:     setOpening(on);
1164:     setLines(ls => ls.map(l => on ? { ...l, type: 'increase', reason: l.reason || 'رصيد افتتاحي' } : l));
1165:   };
1166: 
1167:   const execute = () => {
1168:     setBusy(true); setSrvErr(null);
1169:     setTimeout(() => {
1170:       setBusy(false);
1171:       if (demoState === 'error') { setSrvErr('الكمية المطلوب خصمها في البند ٢ أكبر من الرصيد المتاح (Insufficient stock · 422).'); return; }
1172:       setConfirm(false); toast(`تم تنفيذ التسوية · ${lines.length} بند`);
1173:       go('moves', { branchId });
1174:     }, 900);
1175:   };
1176: 
1177:   const totals = Object.keys(ADJ_TYPES).map(k => ({ k, n: lines.filter(l => l.type === k && l.variantId).length })).filter(x => x.n);
1178: 
1179:   return (
1180:     <section className="space-y-5">
1181:       <PageHead title="تسوية المخزون" back={{ label: 'أرصدة المخزون', onClick: () => go('stock') }}
1182:         sub="زيادة أو خصم كميات، أو نقلها من وإلى التالف. التسوية تُنفَّذ كعملية واحدة وتنعكس فورًا على الأرصدة والحركات." />
1183: 
1184:       <div className="grid grid-cols-1 lg:grid-cols-12 gap-5 items-start">
1185:         <div className="lg:col-span-9 space-y-5">
1186:           <Card stagger={2}>
1187:             <CardHead title="بيانات العملية" />
1188:             <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
1189:               <Field label="الفرع / المخزن" req error={tried && !branchId ? 'اختر الفرع' : null}>
1190:                 <Sel value={branchId} onChange={v => { setBranchId(v); setLocId(null); }} placeholder="اختر…" options={branchOpts(b => b.active)} className={tried && !branchId ? 'err' : ''} />
1191:               </Field>
1192:               <Field label="موقع التخزين" hint="اختياري — يطبَّق على كل البنود">
1193:                 <Sel value={locId} onChange={setLocId} placeholder={branchId ? 'بدون موقع محدد' : 'اختر الفرع أولًا'} disabled={!branchId} options={branchId ? locOpts(branchId) : []} />
1194:               </Field>
1195:               <div>
1196:                 <span className="field-label">إدخال رصيد افتتاحي</span>
1197:                 <label className="v-subcard px-3.5 py-2 flex items-center justify-between cursor-pointer" style={{ borderRadius: 12 }}>
1198:                   <span className="text-[12px] c-secondary">كل البنود = زيادة</span>
1199:                   <Toggle on={opening} onChange={applyOpening} />
1200:                 </label>
1201:               </div>
1202:             </div>
1203:             {opening && <div className="mt-4"><InlineAlert kind="blue" icon="info" title="رصيد افتتاحي">تُسجَّل الكميات الافتتاحية حاليًا كتسوية زيادة. اكتب سببًا واضحًا لكل بند حتى يسهل تتبّعها في سجل الحركات.</InlineAlert></div>}
1204:           </Card>
1205: 
1206:           <Card stagger={3}>
1207:             <CardHead title="البنود" meta={<span className="num">{lines.length} / {ADJ_MAX}</span>}
1208:               right={<button className="btn btn-soft btn-sm" disabled={lines.length >= ADJ_MAX} onClick={() => setLines(ls => [...ls, newAdjLine(opening ? { reason: 'رصيد افتتاحي' } : {})])}><Icon n="plus" s={13} /> إضافة بند</button>} />
1209:             {dupes > 0 && <div className="mb-3"><InlineAlert kind="amber" title="بنود مكررة">يوجد {dupes} بند مكرر بنفس SKU ونفس نوع التسوية — سيتم دمجها عند التنفيذ.</InlineAlert></div>}
1210:             <div className="overflow-x-auto">
1211:               <table className="vt">
1212:                 <thead><tr><th className="w-8">#</th><th style={{ minWidth: 280 }}>المنتج / المتغير</th><th style={{ minWidth: 170 }}>نوع التسوية</th><th style={{ minWidth: 120 }}>الكمية</th><th style={{ minWidth: 200 }}>السبب</th><th></th></tr></thead>
1213:                 <tbody>
1214:                   {lines.map((l, i) => {
1215:                     const e = tried ? errs[i] : {};
1216:                     const st = l.variantId && branchId ? stockOf(l.variantId) : null;
1217:                     return (
1218:                       <tr key={l.key} className="align-top">
1219:                         <td className="num c-muted pt-4">{i + 1}</td>
1220:                         <td>
1221:                           <div className={e.variantId ? 'rounded-[12px] ring-1 ring-[var(--badge-red-text)]' : ''}><VariantPicker small value={l.variantId} onChange={v => upd(l.key, { variantId: v })} /></div>
1222:                           {st && <div className="text-[10.5px] c-muted mt-1 pr-1">المتاح <span className="num c-primary font-semibold">{invFmt(st.available)}</span> · التالف <span className="num">{invFmt(st.damaged)}</span></div>}
1223:                           {l.variantId && branchId && !st && <div className="text-[10.5px] c-muted mt-1 pr-1">لا يوجد رصيد حالي في هذا الفرع</div>}
1224:                         </td>
1225:                         <td><Sel small value={l.type} onChange={v => upd(l.key, { type: v || 'increase' })} options={Object.entries(ADJ_TYPES).map(([k, t]) => ({ value: k, label: t.label }))} /></td>
1226:                         <td>
1227:                           <NumInput small value={l.qty} onChange={v => upd(l.key, { qty: v })} err={e.qty} placeholder="0.0000" />
1228:                           {e.qty && <div className="text-[10.5px] mt-1" style={{ color: 'var(--badge-red-text)' }}>{e.qty}</div>}
1229:                         </td>
1230:                         <td><input className={`inp inp-sm ${e.reason ? 'err' : ''}`} value={l.reason} onChange={ev => upd(l.key, { reason: ev.target.value })} placeholder="مثال: كسر أثناء التفريغ" /></td>
1231:                         <td className="pt-3"><button className="icon-btn" disabled={lines.length === 1} onClick={() => setLines(ls => ls.filter(x => x.key !== l.key))}><Icon n="trash" s={14} /></button></td>
1232:                       </tr>
1233:                     );
1234:                   })}
1235:                 </tbody>
1236:               </table>
1237:             </div>
1238:             <div className="mt-3 text-[11px] c-muted flex items-center gap-1.5"><Icon n="info" s={12} /> الكميات موجبة دائمًا وتقبل حتى 4 منازل عشرية. اتجاه الحركة يحدده نوع التسوية.</div>
1239:           </Card>
1240:         </div>
1241: 
1242:         <div className="lg:col-span-3 lg:sticky lg:top-5">
1243:           <Card stagger={4}>
1244:             <h3 className="font-display text-[15px] font-semibold c-primary mb-3">ملخص</h3>
1245:             <div className="space-y-2 text-[12.5px]">
1246:               <div className="flex justify-between"><span className="c-secondary">الفرع</span><span className="font-medium c-primary">{branchId ? invBranch(branchId).name : '—'}</span></div>
1247:               <div className="flex justify-between"><span className="c-secondary">الموقع</span><span className="mono c-primary">{locId ? invLoc(locId).code : '—'}</span></div>
1248:               <div className="flex justify-between"><span className="c-secondary">عدد البنود</span><span className="num font-semibold c-primary">{lines.length}</span></div>
1249:             </div>
1250:             <div className="h-px my-4" style={{ background: 'var(--divider-color)' }} />
1251:             <div className="space-y-1.5">
1252:               {totals.length === 0 && <div className="text-[11.5px] c-muted">لم يتم اختيار أصناف بعد</div>}
1253:               {totals.map(t => <div key={t.k} className="flex items-center justify-between"><Badge cls={ADJ_TYPES[t.k].cls}>{ADJ_TYPES[t.k].label}</Badge><span className="num text-[12px] c-primary font-semibold">{t.n}</span></div>)}
1254:             </div>
1255:             <div className="mt-5 space-y-2">
1256:               <button className="btn btn-orange w-full" onClick={() => { setTried(true); if (valid) { setSrvErr(null); setConfirm(true); } }}>
1257:                 <Icon n="check" s={14} w={2.2} /> تنفيذ التسوية
1258:               </button>
1259:               <button className="btn btn-soft w-full" onClick={() => go('stock')}>إلغاء</button>
1260:             </div>
1261:             {tried && !valid && <div className="text-[11px] mt-3" style={{ color: 'var(--badge-red-text)' }}>أكمل الحقول المطلوبة المظللة بالأحمر.</div>}
1262:           </Card>
1263:         </div>
1264:       </div>
1265: 
1266:       <ConfirmDialog open={confirm} onClose={() => setConfirm(false)} onConfirm={execute} busy={busy} error={srvErr}
1267:         title="تأكيد تنفيذ التسوية" confirmLabel="تنفيذ الآن"
1268:         body={<div className="space-y-3">
1269:           <p>سيتم تنفيذ <b className="c-primary num">{lines.length}</b> بند على <b className="c-primary">{branchId && invBranch(branchId).name}</b>{locId && <> — موقع <span className="mono">{invLoc(locId).code}</span></>}. لا يمكن تعديل أو حذف الحركات بعد التنفيذ؛ للتصحيح أنشئ تسوية عكسية.</p>
1270:           <div className="v-subcard p-3 space-y-1.5 max-h-40 overflow-y-auto">
1271:             {lines.filter(l => l.variantId).map(l => (
1272:               <div key={l.key} className="flex items-center justify-between text-[12px]">
1273:                 <span className="flex items-center gap-2"><Sku id={l.variantId} /><Badge cls={ADJ_TYPES[l.type].cls}>{ADJ_TYPES[l.type].label}</Badge></span>
1274:                 <span className="num font-semibold c-primary">{invFmt(l.qty)}</span>
1275:               </div>
1276:             ))}
1277:           </div>
1278:         </div>} />
1279:     </section>
1280:   );
1281: }
1282: 
1283: // ---------------- 5. Movements ----------------
1284: function MovesScreen({ go, params }) {
1285:   const can = useCan();
1286:   const [f, setF] = useState({ branchId: params.branchId || null, locId: null, productId: params.productId || null, variantId: params.variantId || null, type: null, from: '', to: '' });
1287:   const [cursor, setCursor] = useState(0);
1288:   const PAGE = 12;
1289:   const phase = useLoad(JSON.stringify(f) + cursor);
1290:   const set = p => { setF(x => ({ ...x, ...p })); setCursor(0); };
1291:   const showCost = can('cost.view');
1292: 
1293:   const rows = INV_MOVES.filter(m => {
1294:     const v = invVariant(m.variantId); const d = m.date.slice(0, 10);
1295:     return (!f.branchId || m.branchId === f.branchId) && (!f.locId || m.locId === f.locId) && (!f.productId || v.productId === f.productId)
1296:       && (!f.variantId || m.variantId === f.variantId) && (!f.type || m.type === f.type) && (!f.from || d >= f.from) && (!f.to || d <= f.to);
1297:   });
1298:   const page = rows.slice(cursor, cursor + PAGE);
1299:   const hasNext = cursor + PAGE < rows.length;
1300:   const active = ['branchId', 'locId', 'productId', 'variantId', 'type', 'from', 'to'].filter(k => f[k]).length;
1301: 
1302:   return (
1303:     <section className="space-y-5">
1304:       <PageHead title="حركات المخزون" sub="سجل غير قابل للتعديل لكل عملية أثّرت على الكميات." />
1305:       <Card stagger={2}>
1306:         <CardHead title="السجل" meta={<span className="flex items-center gap-1.5"><Icon n="lock" s={11} /> عرض فقط</span>}
1307:           right={!showCost && <span className="text-[11px] c-muted flex items-center gap-1"><Icon n="lock" s={11} /> تكلفة الوحدة مخفية حسب صلاحيتك</span>} />
1308:         <FilterBar active={active} onReset={() => set({ branchId: null, locId: null, productId: null, variantId: null, type: null, from: '', to: '' })}>
1309:           <BranchLocFilters f={f} set={set} />
1310:           <ProductVariantFilters f={f} set={set} />
1311:           <FItem label="نوع الحركة" w="w-40"><Sel small value={f.type} onChange={v => set({ type: v })} placeholder="كل الأنواع" options={Object.entries(INV_MOVE_TYPES).map(([k, t]) => ({ value: k, label: t.label }))} className="!bg-[var(--bg-card)]" /></FItem>
1312:           <FItem label="من تاريخ" w="w-36"><input type="date" value={f.from} onChange={e => set({ from: e.target.value })} className="inp inp-sm num !bg-[var(--bg-card)]" /></FItem>
1313:           <FItem label="إلى تاريخ" w="w-36"><input type="date" value={f.to} onChange={e => set({ to: e.target.value })} className="inp inp-sm num !bg-[var(--bg-card)]" /></FItem>
1314:         </FilterBar>
1315: 
1316:         <Phase phase={phase} cols={9} rows={8}
1317:           empty={<EmptyState icon="history" title="لا توجد حركات بعد" sub="ستظهر هنا كل عمليات التسوية والتحويل والجرد واستلام الإنتاج بمجرد تنفيذها." />}>
1318:           {page.length === 0 ? <EmptyState icon="filter" title="لا توجد حركات تطابق الفلاتر" sub="وسّع نطاق التاريخ أو امسح بعض الفلاتر." /> : (
1319:             <>
1320:               <div className="overflow-x-auto">
1321:                 <table className="vt">
1322:                   <thead><tr>
1323:                     <th>التاريخ</th><th>المرجع</th><th>SKU</th><th>الفرع</th><th>الموقع</th><th>نوع الحركة</th>
1324:                     <th className="t-num">الكمية</th><th className="t-num">الرصيد قبل ← بعد</th>{showCost && <th className="t-num">تكلفة الوحدة</th>}<th>المنفّذ</th><th>ملاحظات</th>
1325:                   </tr></thead>
1326:                   <tbody>
1327:                     {page.map(m => {
1328:                       const t = INV_MOVE_TYPES[m.type];
1329:                       return (
1330:                         <tr key={m.id}>
1331:                           <td className="num text-[11.5px] c-secondary">{m.date}</td>
1332:                           <td><span className="mono text-[11.5px] font-semibold c-orange">{m.ref}</span></td>
1333:                           <td><div className="flex flex-col gap-0.5"><Sku id={m.variantId} /><span className="text-[10.5px] c-muted">{invVariant(m.variantId).productName}</span></div></td>
1334:                           <td className="c-secondary">{invBranch(m.branchId).name}</td>
1335:                           <td className="mono text-[11.5px] c-secondary">{invLoc(m.locId).code}</td>
1336:                           <td><Badge cls={t.cls}>{t.label}</Badge></td>
1337:                           <td className="t-num num font-bold" style={{ color: m.qty > 0 ? 'var(--badge-green-text)' : 'var(--badge-red-text)' }}>{m.qty > 0 ? '+' : '−'}{invFmt(Math.abs(m.qty))}</td>
1338:                           <td className="t-num num text-[12px]"><span className="c-muted">{invFmt(m.before)}</span> <span className="c-muted mx-1">→</span> <span className="font-semibold c-primary">{invFmt(m.after)}</span></td>
1339:                           {showCost && <td className="t-num num c-secondary">{invMoney(m.unitCost)}</td>}
1340:                           <td className="c-secondary">{m.user}</td>
1341:                           <td className="text-[11.5px] c-muted max-w-[160px] truncate">{m.note || '—'}</td>
1342:                         </tr>
1343:                       );
1344:                     })}
1345:                   </tbody>
1346:                 </table>
1347:               </div>
1348:               <div className="flex items-center justify-between mt-4 pt-4" style={{ borderTop: '1px solid var(--divider-color)' }}>
1349:                 <span className="text-[11.5px] c-muted">عرض <span className="num">{page.length}</span> حركة · التنقل بالمؤشر</span>
1350:                 <div className="flex items-center gap-2">
1351:                   <button className="btn btn-soft btn-sm" disabled={cursor === 0} onClick={() => setCursor(c => Math.max(0, c - PAGE))}><Icon n="chevR" s={13} /> السابق</button>
1352:                   <button className="btn btn-dark btn-sm" disabled={!hasNext} onClick={() => setCursor(c => c + PAGE)}>التالي <Icon n="chevL" s={13} /></button>
1353:                 </div>
1354:               </div>
1355:             </>
1356:           )}
1357:         </Phase>
1358:       </Card>
1359:     </section>
1360:   );
1361: }
1362: 
1363: function NoPerm({ title, perm, go }) {
1364:   return (
1365:     <section className="space-y-5">
1366:       <PageHead title={title} />
1367:       <Card><EmptyState icon="lock" title="لا تملك صلاحية الوصول لهذه الشاشة" sub={`تتطلب هذه العملية صلاحية «${perm}». تواصل مع مدير النظام لمنحك الصلاحية.`}
1368:         action={<button className="btn btn-soft btn-sm" onClick={() => go('stock')}>العودة لأرصدة المخزون</button>} /></Card>
1369:     </section>
1370:   );
1371: }
1372: 
1373: Object.assign(window, { StockScreen, AdjustScreen, MovesScreen, NoPerm, FilterBar, FItem, BranchLocFilters, ProductVariantFilters });// ============ 6. Stock transfers ============
1374: 
1375: const TR_FLOW = ['draft', 'approved', 'shipped', 'received'];
1376: let __trKey = 1;
1377: const newTrLine = (p = {}) => ({ key: __trKey++, variantId: null, fromLoc: null, toLoc: null, req: '', ...p });
1378: 
1379: function TrStatus({ s }) { const t = INV_TR_STATUS[s]; return <Badge cls={t.cls} dot>{t.label}</Badge>; }
1380: 
1381: function TransfersScreen({ go }) {
1382:   const { db } = useInv();
