1456:   const [tried, setTried] = useState(false);
1457:   const [busy, setBusy] = useState(false);
1458: 
1459:   if (!can('transfers.create')) return <NoPerm title="تحويل جديد" perm="إنشاء التحويلات" go={go} />;
1460: 
1461:   const same = from && to && from === to;
1462:   const upd = (key, p) => setLines(ls => ls.map(l => l.key === key ? { ...l, ...p } : l));
1463:   const lineBad = l => !l.variantId || !(parseFloat(l.req) > 0);
1464:   const valid = from && to && !same && lines.length && lines.every(l => !lineBad(l));
1465: 
1466:   const save = () => {
1467:     setTried(true); if (!valid) return;
1468:     setBusy(true);
1469:     setTimeout(() => {
1470:       const data = { from, to, note, lines: lines.map(l => ({ variantId: l.variantId, fromLoc: l.fromLoc, toLoc: l.toLoc, req: parseFloat(l.req), appr: null, ship: null, recv: null })) };
1471:       let id = existing?.id;
