1475:     }, 600);
1476:   };
1477: 
1478:   const avail = (vid, br, loc) => INV_STOCK.filter(s => s.variantId === vid && s.branchId === br && (!loc || s.locId === loc)).reduce((a, s) => a + s.available, 0);
1479: 
1480:   return (
1481:     <section className="space-y-5">
1482:       <PageHead title={existing ? `تعديل ${existing.no}` : 'تحويل جديد'} back={{ label: 'التحويلات المخزنية', onClick: () => go(existing ? 'transfer' : 'transfers', existing ? { id: existing.id } : {}) }}
1483:         actions={<><button className="btn btn-soft" onClick={() => go('transfers')}>إلغاء</button><button className="btn btn-dark" onClick={save} disabled={busy}>{busy && <span className="w-3.5 h-3.5 rounded-full border-2 border-current border-t-transparent animate-spin" />} حفظ كمسودة</button></>} />
1484: 
1485:       <Card stagger={2}>
1486:         <div className="grid grid-cols-1 md:grid-cols-[1fr_auto_1fr] gap-4 items-end">
1487:           <Field label="فرع المصدر" req error={tried && !from ? 'مطلوب' : null}>
1488:             <Sel value={from} onChange={v => { setFrom(v); setLines(ls => ls.map(l => ({ ...l, fromLoc: null }))); }} placeholder="من…" options={branchOpts(b => b.active)} className={(tried && !from) || same ? 'err' : ''} />
1489:           </Field>
1490:           <button type="button" onClick={() => { setFrom(to); setTo(from); setLines(ls => ls.map(l => ({ ...l, fromLoc: l.toLoc, toLoc: l.fromLoc }))); }} className="w-10 h-10 rounded-full v-subcard flex items-center justify-center c-orange mx-auto mb-0.5" title="تبديل">
1491:             <Icon n="swap" s={16} />
1492:           </button>
1493:           <Field label="فرع الوجهة" req error={tried && !to ? 'مطلوب' : null}>
1494:             <Sel value={to} onChange={v => { setTo(v); setLines(ls => ls.map(l => ({ ...l, toLoc: null }))); }} placeholder="إلى…" options={branchOpts(b => b.active)} className={(tried && !to) || same ? 'err' : ''} />
1495:           </Field>
1496:         </div>
1497:         {same && <div className="mt-3"><InlineAlert kind="red" title="المصدر والوجهة متطابقان">العملية الحالية تشترط اختلاف فرع المصدر عن فرع الوجهة. للنقل بين مواقع داخل نفس الفرع استخدم التسوية.</InlineAlert></div>}
1498:         <Field label="ملاحظات" className="mt-4"><textarea className="inp" rows={2} value={note} onChange={e => setNote(e.target.value)} placeholder="سبب التحويل أو تعليمات للشحن…" /></Field>
1499:       </Card>
1500: 
1501:       <Card stagger={3}>
1502:         <CardHead title="البنود" meta={<span className="num">{lines.length}</span>} right={<button className="btn btn-soft btn-sm" onClick={() => setLines(ls => [...ls, newTrLine()])}><Icon n="plus" s={13} /> إضافة بند</button>} />
1503:         <div className="overflow-x-auto">
1504:           <table className="vt">
1505:             <thead><tr><th className="w-8">#</th><th style={{ minWidth: 280 }}>المتغير / SKU</th><th style={{ minWidth: 170 }}>موقع المصدر</th><th style={{ minWidth: 170 }}>موقع الوجهة</th><th style={{ minWidth: 130 }}>الكمية المطلوبة</th><th></th></tr></thead>
1506:             <tbody>
1507:               {lines.map((l, i) => {
