1515:                       {a !== null && <div className="text-[10.5px] c-muted mt-1 pr-1">المتاح في المصدر: <span className="num font-semibold c-primary">{invFmt(a)}</span></div>}
1516:                     </td>
1517:                     <td><Sel small value={l.fromLoc} onChange={v => upd(l.key, { fromLoc: v })} placeholder={from ? 'أي موقع' : '—'} disabled={!from} options={from ? locOpts(from) : []} /></td>
1518:                     <td><Sel small value={l.toLoc} onChange={v => upd(l.key, { toLoc: v })} placeholder={to ? 'موقع الاستلام الافتراضي' : '—'} disabled={!to} options={to ? locOpts(to) : []} /></td>
1519:                     <td>
