1521:                       {over && <div className="text-[10.5px] mt-1" style={{ color: 'var(--badge-amber-text)' }}>أكبر من المتاح حاليًا</div>}
1522:                     </td>
1523:                     <td className="pt-3"><button className="icon-btn" disabled={lines.length === 1} onClick={() => setLines(ls => ls.filter(x => x.key !== l.key))}><Icon n="trash" s={14} /></button></td>
1524:                   </tr>
1525:                 );
1526:               })}
1527:             </tbody>
1528:           </table>
1529:         </div>
1530:       </Card>
1531:     </section>
1532:   );
1533: }
