1541:   const [qtys, setQtys] = useState({});
1542:   const [confirm, setConfirm] = useState(null);
1543:   const [busy, setBusy] = useState(false);
1544:   const [err, setErr] = useState(null);
1545: 
1546:   if (!t) return <section><Card><EmptyState icon="alert" title="التحويل غير موجود" action={<button className="btn btn-soft btn-sm" onClick={() => go('transfers')}>العودة</button>} /></Card></section>;
1547: 
1548:   const idx = TR_FLOW.indexOf(t.status);
1549:   const stageMeta = {
1550:     approve: { col: 'appr', srcCol: 'req', label: 'اعتماد', next: 'approved', perm: 'transfers.approve', hint: 'حدّد الكمية المعتمدة لكل بند (لا تتجاوز المطلوبة).' },
1551:     ship:    { col: 'ship', srcCol: 'appr', label: 'شحن', next: 'shipped', perm: 'transfers.ship', hint: 'أدخل الكمية المشحونة فعليًا. سيتم خصمها من المصدر وتظهر «قيد النقل».' },
1552:     receive: { col: 'recv', srcCol: 'ship', label: 'استلام', next: 'received', perm: 'transfers.receive', hint: 'أدخل الكمية المستلمة فعليًا في الوجهة. أي فرق يُسجَّل في الملاحظات.' },
1553:   };
1554:   const startStage = s => { const m = stageMeta[s]; setStage(s); setQtys(Object.fromEntries(t.lines.map((l, i) => [i, String(l[m.srcCol] ?? '')]))); };
1555:   const commit = () => {
1556:     const m = stageMeta[stage];
1557:     setBusy(true); setErr(null);
1558:     setTimeout(() => {
1559:       setBusy(false);
1560:       if (demoState === 'error') { setErr('تغيّرت حالة التحويل بواسطة مستخدم آخر. حدّث الصفحة وأعد المحاولة. (409)'); return; }
1561:       setDb(d => ({ ...d, transfers: d.transfers.map(x => x.id === t.id ? { ...x, status: m.next, lines: x.lines.map((l, i) => ({ ...l, [m.col]: parseFloat(qtys[i]) || 0 })) } : x) }));
1562:       setConfirm(null); setStage(null); toast(`تم ${m.label} التحويل`);
1563:     }, 800);
1564:   };
1565:   const cancel = () => {
1566:     setBusy(true);
1567:     setTimeout(() => { setBusy(false); setDb(d => ({ ...d, transfers: d.transfers.map(x => x.id === t.id ? { ...x, status: 'cancelled' } : x) })); setConfirm(null); toast('تم إلغاء التحويل'); }, 600);
1568:   };
1569: 
1570:   const actions = [];
1571:   if (!stage) {
1572:     if (t.status === 'draft') {
1573:       if (can('transfers.create')) actions.push(<button key="e" className="btn btn-soft" onClick={() => go('transfer-edit', { id: t.id })}><Icon n="edit" s={14} /> تعديل</button>);
1574:       if (can('transfers.approve')) actions.push(<button key="a" className="btn btn-dark" onClick={() => startStage('approve')}><Icon n="check" s={14} /> اعتماد</button>);
1575:     }
