1579:   }
1580:   const nextNeedsPerm = !stage && actions.length === 0 && !['received', 'cancelled'].includes(t.status);
1581: 
1582:   const steps = [['draft', 'مسودة', 'edit'], ['approved', 'معتمد', 'check'], ['shipped', 'مشحون', 'truck'], ['received', 'مستلم', 'inbox']];
1583: 
1584:   return (
