1588:         actions={actions.length ? actions : nextNeedsPerm ? <span className="inline-flex items-center gap-1.5 text-[12px] c-muted px-3.5 py-2 rounded-full v-subcard"><Icon n="lock" s={12} /> الخطوة التالية تتطلب صلاحية أخرى</span> : null} />
1589: 
1590:       <Phase phase={phase} cols={6} rows={3} empty={<Card><EmptyState icon="swap" title="لا توجد بنود" /></Card>}>
