1603:                         </span>
1604:                         <span className={`text-[11.5px] ${i === idx ? 'font-semibold c-primary' : 'c-secondary'}`}>{l}</span>
1605:                       </div>
1606:                       {i < steps.length - 1 && <div className={`step-line mb-5 ${i < idx ? 'done' : ''}`} />}
