1694: // Simulated fetch lifecycle: loading → (live | empty | error) per demo tweak
1695: function useLoad(dep) {
1696:   const { demoState, reloadKey } = useInv();
1697:   const [phase, setPhase] = useState('loading');
1698:   useEffect(() => {
1699:     setPhase('loading');
1700:     if (demoState === 'loading') return;
1701:     const t = setTimeout(() => setPhase(demoState === 'live' ? 'ready' : demoState), 550);
1702:     return () => clearTimeout(t);
1703:   }, [demoState, reloadKey, dep]);
1704:   return phase;
1705: }
