2034: function NumInput({ value, onChange, decimals = 4, integer, small, placeholder = '0', className = '', err }) {
2035:   return (
2036:     <input inputMode="decimal" value={value ?? ''} placeholder={placeholder}
2037:       onChange={e => {
2038:         let s = e.target.value.replace(/[^\d.]/g, '');
2039:         if (integer) s = s.replace(/\./g, '');
2040:         const parts = s.split('.');
2041:         if (parts.length > 2) s = parts[0] + '.' + parts.slice(1).join('');
2042:         if (parts[1] && parts[1].length > decimals) s = parts[0] + '.' + parts[1].slice(0, decimals);
2043:         onChange(s);
2044:       }}
2045:       className={`inp ${small ? 'inp-sm' : ''} num text-left ${err ? 'err' : ''} ${className}`} />
2046:   );
2047: }
