 95:     public function store(StoreProductRequest $request): JsonResponse
 96:     {
 97:         $data = $request->validated();
 98:         if (! $request->user()->can('products.view_cost')) {
 99:             foreach ($data['variants'] ?? [] as $index => $variant) {
100:                 unset($data['variants'][$index]['cost_price']);
