17: 
18: class ProductionReceiptController extends Controller
19: {
20:     public function options(Request $request): JsonResponse
21:     {
22:         abort_unless($request->user()->can('inventory.view'), 403);
23:         $filters = $request->validate(['search' => ['nullable', 'string', 'max:100']]);
24:         $branch = app(BranchAccess::class)->restrictedBranch($request->user());
25:         $branches = Branch::where('is_active', true)->when($branch, fn ($q) => $q->whereKey($branch))
26:             ->with(['locations' => fn ($q) => $q->where('is_active', true)])->orderBy('id')->get();
27:         $variants = ProductVariant::where('is_active', true)->whereHas('product')
28:             ->with('product:id,name_ar')->when($filters['search'] ?? null, function ($q, $search): void {
29:                 $pattern = SearchTerm::pattern($search);
30:                 $q->where(fn ($q) => $q->whereLike('sku', $pattern)->orWhereLike('barcode', $pattern)
31:                     ->orWhereHas('product', fn ($p) => $p->whereLike('name_ar', $pattern)->orWhereLike('name_en', $pattern)));
32:             })->orderBy('id')->limit(50)->get();
33: 
34:         return response()->json(['data' => [
35:             'branches' => $branches->map(fn ($b) => ['id' => $b->id, 'name' => $b->name,
36:                 'locations' => $b->locations->map(fn ($l) => ['id' => $l->id, 'name' => $l->name])]),
37:             'variants' => $variants->map(fn ($v) => ['id' => $v->id, 'label' => $v->product->name_ar.' / '.$v->sku]),
38:         ]]);
39:     }
40: 
41:     public function index(Request $request): JsonResponse
42:     {
43:         $request->user()->can('inventory.view') || abort(403);
44:         $filters = $request->validate(['per_page' => ['nullable', 'integer', 'min:1', 'max:100']]);
45:         $branch = app(BranchAccess::class)->restrictedBranch($request->user());
46:         $receipts = ProductionReceipt::query()->when($branch, fn ($q) => $q->where('branch_id', $branch))
47:             ->orderByDesc('id')->paginate($filters['per_page'] ?? 15);
48:         if (! $request->user()->can('products.view_cost')) {
49:             $receipts->getCollection()->each(function ($receipt): void {
50:                 $receipt->items = array_map(function ($item) {
51:                     unset($item['unit_cost']);
52: 
53:                     return $item;
54:                 }, $receipt->items);
55:             });
56:         }
57: 
58:         return response()->json($receipts);
59:     }
60: 
61:     public function store(StoreProductionReceiptRequest $request, ProductionReceiptService $service): JsonResponse
62:     {
63:         $key = $this->idempotencyKey($request);
64:         abort_if($key === null, 422, 'مفتاح Idempotency-Key مطلوب لاستلام الإنتاج.');
65:         $receipt = $service->receive($request->validated(), $request->user()->id, $key);
66: 
67:         return response()->json(['message' => 'تم استلام الإنتاج وإضافة الكميات للمخزون.', 'data' => $receipt], 201);
68:     }
69: } 1: <?php
