17: class ProductionReceiptService
18: {
19:     public function __construct(private readonly InventoryService $inventory) {}
20: 
21:     public function receive(array $data, int $userId, string $key): ProductionReceipt
22:     {
23:         app(BranchAccess::class)->assertBranch($userId, (int) $data['branch_id']);
24:         $hash = IdempotencyFingerprint::hash($data);
25:         $existing = ProductionReceipt::where('created_by', $userId)->where('idempotency_key', $key)->first();
26:         if ($existing) {
27:             return $this->replay($existing, $hash);
28:         }
29: 
30:         try {
