 2: export interface ApiError {
 3:   status: number;                       // 0 = مشكلة شبكة
 4:   message: string;
 5:   fields: Record<string, string[]>;     // كل المفاتيح ما عدا 'status'
 6:   summary: string[];                    // errors.status (أسباب رفض النشر)
 7: }
 8: 
 9: interface RawErrorBody {
10:   message?: unknown;
11:   errors?: Record<string, unknown>;
12: }
13: 
14: function toStringList(v: unknown): string[] {
15:   if (Array.isArray(v)) return v.map(x => String(x));
16:   return [String(v)];
17: }
18: 
19: export function normalizeError(e: unknown): ApiError {
20:   const err = e as { response?: { status?: unknown; data?: unknown }; message?: unknown } | null | undefined;
21:   const status = typeof err?.response?.status === 'number' ? err.response.status : 0;
22:   const data = (err?.response?.data ?? {}) as RawErrorBody;
23:   const raw: Record<string, unknown> = data.errors && typeof data.errors === 'object' ? data.errors : {};
24: 
25:   const fields: Record<string, string[]> = {};
26:   Object.entries(raw).forEach(([k, v]) => {
27:     if (k === 'status') return;
28:     fields[k] = toStringList(v);
29:   });
30: 
31:   const summary = raw.status === undefined ? [] : toStringList(raw.status);
32:   const message = typeof data.message === 'string' && data.message !== ''
33:     ? data.message
34:     : e instanceof Error && !err?.response && !('request' in e)
35:       ? e.message
36:       : status === 0
37:       ? 'تعذّر الاتصال بالخادم، تأكد من الإنترنت وحاول تاني'
38:       : 'حدث خطأ غير متوقع، حاول تاني';
39: 
40:   return { status, message, fields, summary };
