140: export function productFromApi(
141:   product: AdminProduct,
142:   media: AdminMedia[] = [],
143:   opts: { canViewCost: boolean },
144: ): UiProductState {
145:   const apiVariants = (product.variants ?? []) as ApiVariantLike[];
146:   const sorted = [...apiVariants].sort((a, b) => a.sort_order - b.sort_order);
147: 
148:   const rows: UiVariantRow[] = sorted.map((v, i) => {
149:     const colorEn = v.color_name_en ?? v.color?.name_en ?? null;
150:     const colorAr = v.color_name_ar ?? v.color?.name_ar ?? null;
151:     const colorHex = v.color_hex ?? v.color?.hex ?? null;
152:     return {
153:       _id: `srv-${v.id}`,
154:       serverId: v.id,
155:       color: colorEn || colorAr || colorHex
156:         ? { ar: colorAr ?? '', en: colorEn ?? '', hex: colorHex ?? '' }
157:         : null,
158:       size: v.size ?? '', capacity: v.capacity ?? '',
159:       sku: v.sku ?? '', barcode: v.barcode ?? '',
160:       retail: str(v.retail_price), wholesale: str(v.wholesale_price),
161:       cost: opts.canViewCost ? str(v.cost_price ?? '') : '',
162:       compare: str(v.compare_at_price),
163:       weight: str(v.weight_kg), reorder: v.reorder_level === null || v.reorder_level === undefined ? '' : String(v.reorder_level),
164:       order: v.sort_order ?? i,
165:       status: v.is_active ? 'active' : 'inactive',
166:     };
167:   });
168: 
169:   // mode عند التحميل: متغير واحد من غير لون ولا مقاس ولا سعة = single
170:   const single = rows.length === 1 && rows[0].color === null && rows[0].size === '' && rows[0].capacity === '';
171:   const mode: 'single' | 'matrix' = single ? 'single' : 'matrix';
172: 
173:   // axes من القيم الفريدة: الألوان unique بـ color_name_en من غير حساسية حروف
174:   const seenColors = new Set<string>();
175:   const colors: UiColor[] = [];
176:   const sizes: string[] = [];
177:   const capacities: string[] = [];
178:   rows.forEach(r => {
179:     if (r.color && r.color.en.trim() !== '') {
180:       const k = r.color.en.trim().toLowerCase();
181:       if (!seenColors.has(k)) { seenColors.add(k); colors.push(r.color); }
182:     }
183:     if (r.size.trim() !== '' && !sizes.some(s => s.trim().toLowerCase() === r.size.trim().toLowerCase())) sizes.push(r.size);
184:     if (r.capacity.trim() !== '' && !capacities.some(c => c.trim().toLowerCase() === r.capacity.trim().toLowerCase())) capacities.push(r.capacity);
185:   });
186: 
187:   const byId = new Map(sorted.map(v => [v.id, v] as const));
188:   const general: UiMediaItem[] = media
189:     .filter(m => m.collection === 'images' && (m.variant_id === null || m.variant_id === undefined))
190:     .sort((a, b) => a.order - b.order)
191:     .map(m => ({
192:       id: `srv-${m.id}`, serverId: m.id,
193:       name: m.url.split('/').pop()?.split('?')[0] || `image-${m.id}`,
194:       status: 'done' as const, url: m.thumb_url || m.url,
195:     }));
196: 
197:   const byVariant: Record<string, UiMediaItem[]> = {};
198:   media
199:     .filter(m => m.collection === 'images' && m.variant_id !== null && m.variant_id !== undefined)
200:     .sort((a, b) => a.order - b.order)
201:     .forEach(m => {
202:       const v = byId.get(m.variant_id as number);
203:       const colorEn = v ? (v.color_name_en ?? v.color?.name_en ?? '') : '';
204:       if (!colorEn) return;
205:       (byVariant[colorEn] = byVariant[colorEn] || []).push({
206:         id: `srv-${m.id}`, serverId: m.id, variantId: m.variant_id ?? undefined,
207:         name: m.url.split('/').pop()?.split('?')[0] || `image-${m.id}`,
208:         status: 'done' as const, url: m.thumb_url || m.url,
209:       });
210:     });
211: 
212:   const videoSrc = media.find(m => m.collection === 'video') ?? null;
213:   const d = product.dimensions ?? { length_cm: null, width_cm: null, height_cm: null };
214: 
215:   return {
216:     status: product.status, code: product.code,
217:     basic: {
218:       ar: product.name_ar, en: product.name_en,
219:       category: product.category?.id ?? null,
220:       brand: product.brand?.id ?? null,
221:       channel: product.sales_channel,
222:       slug: product.slug,
223:       desc_ar: product.description_ar ?? '', desc_en: product.description_en ?? '',
224:       mat_ar: product.material_ar ?? '', mat_en: product.material_en ?? '',
225:       l: str(d.length_cm), w: str(d.width_cm), h: str(d.height_cm),
226:       kg: str(product.weight_kg),
227:       warranty: product.warranty_months === null || product.warranty_months === undefined ? '' : String(product.warranty_months),
228:       warranty_details: product.warranty_details ?? '',
229:       origin: product.country_of_origin ?? '',
230:       featured: product.is_featured,
231:       supplier: product.supplier_id,
232:     },
233:     mode,
234:     axes: { colors, sizes, capacities },
235:     rows,
236:     media: {
237:       general, byVariant,
238:       video: videoSrc ? {
239:         id: `srv-${videoSrc.id}`, serverId: videoSrc.id,
240:         name: videoSrc.url.split('/').pop()?.split('?')[0] || `video-${videoSrc.id}`,
241:         status: 'done' as const, url: videoSrc.url,
242:       } : null,
243:     },
244:   };
245: }
