268: export function variantToPayload(
269:   row: UiVariantRow & { sort?: number },
270:   opts: { canViewCost: boolean; isCreate: boolean },
271: ): VariantPayload {
272:   const p: VariantPayload = {};
273: 
274:   // sku: فاضي في الإنشاء = ماتبعتوش (السيرفر يولّده). وفي التعديل ماتبعتش فاضي أبدًا.
275:   if (row.sku.trim() !== '') p.sku = row.sku;
276:   if (row.barcode.trim() !== '') p.barcode = row.barcode;
277: 
278:   if (row.color) {
279:     if (row.color.ar.trim() !== '') p.color_name_ar = row.color.ar;
280:     else if (!opts.isCreate) p.color_name_ar = null;
281:     if (row.color.en.trim() !== '') p.color_name_en = row.color.en;
282:     else if (!opts.isCreate) p.color_name_en = null;
283:     if (row.color.hex.trim() !== '') p.color_hex = row.color.hex;
284:     else if (!opts.isCreate) p.color_hex = null;
285:   } else if (!opts.isCreate) {
286:     p.color_name_ar = null; p.color_name_en = null; p.color_hex = null;
287:   }
288: 
289:   p.size = nullIfEmpty(row.size);
290:   p.capacity = nullIfEmpty(row.capacity);
291: 
292:   // التكلفة: لو معندوش الصلاحية ماتحطش cost_price خالص (الـ backend بيشيله أصلًا بس ماتعتمدش على ده)
293:   if (opts.canViewCost) p.cost_price = nullIfEmpty(row.cost);
294: 
295:   p.retail_price = nullIfEmpty(row.retail);
296:   p.wholesale_price = nullIfEmpty(row.wholesale);
297:   p.compare_at_price = nullIfEmpty(row.compare);
298: 
299:   p.reorder_level = row.reorder.trim() === '' ? null : parseInt(row.reorder, 10);
300:   p.weight_kg = nullIfEmpty(row.weight);
301:   p.sort_order = typeof row.sort === 'number' ? row.sort : row.order;
302:   p.is_active = row.status === 'active';
303:   return p;
304: }
