 440: */
 441: 
 442: input::placeholder,
 443: textarea::placeholder {
 444:   opacity: 1; /* 1 */
 445:   color: #9ca3af; /* 2 */
 446: }
 447: 
 448: /*
 449: Set the default cursor for buttons.
 450: */
 451: 
 452: button,
 453: [role="button"] {
 454:   cursor: pointer;
 455: }
 456: 
 457: /*
 458: Make sure disabled buttons don't get the pointer cursor.
 459: */
 460: :disabled {
 461:   cursor: default;
 462: }
 463: 
 464: /*
 465: 1. Make replaced elements \`display: block\` by default. (https://github.com/mozdevs/cssremedy/issues/14)
 466: 2. Add \`vertical-align: middle\` to align replaced elements more sensibly by default. (https://github.com/jensimmons/cssremedy/issues/14#issuecomment-634934210)
 467:    This can trigger a poorly considered lint error in some tools but is included by design.
 468: */
 469: 
 470: img,
 471: svg,
 472: video,
 473: canvas,
 474: audio,
 475: iframe,
 476: embed,
 477: object {
 478:   display: block; /* 1 */
 479:   vertical-align: middle; /* 2 */
 480: }
 481: 
 482: /*
 483: Constrain images and videos to the parent width and preserve their intrinsic aspect ratio. (https://github.com/mozdevs/cssremedy/issues/14)
 484: */
 485: 
 486: img,
 487: video {
 488:   max-width: 100%;
 489:   height: auto;
 490: }
 491: 
 492: /* Make elements with the HTML hidden attribute stay hidden by default */
 493: [hidden]:where(:not([hidden="until-found"])) {
 494:   display: none;
 495: }
