 572: 
 573:     :host {
 574:       margin: 0;
 575:       padding: 0;
 576:       font-family: 'Inter', 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, sans-serif;
 577:       background-color: var(--bg-canvas);
 578:       color: var(--text-primary);
 579:       overflow-x: hidden;
 580:     }
 581: 
 582:     h1, h2, h3, .font-display {
 583:       font-family: 'Plus Jakarta Sans', 'Inter', sans-serif;
 584:     }
 585: 
 586:     /* Live Theme Viewport & Underlay Snapshot for 100% True Circular Reveal */
 587:     #app-viewport {
 588:       position: relative;
 589:       z-index: 10;
 590:       background-color: var(--bg-canvas);
 591:       color: var(--text-primary);
 592:       min-height: 100vh;
 593:       will-change: clip-path;
 594:     }
 595: 
 596:     #theme-wipe-overlay {
 597:       position: fixed;
 598:       inset: 0;
 599:       z-index: 1;
 600:       pointer-events: none;
 601:       overflow: hidden;
 602:     }
 603: 
 604:     #theme-wipe-overlay *,
 605:     #theme-wipe-overlay {
 606:       animation: none !important;
 607:       transition: none !important;
 608:     }
 609: 
 610:     .no-theme-transitions,
 611:     .no-theme-transitions * {
 612:       transition: none !important;
 613:     }
 614: 
 615:     /* Surface classes */
 616:     .v-card {
 617:       background-color: var(--bg-card);
 618:       border-radius: 22px;
 619:       border: 1px solid var(--border-subtle);
 620:     }
 621: 
 622:     .v-subcard {
 623:       background-color: var(--bg-subcard);
 624:       border-radius: 16px;
 625:     }
 626: 
 627:     .v-pill-surface {
 628:       background-color: var(--bg-card);
 629:       border: 1px solid var(--border-subtle);
 630:     }
 631: 
 632:     .v-badge-green {
 633:       background-color: var(--badge-green-bg);
 634:       color: var(--badge-green-text);
 635:     }
 636: 
 637:     .v-badge-red {
 638:       background-color: var(--badge-red-bg);
 639:       color: var(--badge-red-text);
 640:     }
 641: 
 642:     .v-icon-well {
 643:       background-color: var(--icon-well-bg);
 644:       color: var(--text-secondary);
 645:     }
 646: 
 647:     .v-divide > :not([hidden]) ~ :not([hidden]) {
 648:       border-top: 1px solid var(--divider-color);
 649:     }
 650: 
 651:     .v-border-b {
 652:       border-bottom: 1px solid var(--divider-color);
 653:     }
 654: 
 655:     .v-border-r {
 656:       border-right: 1px solid var(--divider-color);
 657:     }
 658: 
 659:     /* Orange Gradient Hero Cards (Total Earnings & Rewards Card) */
 660:     .v-orange-card {
 661:       background: radial-gradient(circle at 78% 42%, #f48668 0%, #e7582f 48%, #dc4318 100%);
 662:       color: #ffffff;
 663:     }
 664: 
 665:     .v-orange-earnings {
 666:       background: radial-gradient(circle at 22% 18%, #f4886b 0%, #e6542b 55%, #db4218 100%);
 667:       color: #ffffff;
 668:     }
 669: 
 670:     /* Profit Hatched Orange Bar */
 671:     .bar-profit-hatched {
 672:       background: repeating-linear-gradient(
 673:         -45deg,
 674:         #e0491f 0px,
 675:         #e0491f 2.5px,
 676:         #f37c59 2.5px,
 677:         #f37c59 5px
 678:       );
 679:     }
 680: 
 681:     /* White Hatched Progress Bar on Rewards Card */
 682:     .rewards-hatched-track {
 683:       background: repeating-linear-gradient(
 684:         -60deg,
 685:         rgba(255, 255, 255, 0.45) 0px,
 686:         rgba(255, 255, 255, 0.45) 1.5px,
 687:         transparent 1.5px,
 688:         transparent 5.5px
 689:       );
 690:     }
 691: 
 692:     /* Grey Hatched Progress Bar on Spending Limit */
 693:     .spending-hatched-track {
 694:       background: var(--hatched-track);
 695:     }
 696: 
 697:     /* Staggered Blur-In Animation matching video transitions */
 698:     @keyframes blurFadeIn {
 699:       0% {
 700:         opacity: 0;
 701:         filter: blur(10px);
 702:         transform: translateY(8px);
 703:       }
 704:       100% {
 705:         opacity: 1;
 706:         filter: blur(0px);
 707:         transform: translateY(0px);
 708:       }
 709:     }
 710: 
 711:     .stagger-item {
 712:       animation: blurFadeIn 0.48s cubic-bezier(0.22, 1, 0.36, 1) both;
 713:     }
 714:     .stagger-1 { animation-delay: 0.03s; }
 715:     .stagger-2 { animation-delay: 0.09s; }
 716:     .stagger-3 { animation-delay: 0.15s; }
 717:     .stagger-4 { animation-delay: 0.21s; }
 718:     .stagger-5 { animation-delay: 0.27s; }
 719: 
 720:     /* 3D Credit Card Flip */
 721:     .card-3d-perspective {
 722:       perspective: 1100px;
 723:     }
 724:     .card-3d-inner {
 725:       position: relative;
 726:       width: 100%;
 727:       height: 100%;
 728:       transform-style: preserve-3d;
 729:       transition: transform 0.65s cubic-bezier(0.34, 1.56, 0.64, 1);
 730:     }
 731:     .card-3d-inner.is-flipped {
 732:       transform: rotateY(180deg);
 733:     }
 734:     .card-3d-face {
 735:       position: absolute;
 736:       inset: 0;
 737:       backface-visibility: hidden;
 738:       -webkit-backface-visibility: hidden;
 739:       border-radius: 18px;
 740:       overflow: hidden;
 741:     }
 742:     .card-3d-back {
 743:       transform: rotateY(180deg);
 744:     }
 745: 
 746:     /* Custom Range Slider for Manage Card Controls */
 747:     input[type="range"].v-slider {
 748:       -webkit-appearance: none;
 749:       appearance: none;
 750:       width: 100%;
 751:       height: 5px;
 752:       border-radius: 999px;
 753:       outline: none;
 754:       cursor: pointer;
 755:     }
 756:     input[type="range"].v-slider::-webkit-slider-thumb {
 757:       -webkit-appearance: none;
 758:       appearance: none;
 759:       width: 18px;
 760:       height: 18px;
 761:       border-radius: 50%;
 762:       background: #ffffff;
 763:       border: 3.5px solid #e0491f;
 764:       box-shadow: 0 2px 6px rgba(224, 73, 31, 0.35);
 765:       cursor: grab;
 766:       transition: transform 0.15s ease;
 767:     }
 768:     input[type="range"].v-slider::-webkit-slider-thumb:active {
 769:       cursor: grabbing;
 770:       transform: scale(1.12);
 771:     }
 772: 
 773:     /* Custom Scrollbar */
 774:     ::-webkit-scrollbar {
 775:       width: 5px;
 776:       height: 5px;
 777:     }
 778:     ::-webkit-scrollbar-track {
 779:       background: transparent;
 780:     }
 781:     ::-webkit-scrollbar-thumb {
 782:       background: rgba(150, 145, 160, 0.25);
 783:       border-radius: 999px;
 784:     }
