  7: use App\Enums\StockMovementType;
  8: use App\Http\Controllers\Controller;
  9: use App\Http\Requests\Admin\Inventory\StoreAdjustmentRequest;
 10: use App\Http\Resources\Admin\StockLevelResource;
 11: use App\Http\Resources\Admin\StockMovementResource;
 12: use App\Models\StockLevel;
 13: use App\Models\StockMovement;
 14: use App\Services\BranchAccess;
 15: use App\Services\InventoryService;
 16: use Carbon\Carbon;
 17: use Illuminate\Database\Eloquent\Collection as EloquentCollection;
 18: use Illuminate\Http\JsonResponse;
 19: use Illuminate\Http\Request;
 20: use Illuminate\Http\Resources\Json\AnonymousResourceCollection;
 21: use Illuminate\Routing\Controllers\HasMiddleware;
 22: use Illuminate\Routing\Controllers\Middleware;
 23: use Illuminate\Validation\Rule;
 24: 
 25: class InventoryController extends Controller implements HasMiddleware
 26: {
 27:     public function __construct(private readonly InventoryService $inventory) {}
 28: 
 29:     public static function middleware(): array
 30:     {
 31:         return [
 32:             new Middleware('can:inventory.view', only: ['index', 'movements']),
 33:             new Middleware('can:inventory.adjust', only: ['adjustments']),
 34:         ];
 35:     }
 36: 
 37:     /** قائمة أرصدة المخزون الحالية مع الفلاتر والمتاح المحسوب. */
 38:     public function index(Request $request): AnonymousResourceCollection
 39:     {
 40:         $filters = $request->validate([
 41:             'branch_id' => ['nullable', 'integer', 'min:1'],
 42:             'location_id' => ['nullable', 'integer', 'min:1'],
 43:             'product_id' => ['nullable', 'integer', 'min:1'],
 44:             'product_variant_id' => ['nullable', 'integer', 'min:1'],
 45:             'low_stock' => ['nullable', 'boolean'],
 46:             'per_page' => ['nullable', 'integer', 'min:1', 'max:100'],
 47:         ]);
 48: 
 49:         $levels = StockLevel::query()
 50:             ->when(app(BranchAccess::class)->restrictedBranch($request->user()), fn ($q, $branch) => $q->where('branch_id', $branch))
 51:             ->with(['variant.product', 'branch', 'location'])
 52:             ->when($filters['branch_id'] ?? null, fn ($q, $v) => $q->where('branch_id', $v))
 53:             ->when($filters['location_id'] ?? null, fn ($q, $v) => $q->where('location_id', $v))
 54:             ->when($filters['product_variant_id'] ?? null, fn ($q, $v) => $q->where('product_variant_id', $v))
 55:             ->when($filters['product_id'] ?? null, fn ($q, $v) => $q->whereHas('variant', fn ($vq) => $vq->where('product_id', $v)))
 56:             // حد إعادة الطلب الفعّال: مستوى الصف إن ضُبط (> 0)، وإلا مستوى المتغير نفسه
 57:             ->when($filters['low_stock'] ?? null, fn ($q) => $q
 58:                 ->join('product_variants', 'product_variants.id', '=', 'stock_levels.product_variant_id')
 59:                 ->whereRaw('stock_levels.available <= COALESCE(NULLIF(stock_levels.reorder_level, 0), product_variants.reorder_level, 0)')
 60:                 // صف بلا حد إعادة طلب فعّال ليس "منخفضًا": صفوف صفرية ينشئها
 61:                 // lockLevels كأثر جانبي كانت تملأ الفلتر وهميًا (L-4).
 62:                 ->whereRaw('COALESCE(NULLIF(stock_levels.reorder_level, 0), product_variants.reorder_level, 0) > 0')
 63:                 ->select('stock_levels.*'))
 64:             ->orderBy('branch_id')
 65:             ->orderBy('product_variant_id')
 66:             ->orderBy('id')
 67:             ->paginate($filters['per_page'] ?? 15);
 68: 
 69:         return StockLevelResource::collection($levels);
 70:     }
 71: 
 72:     /** سجل حركات دفتر الأستاذ من الأحدث للأقدم مع الفلاتر. */
 73:     public function movements(Request $request): AnonymousResourceCollection
 74:     {
 75:         $filters = $request->validate([
 76:             'branch_id' => ['nullable', 'integer', 'min:1'],
 77:             'location_id' => ['nullable', 'integer', 'min:1'],
 78:             'product_id' => ['nullable', 'integer', 'min:1'],
 79:             'product_variant_id' => ['nullable', 'integer', 'min:1'],
 80:             'type' => ['nullable', Rule::in(array_column(StockMovementType::cases(), 'value'))],
 81:             'from_date' => ['nullable', 'date_format:Y-m-d'],
 82:             'to_date' => ['nullable', 'date_format:Y-m-d', Rule::when($request->filled('from_date'), 'after_or_equal:from_date')],
 83:             'per_page' => ['nullable', 'integer', 'min:1', 'max:100'],
 84:         ]);
 85: 
 86:         $movements = StockMovement::query()
 87:             ->when(app(BranchAccess::class)->restrictedBranch($request->user()), fn ($q, $branch) => $q->where('branch_id', $branch))
 88:             ->with(['variant', 'branch', 'location', 'creator'])
 89:             ->when($filters['branch_id'] ?? null, fn ($q, $v) => $q->where('branch_id', $v))
 90:             ->when($filters['location_id'] ?? null, fn ($q, $v) => $q->where('location_id', $v))
 91:             ->when($filters['product_variant_id'] ?? null, fn ($q, $v) => $q->where('product_variant_id', $v))
 92:             ->when($filters['product_id'] ?? null, fn ($q, $v) => $q->whereHas('variant', fn ($vq) => $vq->where('product_id', $v)))
 93:             ->when($filters['type'] ?? null, fn ($q, $v) => $q->where('type', $v))
 94:             // حدود الأيام بأيام العمل (business_timezone) لا UTC، والتخزين يظل UTC
 95:             ->when($filters['from_date'] ?? null, fn ($q, $v) => $q->where('created_at', '>=', Carbon::parse($v, config('app.business_timezone'))->startOfDay()->utc()))
 96:             ->when($filters['to_date'] ?? null, fn ($q, $v) => $q->where('created_at', '<', Carbon::parse($v, config('app.business_timezone'))->addDay()->startOfDay()->utc()))
 97:             ->orderByDesc('id')
 98:             // الدفتر append-only وسيكبر لملايين الصفوف: بلا COUNT(*) وبلا OFFSET —
 99:             // ترقيم بالمؤشر على (branch_id, id DESC) يجعل الصفحات العميقة بنفس
100:             // تكلفة الأولى (M-7). المقايضة: لا قفز لرقم صفحة محدد.
101:             ->cursorPaginate($filters['per_page'] ?? 15);
102: 
103:         return StockMovementResource::collection($movements);
104:     }
105: 
106:     /** تسوية يدوية: كل العناصر في transaction واحدة عبر InventoryService فقط. */
107:     public function adjustments(StoreAdjustmentRequest $request): JsonResponse
108:     {
109:         $movements = $this->inventory->applyAdjustments($request->validated(), $request->user()->id, $this->idempotencyKey($request));
110: 
111:         return response()->json([
112:             'message' => 'تم تنفيذ التسوية بنجاح',
113:             'data' => StockMovementResource::collection((new EloquentCollection($movements))->load(['variant', 'branch', 'location'])),
114:         ], 201);
115:     }
116: }  1: <?php
