 16: class ProductService
 17: {
 18:     public function __construct(private ProductPublishabilityChecker $publishability) {}
 19: 
 20:     public function create(array $data, User $user): Product
 21:     {
 22:         return DB::transaction(function () use ($data, $user) {
 23:             CatalogLock::tree(shared: true);
 24:             $data['brand_id'] = null;
 25:             $data['supplier_id'] = null;
 26:             $variants = $data['variants'] ?? [];
 27:             unset($data['variants']);
 28:             $data = array_filter($data, fn ($value) => $value !== null);
 29: 
 30:             if (($data['status'] ?? 'draft') !== ProductStatus::Draft->value) {
 31:                 throw new BusinessException('يجب إنشاء المنتج كمسودة ثم رفع صوره ونشره', ['status' => ['الحالة المسموحة عند الإنشاء هي draft']]);
 32:             }
 33: 
 34:             $data['slug'] = $data['slug'] ?? SlugService::make(Product::class, $data['name_en']);
 35:             $data['created_by'] = $user->id;
 36:             $data['status'] = ProductStatus::Draft->value; // دايمًا يتعمل draft الأول
 37: 
 38:             // قفل القسم يمنع حذفه أثناء إنشاء المنتج
 39:             $this->lockReference(Category::class, (int) $data['category_id'], 'category_id');
 40: 
 41:             $product = Product::create($data);
 42:             $product->update(['code' => 'P'.str_pad((string) $product->id, 5, '0', STR_PAD_LEFT)]);
 43: 
 44:             foreach ($variants as $v) {
 45:                 app(VariantService::class)->create($product, $v);
 46:             }
 47: 
 48:             return $product->fresh(['category.media', 'variants.media', 'media']);
 49:         });
 50:     }
 51: 
 52:     public function update(Product $product, array $data, User $user): Product
 53:     {
 54:         return DB::transaction(function () use ($product, $data, $user) {
 55:             CatalogLock::tree(shared: true);
 56:             // قفل صف المنتج طول التعديل عشان فحص النشر ميعديش مع تعديل متزامن
 57:             $product = Product::whereKey($product->id)->lockForUpdate()->firstOrFail();
 58: 
 59:             unset($data['brand_id'], $data['supplier_id']);
 60:             $newStatus = isset($data['status']) ? ProductStatus::from($data['status']) : null;
 61:             unset($data['status']);
 62: 
 63:             if (array_key_exists('slug', $data) && empty($data['slug'])) {
 64:                 $data['slug'] = SlugService::make(Product::class, $data['name_en'] ?? $product->name_en, $product->id);
 65:             }
 66:             $this->lockReference(Category::class, (int) ($data['category_id'] ?? $product->category_id), 'category_id');
 67: 
 68:             if (array_key_exists('is_featured', $data) && $data['is_featured'] === null) {
 69:                 unset($data['is_featured']);
 70:             }
 71: 
 72:             $product->update($data);
 73: 
 74:             if ($newStatus && $newStatus !== $product->status) {
 75:                 $this->changeStatus($product, $newStatus, $user);
 76:             } elseif ($product->status === ProductStatus::Published) {
 77:                 // تعديل من غير تغيير حالة على منتج منشور: القواعد بتتفحص من جديد
 78:                 $this->assertPublishable($product);
 79:             }
 80: 
 81:             return $product->fresh(['category.media', 'variants.media', 'media']);
 82:         });
 83:     }
 84: 
 85:     public function changeStatus(Product $product, ProductStatus $status, User $user): void
 86:     {
 87:         DB::transaction(function () use ($product, $status, $user): void {
 88:             CatalogLock::tree(shared: true);
 89:             // قفل صف المنتج وقسمه قبل الفحص والنشر، عشان مفيش تعديل متزامن يعدي بين الفحص والحفظ
 90:             $product = Product::whereKey($product->id)->lockForUpdate()->firstOrFail();
 91:             if ($product->category_id) {
 92:                 $this->lockReference(Category::class, (int) $product->category_id, 'category_id');
 93:             }
 94:             $product->refresh();
 95: 
 96:             if ($product->status !== $status && ($product->status === ProductStatus::Published || $status === ProductStatus::Published) && ! $user->can('products.publish')) {
 97:                 throw new BusinessException('ليس لديك صلاحية تغيير نشر المنتجات', [], 403);
 98:             }
 99: 
100:             if ($status === ProductStatus::Published) {
101:                 $this->assertPublishable($product);
102:                 $product->published_at ??= now();
103:             }
104:             $product->status = $status;
105:             $product->save();
106:         });
107:         $product->refresh();
108:     }
109: 
110:     public function assertPublishable(Product $product): void
111:     {
112:         $this->publishability->assertPublishable($product);
113:     }
114: 
115:     private function lockReference(string $model, int $id, string $field): void
116:     {
117:         if (! $model::whereKey($id)->sharedLock()->first()) {
118:             throw new BusinessException('أحد المراجع المطلوبة لم يعد متاحًا', [$field => ['القيمة المحددة غير موجودة أو محذوفة']]);
119:         }
120:     }
121: 
122:     public function delete(Product $product): void
123:     {
124:         DB::transaction(function () use ($product): void {
125:             $product = Product::whereKey($product->id)->lockForUpdate()->firstOrFail();
126:             // حذف المنتج يحذف متغيراته ناعمًا: أي رصيد على أي منها يُحبس (M-9)
127:             if (StockLevel::query()->whereIn('product_variant_id', $product->variants()->pluck('id'))
128:                 ->where(fn ($q) => $q->where('on_hand', '<>', 0)->orWhere('reserved', '<>', 0)
129:                     ->orWhere('damaged', '<>', 0)->orWhere('in_transit', '<>', 0))
130:                 ->exists()) {
131:                 throw new BusinessException('لا يمكن حذف منتج له متغيرات برصيد مخزون؛ صفِّ الأرصدة أولًا.');
132:             }
133:             $product->variants()->delete();  // soft
134:             $product->delete();              // soft
135:         });
136:         // TODO مرحلة الطلبات: منع الحذف لو المنتج عليه طلبات، وبدل كده يتعمل archived
137:     }
138: } 1: <?php
