 24: /**
 25:  * إدارة قوائم الأسعار وعناصرها واستيراد/تصدير CSV.
 26:  * منطق حساب السعر نفسه في PricingService.
 27:  */
 28: class PriceListService
 29: {
 30:     public function paginate(array $filters, ?User $user = null): LengthAwarePaginator
 31:     {
 32:         return PriceList::query()
 33:             ->with(['customer', 'customerGroup', 'branch'])
 34:             ->withCount('items')
 35:             ->when($this->restrictedBranch($user) !== null, fn ($q) => $q->where('branch_id', $this->restrictedBranch($user)))
 36:             ->when($filters['type'] ?? null, fn ($q, $v) => $q->where('type', $v))
 37:             ->when($filters['customer_id'] ?? null, fn ($q, $v) => $q->where('customer_id', $v))
 38:             ->when($filters['customer_group_id'] ?? null, fn ($q, $v) => $q->where('customer_group_id', $v))
 39:             ->when($filters['branch_id'] ?? null, fn ($q, $v) => $q->where('branch_id', $v))
 40:             ->when(array_key_exists('is_active', $filters) && $filters['is_active'] !== null, fn ($q) => $q->where('is_active', $filters['is_active']))
 41:             ->when($filters['search'] ?? null, fn ($q, $v) => $q->whereLike('name', '%'.SearchTerm::escape($v).'%', caseSensitive: false))
 42:             ->orderByDesc('priority')
 43:             ->orderByDesc('id')
 44:             ->paginate($filters['per_page'] ?? 15);
 45:     }
 46: 
 47:     public function find(int $id, ?User $user = null): PriceList
 48:     {
 49:         return PriceList::query()
 50:             ->with(['customer', 'customerGroup', 'branch'])
 51:             ->withCount('items')
 52:             ->when($this->restrictedBranch($user) !== null, fn ($q) => $q->where('branch_id', $this->restrictedBranch($user)))
 53:             ->findOrFail($id);
 54:     }
 55: 
 56:     public function create(array $data, ?User $user = null): PriceList
 57:     {
 58:         $restricted = $this->restrictedBranch($user);
 59:         if ($restricted !== null) {
 60:             if (isset($data['branch_id']) && (int) $data['branch_id'] !== $restricted) {
 61:                 throw new AuthorizationException('لا تملك صلاحية إنشاء قوائم أسعار لفرع آخر.');
 62:             }
 63:             $data['branch_id'] = $restricted;
 64:         }
 65:         $data = $this->normalizeDates($data);
 66:         $data = array_filter($data, fn ($value, $key) => $value !== null || ! in_array($key, ['currency', 'priority', 'is_active'], true), ARRAY_FILTER_USE_BOTH);
 67:         $this->validateDates($data);
 68:         $data = $this->withValidOwner($data);
 69: 
 70:         return PriceList::query()->create($data)->load(['customer', 'customerGroup', 'branch']);
 71:     }
 72: 
 73:     public function update(PriceList $priceList, array $data, ?User $user = null): PriceList
 74:     {
 75:         $this->assertListAccess($user, $priceList);
 76:         $restricted = $this->restrictedBranch($user);
 77:         // array_key_exists لا isset: إرسال branch_id = null كان يتخطى الفحص كله
 78:         // ويحوّل قائمة الفرع إلى قائمة عامة لكل الفروع (C-1).
 79:         if ($restricted !== null && array_key_exists('branch_id', $data)
 80:             && ($data['branch_id'] === null || (int) $data['branch_id'] !== $restricted)) {
 81:             throw new AuthorizationException('لا تملك صلاحية نقل قائمة أسعار إلى فرع آخر.');
 82:         }
 83:         $data = $this->normalizeDates($data);
 84: 
 85:         return DB::transaction(function () use ($priceList, $data, $user): PriceList {
 86:             $priceList = PriceList::query()->lockForUpdate()->findOrFail($priceList->id);
 87:             // إعادة الفحص على الصف المقفول: القائمة قد تكون انتقلت لفرع آخر بين
 88:             // فحص الـ route binding والقفل (L-1).
 89:             $this->assertListAccess($user, $priceList);
 90:             $this->validateDates($data, $priceList);
 91:             $data = $this->withValidOwner($data, $priceList);
 92:             $priceList->update($data);
 93: 
 94:             return $priceList->load(['customer', 'customerGroup', 'branch']);
 95:         });
 96:     }
