127:     public function delete(PriceList $priceList, ?User $user = null): void
128:     {
129:         $this->assertListAccess($user, $priceList);
130: 
131:         DB::transaction(function () use ($priceList, $user): void {
132:             $locked = PriceList::query()->lockForUpdate()->findOrFail($priceList->id);
133:             $this->assertListAccess($user, $locked); // إعادة فحص بعد القفل (L-1)
134:             $locked->delete(); // العناصر بتتحذف بـ cascade في القاعدة
135:         });
136:     }
