172:         $data = $this->normalizeDates($data);
173: 
174:         return DB::transaction(function () use ($item, $data, $user): PriceListItem {
175:             $lockedList = PriceList::query()->lockForUpdate()->findOrFail($item->price_list_id);
176:             $this->assertListAccess($user, $lockedList); // إعادة فحص بعد القفل (L-1)
