266:     /**
267:      * تسجيل العناصر مع لقطة system_qty من الرصيد الحالي في نطاق الجلسة.
268:      *
269:      * @param  list<array{product_variant_id: int, counted_qty?: float|int|string|null}>  $items
270:      */
271:     private function syncItems(Stocktake $stocktake, array $items): void
272:     {
273:         $levels = $this->snapshotLevels($stocktake, $items);
274:         $snapshotMovementId = (int) StockMovement::query()->max('id');
275:         foreach ($items as $item) {
276:             $level = $levels->get($item['product_variant_id']);
277: 
278:             $stocktake->items()->create([
279:                 'product_variant_id' => $item['product_variant_id'],
280:                 'system_qty' => $level ? (float) $level->on_hand : 0,
281:                 'snapshot_movement_id' => $snapshotMovementId,
282:                 'counted_qty' => $item['counted_qty'] ?? null,
283:             ]);
284:         }
285:     }
