48: 
49:     public function registerMediaCollections(): void
50:     {
51:         $this->addMediaCollection('image')->singleFile()
52:             ->acceptsMimeTypes(['image/jpeg', 'image/png', 'image/webp']);
53:     }
54: 
55:     // بيرجّع IDs كل الأقسام اللي تحته على أي مستوى — مجموعة visited بتمنع اللف اللانهائي لو فيه دورة في البيانات
56:     public function descendantIds(): array
57:     {
58:         $ids = [];
59:         $seen = [$this->id => true];
60:         $queue = [$this->id];
61:         while ($queue) {
62:             $children = Category::whereIn('parent_id', $queue)->pluck('id')->all();
63:             $queue = [];
64:             foreach ($children as $childId) {
65:                 if (! isset($seen[$childId])) {
66:                     $seen[$childId] = true;
67:                     $ids[] = $childId;
68:                     $queue[] = $childId;
69:                 }
70:             }
71:         }
72: 
73:         return $ids;
74:     }
75: 
76:     public function depth(): int
77:     {
78:         $depth = 1;
79:         $seen = [$this->id => true];
80:         $p = $this->parent;
81:         while ($p) {
82:             if (isset($seen[$p->id])) {
83:                 throw new \RuntimeException('توجد دورة في شجرة الأقسام');
84:             }
85:             $seen[$p->id] = true;
86:             $depth++;
87:             $p = $p->parent;
88:         }
89: 
90:         return $depth;
91:     }
