328:     public function test_movement_sequence_is_monotonic_across_rollbacks_and_counter_changes(): void
329:     {
330:         $settings = app(SettingService::class);
331:         $before = $settings->get('movement_next_number');
332:         DB::beginTransaction();
333:         $first = $settings->generateNextNumber('movement');
334:         DB::rollBack();
335:         $second = $settings->generateNextNumber('movement');
336:         $this->assertNotSame($first, $second);
337:         $this->assertSame($before + 2, $settings->get('movement_next_number'));
338:         $settings->updateBatch(['movement_next_number' => $before]);
339:         $this->assertSame($before + 2, $settings->get('movement_next_number'));
