363:     public function test_stocktake_loads_snapshots_and_variant_costs_in_batches(): void
364:     {
365:         $branch = Branch::factory()->create();
366:         $variants = ProductVariant::factory()->count(12)->create();
367:         $items = $variants->map(fn ($variant) => ['product_variant_id' => $variant->id, 'counted_qty' => 1])->all();
368:         DB::enableQueryLog();
369:         try {
370:             $stocktake = app(StocktakeService::class)->create(['branch_id' => $branch->id, 'items' => $items], $this->staff->id);
371:             $snapshotQueries = array_filter(DB::getQueryLog(), fn ($query) => str_starts_with($query['query'], 'select') && str_contains($query['query'], 'from "stock_levels"'));
372:             $this->assertCount(1, $snapshotQueries);
373:             DB::flushQueryLog();
374:             app(StocktakeService::class)->approve($stocktake, $this->staff->id);
375:             $variantQueries = array_filter(DB::getQueryLog(), fn ($query) => str_contains($query['query'], 'from "product_variants"'));
376:             // Costs, active-input validation, and response variants are each loaded in a batch.
377:             $this->assertCount(3, $variantQueries);
378:         } finally {
379:             DB::disableQueryLog();
380:             DB::flushQueryLog();
381:         }
382:     }
