384:     public function test_movement_date_filter_includes_entire_end_day_and_excludes_next_midnight(): void
385:     {
386:         $branch = Branch::factory()->create();
387:         $variant = ProductVariant::factory()->create();
388:         try {
389:             // حدود الفلتر بأيام العمل (Africa/Cairo) والتخزين UTC: الحركة الثانية في
390:             // آخر ثانية من يوم القاهرة، والثالثة في أول ثانية من اليوم التالي (خارج النطاق).
391:             $this->travelTo(now()->setDate(2026, 10, 1)->startOfDay());
392:             $this->movement($variant, $branch, 1);
393:             $this->travelTo(Carbon::createFromFormat('Y-m-d H:i:s', '2026-10-02 23:59:59', 'Africa/Cairo')->utc());
394:             $this->movement($variant, $branch, 1);
395:             $this->travelTo(Carbon::createFromFormat('Y-m-d H:i:s', '2026-10-03 00:00:00', 'Africa/Cairo')->utc());
396:             $this->movement($variant, $branch, 1);
397:             $this->api('GET', 'inventory/movements?from_date=2026-10-02&to_date=2026-10-02')->assertOk()->assertJsonCount(1, 'data');
398:         } finally {
399:             $this->travelBack();
400:         }
401:     }
