403:     private function customer(?CustomerGroup $group = null): Customer
404:     {
405:         return Customer::create(['name' => 'Buyer', 'email' => uniqid().'@example.com', 'phone' => fake()->unique()->numerify('010########'),
406:             'company_name' => 'Company', 'tax_number' => '123', 'commercial_register' => '456',
407:             'password' => 'password', 'type' => CustomerType::Wholesale, 'status' => CustomerStatus::Approved,
408:             'customer_group_id' => $group?->id]);
409:     }
410: 
411:     private function staff(?Branch $branch = null): User
412:     {
413:         $staff = User::factory()->create(['branch_id' => $branch?->id]);
414:         // موظف مرتبط بفرع لا يأخذ امتياز كل الفروع، وإلا انكسر تقييد نطاقه.
415:         $permissions = Permission::where('guard_name', 'staff')
416:             ->when($branch !== null, fn ($query) => $query->where('name', '!=', 'inventory.all_branches'))
417:             ->get();
418:         $staff->givePermissionTo($permissions);
419: 
420:         return $staff;
421:     }
422: 
423:     private function movement(ProductVariant $variant, Branch $branch, float $qty): void
424:     {
