  8: function AnimatedNumber({ value, start, duration, trigger, format }) {
  9:   const [display, setDisplay] = useState(start);
 10:   useEffect(() => {
 11:     let frame;
 12:     const started = performance.now();
 13:     function tick(now) {
 14:       const progress = Math.min((now - started) / duration, 1);
 15:       setDisplay(start + (value - start) * (1 - Math.pow(1 - progress, 3)));
 16:       if (progress < 1) frame = requestAnimationFrame(tick);
 17:     }
 18:     frame = requestAnimationFrame(tick);
 19:     return () => cancelAnimationFrame(frame);
 20:   }, [value, start, duration, trigger]);
 21:   return <>{format(display)}</>;
 22: }
