128: export const categoriesApi = {
129:   tree: (signal?: AbortSignal) =>
130:     apiClient.get<{ data: AdminCategory[] }>(CAT, { params: { tree: 1 }, signal }).then((r) => r.data.data),
131:   show: (id: number) =>
132:     apiClient.get<{ data: AdminCategory }>(`${CAT}/${id}`).then((r) => r.data.data),
133:   create: (p: CategoryPayload, onProgress?: (pct: number) => void) =>
134:     apiClient.post<{ data: AdminCategory }>(CAT, categoryFormData(p), {
135:       ...MULTIPART,
136:       onUploadProgress: (e) => onProgress?.(Math.round((e.loaded / (e.total || 1)) * 100)),
137:     }).then((r) => r.data.data),
138:   update: (id: number, p: CategoryPayload, onProgress?: (pct: number) => void) =>
139:     apiClient.post<{ data: AdminCategory }>(`${CAT}/${id}`, categoryFormData(p, true), {
140:       ...MULTIPART,
141:       onUploadProgress: (e) => onProgress?.(Math.round((e.loaded / (e.total || 1)) * 100)),
142:     }).then((r) => r.data.data),
143:   remove: (id: number) =>
144:     apiClient.delete<{ message: string }>(`${CAT}/${id}`).then((r) => r.data),
145:   reorder: (items: CategoryReorderItem[]) =>
146:     apiClient.put<{ message: string }>(`${CAT}/reorder`, { items }).then((r) => r.data),
147: };
