165:   if (spoofPut) fd.append('_method', 'PUT');
166:   const put = (key: string, v: unknown) => {
167:     if (v === undefined) return;                       // مش هيتبعت
168:     if (v === null) return fd.append(key, '');         // Laravel يحوّلها null
169:     if (typeof v === 'boolean') return fd.append(key, v ? '1' : '0'); // مهم: مش "true"
170:     if (v instanceof Blob) return fd.append(key, v);
171:     fd.append(key, String(v));
172:   };
173:   put('name_ar', p.name_ar);
174:   put('name_en', p.name_en);
175:   put('slug', p.slug);
176:   put('description_ar', p.description_ar);
177:   put('description_en', p.description_en);
178:   put('sort_order', p.sort_order);
179:   put('is_active', p.is_active);
180:   if (p.logo) put('logo', p.logo);
181:   if (p.remove_logo) put('remove_logo', true);
