284:     private function nextMovementNumber(): int
285:     {
286:         $sequence = DB::selectOne('SELECT last_value, is_called FROM stock_movement_number_seq');
287: 
288:         return (int) $sequence->last_value + ($sequence->is_called ? 1 : 0);
289:     }
290: 
291:     private function nextDocumentNumber(string $type): int
292:     {
293:         if (! isset(self::SEQUENCE_TYPES[$type])) {
294:             throw new InvalidArgumentException("Unsupported numbering type [{$type}].");
295:         }
296:         $sequence = DB::selectOne("SELECT last_value, is_called FROM document_{$type}_number_seq");
297: 
298:         return (int) $sequence->last_value + ($sequence->is_called ? 1 : 0);
299:     }
