313:     private function castValue(?string $value, string $type): mixed
314:     {
315:         if ($value === null) {
316:             return null;
317:         }
318: 
319:         return match ($type) {
320:             'boolean' => filter_var($value, FILTER_VALIDATE_BOOLEAN),
321:             'integer' => (int) $value,
322:             'float' => (float) $value,
323:             'json' => json_decode($value, true, 512, JSON_THROW_ON_ERROR),
324:             default => $value,
325:         };
326:     }
327: 
328:     /** @throws JsonException */
329:     private function serializeValue(mixed $value, string $type): ?string
330:     {
331:         if ($value === null) {
332:             return null;
333:         }
334: 
335:         if ($type === 'json') {
336:             return json_encode($value, JSON_THROW_ON_ERROR);
337:         }
338: 
339:         if ($type === 'boolean') {
340:             return filter_var($value, FILTER_VALIDATE_BOOLEAN) ? '1' : '0';
341:         }
342: 
343:         return (string) $value;
344:     }
