24: function AuthenticatedApp() {
25:   const user = useAuthStore((state) => state.user);
26:   const logoutRemote = useAuthStore((state) => state.logoutRemote);
27:   const readRoute = () => window.location.hash.replace(/^#/, '').split('?')[0]
28:     || window.location.pathname;
29:   const [route, setRoute] = useState(readRoute);
30:   const can = useCallback((permission: string) =>
31:     hasPermission(user?.permissions, permission), [user]);
32:   const cashierOnly = user?.roles.length === 1 && user.roles[0] === 'cashier';
33:   useEffect(() => {
34:     const changed = () => setRoute(readRoute());
35:     window.addEventListener('hashchange', changed);
36:     window.addEventListener('popstate', changed);
37:     return () => {
38:       window.removeEventListener('hashchange', changed);
39:       window.removeEventListener('popstate', changed);
40:     };
41:   }, []);
42:   useEffect(() => {
43:     if (cashierOnly && !['/', '/dashboard', '/pos'].includes(route)) window.location.replace('/dashboard');
44:     else if (!['/', '/dashboard', '/categories', '/dealers', '/production', '/pos'].includes(route) && !/^\/products(?:\/(?:new|[0-9]+))?$/.test(route) && !/^\/inventory(?:\/[a-z-]+)?$/.test(route)) window.location.replace('/dashboard');
45:   }, [cashierOnly, route]);
46:   if (cashierOnly && !['/', '/dashboard', '/pos'].includes(route)) return null;
47:   if (route === '/pos') return <PosPage />;
48:   const categoriesActive = route === '/categories';
49:   const inventoryActive = route === '/inventory' || route.startsWith('/inventory/');
50:   const catalogActive = inventoryActive ? 'inventory' : route.startsWith('/products') ? 'products' : route === '/dealers' ? 'dealers' : route === '/production' ? 'production' : null;
51:   return <FinancialDashboard
52:     onLogout={logoutRemote}
53:     catalogActive={catalogActive}
54:     catalogPage={inventoryActive ? (can('inventory.view') ? <Suspense fallback={<div dir="rtl" className="p-6">جارٍ تحميل المخزون…</div>}><InventoryMockPage can={can}/></Suspense> : <div dir="rtl" className="p-6">ليس لديك صلاحية عرض المخزون.</div>) : catalogActive && <CatalogMockPage key={catalogActive} can={can} page={catalogActive} />}
55:     catalogNav={!cashierOnly ? [
56:       ...(can('inventory.view') ? [{ id: 'inventory', label: 'المخزون', onOpen: () => { window.location.hash = '/inventory/stock'; } }] : []),
57:       ...(can('products.view') ? [{ id: 'products', label: 'المنتجات', onOpen: () => { window.location.hash = '/products'; } }] : []),
58:       ...(can('customers.view') ? [{ id: 'dealers', label: 'التجار والموزعون', onOpen: () => { window.location.hash = '/dealers'; } }] : []),
59:       ...(can('inventory.view') ? [{ id: 'production', label: 'استلام الإنتاج', onOpen: () => { window.location.hash = '/production'; } }] : []),
60:     ] : []}
61:     onCloseCatalog={() => { window.location.hash = '/dashboard'; }}
62:     categoriesActive={categoriesActive}
63:     categoriesPage={<CategoriesMockPage can={can} embedded />}
64:     onOpenCategories={!cashierOnly && can('categories.view')
65:       ? () => { window.location.hash = '/categories'; }
66:       : undefined}
67:     onCloseCategories={() => { window.location.hash = '/dashboard'; }}
68:   />;
69: }
